-- ── José L. Piedra ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('José L. Piedra occupe une place que le reste du portefeuille laisse vide : celle du cigare cubain de tous les jours, vendu au prix d''un paquet de cigarettes, et assumé comme tel.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'José L. Piedra occupe une place que le reste du portefeuille laisse vide : celle du cigare cubain de tous les jours, vendu au prix d''un paquet de cigarettes, et assumé comme tel.', 'En octobre 2026, habanos.com range José L. Piedra, avec Quintero et Vegueros, parmi les trois marques dites de volume de son portefeuille.'), `history`),
  `history_en` = IF(LOCATE(CAST('José L. Piedra occupies a place the rest of the portfolio leaves empty: that of the everyday Cuban cigar, sold for the price of a packet of cigarettes, and owned as such.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'José L. Piedra occupies a place the rest of the portfolio leaves empty: that of the everyday Cuban cigar, sold for the price of a packet of cigarettes, and owned as such.', 'In October 2026, habanos.com lists José L. Piedra, with Quintero and Vegueros, among the three so-called volume brands of its portfolio.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('José L. Piedra ocupa un lugar que el resto del portafolio deja vacío: el del cigarro cubano de todos los días, vendido al precio de una cajetilla de cigarrillos, y asumido como tal.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'José L. Piedra ocupa un lugar que el resto del portafolio deja vacío: el del cigarro cubano de todos los días, vendido al precio de una cajetilla de cigarrillos, y asumido como tal.', 'En octubre de 2026, habanos.com clasifica José L. Piedra, con Quintero y Vegueros, entre las tres marcas llamadas de volumen de su portafolio.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('José L. Piedra besetzt einen Platz, den der Rest des Sortiments leer lässt: den der kubanischen Alltagszigarre, verkauft zum Preis einer Schachtel Zigaretten, und dazu bekennt sie sich.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'José L. Piedra besetzt einen Platz, den der Rest des Sortiments leer lässt: den der kubanischen Alltagszigarre, verkauft zum Preis einer Schachtel Zigaretten, und dazu bekennt sie sich.', 'Im Oktober 2026 führt habanos.com José L. Piedra zusammen mit Quintero und Vegueros unter den drei sogenannten Volumenmarken seines Portfolios.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('何塞·L. 皮埃德拉占据着整个产品序列留空的一个位置：古巴人的日常雪茄，售价相当于一包香烟，而且坦然如此。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '何塞·L. 皮埃德拉占据着整个产品序列留空的一个位置：古巴人的日常雪茄，售价相当于一包香烟，而且坦然如此。', '2026年10月，habanos.com 把 José L. Piedra 与 Quintero、Vegueros 一起列为其品牌组合中的三个所谓量产品牌。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تشغل «خوسيه ل. بييدرا» موقعاً تتركه بقية المحفظة فارغاً: موقع السيجار الكوبي اليومي، الذي يُباع بثمن علبة سجائر، ويعترف بذلك.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تشغل «خوسيه ل. بييدرا» موقعاً تتركه بقية المحفظة فارغاً: موقع السيجار الكوبي اليومي، الذي يُباع بثمن علبة سجائر، ويعترف بذلك.', 'في أكتوبر 2026 تصنّف habanos.com علامة José L. Piedra، مع Quintero وVegueros، ضمن ثلاث علامات تسمّيها علامات الحجم في محفظتها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'José L. Piedra';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La marque vient de la région de Villa Clara, dans le centre de l''île, et non de la Vuelta Abajo. Ses feuilles sont plus rustiques, son roulage est différent — la tripe est faite de feuilles entières mais l''exécution reste volontairement simple —, et la présentation se limite souvent à des paquets de cinq ou à des boîtes sans habillage.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La marque vient de la région de Villa Clara, dans le centre de l''île, et non de la Vuelta Abajo. Ses feuilles sont plus rustiques, son roulage est différent — la tripe est faite de feuilles entières mais l''exécution reste volontairement simple —, et la présentation se limite souvent à des paquets de cinq ou à des boîtes sans habillage.', 'Habanos rattache la marque à la famille Piedra, venue des Asturies dans les années 1880 et installée près de Santa Clara, au cœur de la région de Remedios, où le tabac se cultive depuis le XVIe siècle. Selon habanos.com, les sept formats sont faits de tabacs de Remedios, entièrement à la main en tripe courte (tripa corta). La maison présente une image plus moderne ; le Petit Caballeros l''adopte déjà, en paquet de douze et en présentoir de quinze étuis de trois cigares.'), `history`),
  `history_en` = IF(LOCATE(CAST('The brand comes from the Villa Clara region, in the centre of the island, and not from the Vuelta Abajo. Its leaves are more rustic, its rolling different — the filler is made of whole leaves but the execution stays deliberately simple — and the presentation often amounts to packs of five or boxes without dressing.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The brand comes from the Villa Clara region, in the centre of the island, and not from the Vuelta Abajo. Its leaves are more rustic, its rolling different — the filler is made of whole leaves but the execution stays deliberately simple — and the presentation often amounts to packs of five or boxes without dressing.', 'Habanos links the brand to the Piedra family, who came from Asturias in the 1880s and settled near Santa Clara, in the heart of the Remedios region, where tobacco has been grown since the sixteenth century. According to habanos.com, the seven formats are made of Remedios tobaccos, entirely by hand in short filler (tripa corta). The house presents a more modern image; the Petit Caballeros already adopts it, in a pack of twelve and in a display of fifteen sleeves of three cigars.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La marca viene de la región de Villa Clara, en el centro de la isla, y no de la Vuelta Abajo. Sus hojas son más rústicas, su liado distinto — la tripa se hace de hojas enteras pero la ejecución sigue siendo deliberadamente simple — y la presentación se limita a menudo a paquetes de cinco o a cajas sin adorno.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La marca viene de la región de Villa Clara, en el centro de la isla, y no de la Vuelta Abajo. Sus hojas son más rústicas, su liado distinto — la tripa se hace de hojas enteras pero la ejecución sigue siendo deliberadamente simple — y la presentación se limita a menudo a paquetes de cinco o a cajas sin adorno.', 'Habanos vincula la marca con la familia Piedra, llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, en el corazón de la región de Remedios, donde el tabaco se cultiva desde el siglo XVI. Según habanos.com, los siete formatos están hechos con tabacos de Remedios, enteramente a mano en tripa corta. La casa presenta una imagen más moderna; el Petit Caballeros ya la adopta, en paquete de doce y en expositor de quince estuches de tres puros.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Marke stammt aus der Region Villa Clara im Zentrum der Insel und nicht aus der Vuelta Abajo. Ihre Blätter sind rustikaler, ihre Rollart anders — die Einlage besteht aus ganzen Blättern, doch die Ausführung bleibt bewusst einfach —, und die Aufmachung beschränkt sich oft auf Fünferpackungen oder Kisten ohne Ausstattung.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Marke stammt aus der Region Villa Clara im Zentrum der Insel und nicht aus der Vuelta Abajo. Ihre Blätter sind rustikaler, ihre Rollart anders — die Einlage besteht aus ganzen Blättern, doch die Ausführung bleibt bewusst einfach —, und die Aufmachung beschränkt sich oft auf Fünferpackungen oder Kisten ohne Ausstattung.', 'Habanos verbindet die Marke mit der Familie Piedra, die in den 1880er Jahren aus Asturien kam und sich bei Santa Clara niederließ, im Herzen der Region Remedios, wo seit dem 16. Jahrhundert Tabak angebaut wird. Laut habanos.com bestehen die sieben Formate aus Remedios-Tabaken, vollständig von Hand gerollt, mit kurzer Einlage (tripa corta). Das Haus zeigt ein moderneres Bild; das Petit Caballeros übernimmt es bereits, in einer Packung zu zwölf und in einem Aufsteller mit fünfzehn Etuis zu je drei Zigarren.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这个品牌来自岛屿中部的比亚克拉拉地区，而不是阿巴霍谷。它的烟叶更粗犷，卷法也不同——茄芯用的是整叶，但工序刻意保持简单——包装往往只是五支一包，或是不加装饰的盒子。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这个品牌来自岛屿中部的比亚克拉拉地区，而不是阿巴霍谷。它的烟叶更粗犷，卷法也不同——茄芯用的是整叶，但工序刻意保持简单——包装往往只是五支一包，或是不加装饰的盒子。', 'Habanos 把该品牌与皮耶德拉家族联系起来：该家族1880年代从阿斯图里亚斯而来，定居在圣克拉拉附近，位于雷梅迪奥斯地区的中心，那里自十六世纪起种植烟草。据 habanos.com，七个尺寸均以雷梅迪奥斯烟叶制成，全部手工卷制，采用短茄芯（tripa corta）。品牌方展示出更现代的形象；Petit Caballeros 已采用这一形象，为十二支一包，以及陈列架上十五个三支装的小盒。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تأتي العلامة من منطقة ڤيّا كلارا، وسط الجزيرة، لا من ڤويلتا أباخو. أوراقها أخشن، ولفّها مختلف — الحشوة من أوراق كاملة لكن التنفيذ يبقى بسيطاً عن قصد — ويقتصر العرض غالباً على عبوات من خمس قطع أو صناديق بلا زينة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تأتي العلامة من منطقة ڤيّا كلارا، وسط الجزيرة، لا من ڤويلتا أباخو. أوراقها أخشن، ولفّها مختلف — الحشوة من أوراق كاملة لكن التنفيذ يبقى بسيطاً عن قصد — ويقتصر العرض غالباً على عبوات من خمس قطع أو صناديق بلا زينة.', 'تربط Habanos العلامة بعائلة بييدرا، التي جاءت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، في قلب منطقة ريميديوس، حيث يُزرع التبغ منذ القرن السادس عشر. بحسب habanos.com، المقاسات السبعة مصنوعة من تبغ ريميديوس، ملفوفة يدويًا بالكامل بحشوة قصيرة (tripa corta). وتقدّم الدار صورة أحدث؛ ويعتمدها Petit Caballeros بالفعل، في عبوة من اثنتي عشرة قطعة وفي حامل عرض من خمسة عشر علبة صغيرة من ثلاث سيجارات.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'José L. Piedra';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le profil s''en ressent, et c''est là tout l''intérêt : terreux, franc, un peu sauvage, avec une force médium qui ne cherche aucune finesse. Ceux qui l''aiment y trouvent une authenticité que les grands assemblages, très travaillés, ont perdue ; ceux qui ne l''aiment pas lui reprochent exactement la même chose.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le profil s''en ressent, et c''est là tout l''intérêt : terreux, franc, un peu sauvage, avec une force médium qui ne cherche aucune finesse. Ceux qui l''aiment y trouvent une authenticité que les grands assemblages, très travaillés, ont perdue ; ceux qui ne l''aiment pas lui reprochent exactement la même chose.', 'Habanos donne la force comme moyenne à corsée.'), `history`),
  `history_en` = IF(LOCATE(CAST('The profile shows it, and that is the whole point: earthy, frank, a little wild, with a medium strength that seeks no finesse. Those who love it find an authenticity that the great, highly worked blends have lost; those who do not love it reproach it for exactly the same thing.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The profile shows it, and that is the whole point: earthy, frank, a little wild, with a medium strength that seeks no finesse. Those who love it find an authenticity that the great, highly worked blends have lost; those who do not love it reproach it for exactly the same thing.', 'Habanos gives the strength as medium to full.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El perfil lo refleja, y ahí está todo el interés: terroso, franco, un poco salvaje, con una fuerza media que no busca ninguna finura. Quienes lo aman encuentran en él una autenticidad que las grandes ligas, muy trabajadas, han perdido; quienes no lo aman le reprochan exactamente lo mismo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El perfil lo refleja, y ahí está todo el interés: terroso, franco, un poco salvaje, con una fuerza media que no busca ninguna finura. Quienes lo aman encuentran en él una autenticidad que las grandes ligas, muy trabajadas, han perdido; quienes no lo aman le reprochan exactamente lo mismo.', 'Habanos da la fuerza como media a fuerte.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Profil zeigt es, und darin liegt der ganze Reiz: erdig, offen, ein wenig wild, mit mittlerer Kraft, die keine Finesse sucht. Wer sie liebt, findet eine Echtheit, die den großen, stark bearbeiteten Blends abhandengekommen ist; wer sie nicht liebt, wirft ihr genau dasselbe vor.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Profil zeigt es, und darin liegt der ganze Reiz: erdig, offen, ein wenig wild, mit mittlerer Kraft, die keine Finesse sucht. Wer sie liebt, findet eine Echtheit, die den großen, stark bearbeiteten Blends abhandengekommen ist; wer sie nicht liebt, wirft ihr genau dasselbe vor.', 'Habanos gibt die Stärke als mittel bis kräftig an.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('风格也随之而来，而这正是关键所在：带土味、直率、有点野，中等力度，不追求任何细腻。喜欢它的人在其中找到了那些精雕细琢的大配方已经失去的真实；不喜欢它的人，指责的恰恰是同一件事。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '风格也随之而来，而这正是关键所在：带土味、直率、有点野，中等力度，不追求任何细腻。喜欢它的人在其中找到了那些精雕细琢的大配方已经失去的真实；不喜欢它的人，指责的恰恰是同一件事。', 'Habanos 给出的力度为中等至浓郁。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ويظهر ذلك في الطابع، وفيه تكمن الفائدة كلّها: ترابي، صريح، متوحّش قليلاً، بقوّة متوسطة لا تبحث عن أي رهافة. من يحبّونه يجدون فيه أصالةً فقدتها الخلطات الكبرى شديدة الصنعة؛ ومن لا يحبّونه يعيبون عليه الشيء نفسه تماماً.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ويظهر ذلك في الطابع، وفيه تكمن الفائدة كلّها: ترابي، صريح، متوحّش قليلاً، بقوّة متوسطة لا تبحث عن أي رهافة. من يحبّونه يجدون فيه أصالةً فقدتها الخلطات الكبرى شديدة الصنعة؛ ومن لا يحبّونه يعيبون عليه الشيء نفسه تماماً.', 'تذكر Habanos أن القوة متوسطة إلى شديدة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'José L. Piedra';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('C''est, dans les faits, le cigare le plus fumé à Cuba, très loin devant les marques qui font la réputation de l''île à l''étranger. À ce titre, il en dit davantage sur le pays réel que n''importe quelle boîte vernie.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'C''est, dans les faits, le cigare le plus fumé à Cuba, très loin devant les marques qui font la réputation de l''île à l''étranger. À ce titre, il en dit davantage sur le pays réel que n''importe quelle boîte vernie.', 'Des détaillants datent la marque des années 1880, la disent retirée au début des années 1990 puis relancée en 1996 (Puroexpress, Cigar Keep) ; habanos.com ne donne aucune de ces dates.'), `history`),
  `history_en` = IF(LOCATE(CAST('It is, in fact, the most smoked cigar in Cuba, far ahead of the brands that make the island''s reputation abroad. On that count it says more about the real country than any varnished box.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'It is, in fact, the most smoked cigar in Cuba, far ahead of the brands that make the island''s reputation abroad. On that count it says more about the real country than any varnished box.', 'Retailers date the brand to the 1880s and say it was withdrawn in the early 1990s and then relaunched in 1996 (Puroexpress, Cigar Keep); habanos.com gives none of these dates.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Es, de hecho, el cigarro más fumado en Cuba, muy por delante de las marcas que hacen la fama de la isla en el extranjero. Por eso dice más del país real que cualquier caja barnizada.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Es, de hecho, el cigarro más fumado en Cuba, muy por delante de las marcas que hacen la fama de la isla en el extranjero. Por eso dice más del país real que cualquier caja barnizada.', 'Minoristas fechan la marca en los años 1880, la dicen retirada a comienzos de los años 1990 y luego relanzada en 1996 (Puroexpress, Cigar Keep); habanos.com no da ninguna de estas fechas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Sie ist faktisch die meistgerauchte Zigarre Kubas, weit vor den Marken, die den Ruf der Insel im Ausland begründen. Insofern sagt sie mehr über das wirkliche Land aus als jede lackierte Kiste.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Sie ist faktisch die meistgerauchte Zigarre Kubas, weit vor den Marken, die den Ruf der Insel im Ausland begründen. Insofern sagt sie mehr über das wirkliche Land aus als jede lackierte Kiste.', 'Händler datieren die Marke auf die 1880er Jahre und sagen, sie sei Anfang der 1990er Jahre vom Markt genommen und 1996 neu aufgelegt worden (Puroexpress, Cigar Keep); habanos.com nennt keines dieser Daten.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('事实上，它是古巴境内被抽得最多的雪茄，远远超过那些为这座岛屿赢得国际声誉的品牌。就此而言，它比任何一只上漆的木盒都更能说明这个国家的真实模样。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '事实上，它是古巴境内被抽得最多的雪茄，远远超过那些为这座岛屿赢得国际声誉的品牌。就此而言，它比任何一只上漆的木盒都更能说明这个国家的真实模样。', '一些零售商把该品牌定在1880年代，称其在1990年代初被撤下，1996年重新推出（Puroexpress、Cigar Keep）；habanos.com 没有给出其中任何一个日期。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وهو في الواقع السيجار الأكثر تدخيناً في كوبا، متقدّماً بفارق كبير على العلامات التي تصنع سمعة الجزيرة في الخارج. وبهذا المعنى يقول عن البلد الحقيقي أكثر مما يقوله أي صندوق مطليّ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وهو في الواقع السيجار الأكثر تدخيناً في كوبا، متقدّماً بفارق كبير على العلامات التي تصنع سمعة الجزيرة في الخارج. وبهذا المعنى يقول عن البلد الحقيقي أكثر مما يقوله أي صندوق مطليّ.', 'يؤرّخ بعض تجّار التجزئة العلامة بثمانينيات القرن التاسع عشر، ويقولون إنها سُحبت في مطلع التسعينيات ثم أُعيد إطلاقها سنة 1996 (Puroexpress وCigar Keep)؛ ولا تذكر habanos.com أيًّا من هذه التواريخ.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'José L. Piedra';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est une fabrique provinciale de Holguín, dans l''est de l''île — loin de la Vuelta Abajo, dont elle n''utilise pas le tabac. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle dit la famille Piedra arrivée des Asturies dans les années 1880 et installée près de Santa Clara, et la marque fondée par la deuxième génération, José Lamadrid Piedra. Toute la gamme est en tripe courte roulée main, avec le seul tabac de Remedios.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est une fabrique provinciale de Holguín, dans l''est de l''île — loin de la Vuelta Abajo, dont elle n''utilise pas le tabac. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle dit la famille Piedra arrivée des Asturies dans les années 1880 et installée près de Santa Clara, et la marque fondée par la deuxième génération, José Lamadrid Piedra. Toute la gamme est en tripe courte roulée main, avec le seul tabac de Remedios.', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos.com ne nomme aucune fabrique pour la marque ; un détaillant (Puroexpress) place la production à Santa Clara. En octobre 2026, habanos.com range José L. Piedra, Quintero et Vegueros parmi les trois marques de volume de ses vingt-sept marques ; la presse du métier annonçait ce groupe le 1er août 2019, pour un portefeuille alors de vingt et une marques. La page officielle dit la famille Piedra arrivée des Asturies dans les années 1880 et installée près de Santa Clara, et la marque fondée par la deuxième génération, José Lamadrid Piedra. Toute la gamme est en tripe courte roulée main, avec le seul tabac de Remedios.'), `history`),
  `history_en` = IF(LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is a provincial factory in Holguín, in the east of the island — far from the Vuelta Abajo, whose tobacco it does not use. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page has the Piedra family arriving from Asturias in the 1880s and settling near Santa Clara, and the brand founded by the second generation, José Lamadrid Piedra. The whole range is hand-rolled short filler, with Remedios tobacco only.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is a provincial factory in Holguín, in the east of the island — far from the Vuelta Abajo, whose tobacco it does not use. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page has the Piedra family arriving from Asturias in the 1880s and settling near Santa Clara, and the brand founded by the second generation, José Lamadrid Piedra. The whole range is hand-rolled short filler, with Remedios tobacco only.', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos.com names no factory for the brand; a retailer (Puroexpress) places production in Santa Clara. In October 2026, habanos.com lists José L. Piedra, Quintero and Vegueros among the three volume brands of its twenty-seven brands; the trade press announced this group on 1 August 2019, for a portfolio then of twenty-one brands. The official page has the Piedra family arriving from Asturias in the 1880s and settling near Santa Clara, and the brand founded by the second generation, José Lamadrid Piedra. The whole range is hand-rolled short filler, with Remedios tobacco only.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es una fábrica provincial de Holguín, en el este de la isla — lejos de la Vuelta Abajo, cuyo tabaco no usa. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial dice la familia Piedra llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, y la marca fundada por la segunda generación, José Lamadrid Piedra. Toda la gama es tripa corta liada a mano, solo con tabaco de Remedios.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es una fábrica provincial de Holguín, en el este de la isla — lejos de la Vuelta Abajo, cuyo tabaco no usa. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial dice la familia Piedra llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, y la marca fundada por la segunda generación, José Lamadrid Piedra. Toda la gama es tripa corta liada a mano, solo con tabaco de Remedios.', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos.com no nombra ninguna fábrica para la marca; un minorista (Puroexpress) sitúa la producción en Santa Clara. En octubre de 2026, habanos.com clasifica José L. Piedra, Quintero y Vegueros entre las tres marcas de volumen de sus veintisiete marcas; la prensa del oficio anunciaba este grupo el 1 de agosto de 2019, para un portafolio entonces de veintiuna marcas. La página oficial dice la familia Piedra llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, y la marca fundada por la segunda generación, José Lamadrid Piedra. Toda la gama es tripa corta liada a mano, solo con tabaco de Remedios.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist eine Provinzfabrik in Holguín im Osten der Insel — fern der Vuelta Abajo, deren Tabak sie nicht verwendet. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite lässt die Familie Piedra in den 1880er Jahren aus Asturien kommen und sich bei Santa Clara niederlassen, die Marke gegründet von der zweiten Generation, José Lamadrid Piedra. Die ganze Palette ist handgerollter Shortfiller, allein mit Remedios-Tabak.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist eine Provinzfabrik in Holguín im Osten der Insel — fern der Vuelta Abajo, deren Tabak sie nicht verwendet. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite lässt die Familie Piedra in den 1880er Jahren aus Asturien kommen und sich bei Santa Clara niederlassen, die Marke gegründet von der zweiten Generation, José Lamadrid Piedra. Die ganze Palette ist handgerollter Shortfiller, allein mit Remedios-Tabak.', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos.com nennt für die Marke keine Fabrik; ein Händler (Puroexpress) verortet die Produktion in Santa Clara. Im Oktober 2026 führt habanos.com José L. Piedra, Quintero und Vegueros unter den drei Volumenmarken seiner siebenundzwanzig Marken; die Fachpresse kündigte diese Gruppe am 1. August 2019 an, bei einem Portfolio von damals einundzwanzig Marken. Die offizielle Seite lässt die Familie Piedra in den 1880er Jahren aus Asturien kommen und sich bei Santa Clara niederlassen, die Marke gegründet von der zweiten Generation, José Lamadrid Piedra. Die ganze Palette ist handgerollter Shortfiller, allein mit Remedios-Tabak.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是岛东部奥尔金的一家省属工厂——远离下维尔塔，也不用那里的烟叶。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面说皮耶德拉家族1880年代从阿斯图里亚斯来到古巴，定居在圣克拉拉附近，品牌由第二代何塞·拉马德里德·皮耶德拉创立。全系列为手工短茄芯，只用雷梅迪奥斯烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是岛东部奥尔金的一家省属工厂——远离下维尔塔，也不用那里的烟叶。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面说皮耶德拉家族1880年代从阿斯图里亚斯来到古巴，定居在圣克拉拉附近，品牌由第二代何塞·拉马德里德·皮耶德拉创立。全系列为手工短茄芯，只用雷梅迪奥斯烟叶。', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。habanos.com 没有为该品牌点出任何工厂；一家零售商（Puroexpress）把生产定在圣克拉拉。2026年10月，habanos.com 把 José L. Piedra、Quintero 与 Vegueros 列为其二十七个品牌中的三个量产品牌；行业媒体于2019年8月1日宣布了这一组合，当时的品牌组合为二十一个品牌。官方页面说皮耶德拉家族1880年代从阿斯图里亚斯来到古巴，定居在圣克拉拉附近，品牌由第二代何塞·拉马德里德·皮耶德拉创立。全系列为手工短茄芯，只用雷梅迪奥斯烟叶。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ مصنع إقليمي في هولغين شرق الجزيرة — بعيدًا عن فويلتا أباخو التي لا تستعمل تبغها. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. تقول الصفحة الرسمية إنّ عائلة بييدرا وصلت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، وإنّ العلامة أسّسها الجيل الثاني، خوسيه لامادريد بييدرا. والمجموعة كلّها حشوة قصيرة ملفوفة يدويًّا بتبغ ريميديوس وحده.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ مصنع إقليمي في هولغين شرق الجزيرة — بعيدًا عن فويلتا أباخو التي لا تستعمل تبغها. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. تقول الصفحة الرسمية إنّ عائلة بييدرا وصلت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، وإنّ العلامة أسّسها الجيل الثاني، خوسيه لامادريد بييدرا. والمجموعة كلّها حشوة قصيرة ملفوفة يدويًّا بتبغ ريميديوس وحده.', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي habanos.com أي مصنع للعلامة؛ ويضع أحد تجّار التجزئة (Puroexpress) الإنتاج في سانتا كلارا. في أكتوبر 2026 تصنّف habanos.com علامات José L. Piedra وQuintero وVegueros ضمن علامات الحجم الثلاث من علاماتها السبع والعشرين؛ وأعلنت الصحافة المتخصّصة هذه المجموعة في 1 أغسطس 2019، لمحفظة كانت حينها من إحدى وعشرين علامة. تقول الصفحة الرسمية إنّ عائلة بييدرا وصلت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، وإنّ العلامة أسّسها الجيل الثاني، خوسيه لامادريد بييدرا. والمجموعة كلّها حشوة قصيرة ملفوفة يدويًّا بتبغ ريميديوس وحده.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'José L. Piedra';

UPDATE `brands` SET
  `factory` = 'Fabrique non nommée par habanos.com ; Santa Clara selon un détaillant ; tripe courte de Remedios, roulée main (habanos.com)',
  `gamme` = '[{"name":"Petit Cazadores","color":"#8B4513","force":"Medium-Full","story":"Selon un détaillant (Puroexpress), 105 mm pour un cepo de 43. Habanos ne donne aucune dimension pour les sept formats de la marque, tous faits de tabacs de Remedios en tripe courte.","vitolas":["Petit Cazadores"],"wrapper":"Tabac de Remedios"},{"name":"Conservas","color":"#A0522D","force":"Medium-Full","story":"Selon deux détaillants (Puroexpress, Cigar Keep), 140 mm pour un cepo de 44. Même tabac de Remedios, même tripe courte roulée main.","vitolas":["Conservas"],"wrapper":"Tabac de Remedios"}]',
  `gamme_en` = '[{"name":"Petit Cazadores","color":"#8B4513","force":"Medium-Full","story":"According to a retailer (Puroexpress), 105 mm for a ring gauge of 43. Habanos gives no dimensions for the brand''s seven formats, all made with Remedios tobaccos in short filler.","vitolas":["Petit Cazadores"],"wrapper":"Remedios tobacco"},{"name":"Conservas","color":"#A0522D","force":"Medium-Full","story":"According to two retailers (Puroexpress, Cigar Keep), 140 mm for a ring gauge of 44. Same Remedios tobacco, same hand-rolled short filler.","vitolas":["Conservas"],"wrapper":"Remedios tobacco"}]',
  `gamme_es` = '[{"name":"Petit Cazadores","color":"#8B4513","force":"Medium-Full","story":"Según un minorista (Puroexpress), 105 mm para un cepo de 43. Habanos no da ninguna dimensión para los siete formatos de la marca, todos hechos con tabacos de Remedios en tripa corta.","vitolas":["Petit Cazadores"],"wrapper":"Tabaco de Remedios"},{"name":"Conservas","color":"#A0522D","force":"Medium-Full","story":"Según dos minoristas (Puroexpress, Cigar Keep), 140 mm para un cepo de 44. Mismo tabaco de Remedios, misma tripa corta liada a mano.","vitolas":["Conservas"],"wrapper":"Tabaco de Remedios"}]',
  `gamme_de` = '[{"name":"Petit Cazadores","color":"#8B4513","force":"Medium-Full","story":"Laut einem Händler (Puroexpress) 105 mm bei einem Ringmaß von 43. Habanos nennt keine Maße für die sieben Formate der Marke, die alle aus Remedios-Tabaken in kurzer Einlage (tripa corta) gefertigt sind.","vitolas":["Petit Cazadores"],"wrapper":"Remedios-Tabak"},{"name":"Conservas","color":"#A0522D","force":"Medium-Full","story":"Laut zwei Händlern (Puroexpress, Cigar Keep) 140 mm bei einem Ringmaß von 44. Derselbe Remedios-Tabak, dieselbe handgerollte kurze Einlage.","vitolas":["Conservas"],"wrapper":"Remedios-Tabak"}]',
  `gamme_zh` = '[{"name":"Petit Cazadores","color":"#8B4513","force":"Medium-Full","story":"据一家零售商（Puroexpress），长105 mm，环径43。Habanos 未给出该品牌七个尺寸的任何规格，七款均以雷梅迪奥斯烟叶、短茄芯制成。","vitolas":["Petit Cazadores"],"wrapper":"雷梅迪奥斯烟叶"},{"name":"Conservas","color":"#A0522D","force":"Medium-Full","story":"据两家零售商（Puroexpress、Cigar Keep），长140 mm，环径44。同样的雷梅迪奥斯烟叶，同样手工卷制的短茄芯。","vitolas":["Conservas"],"wrapper":"雷梅迪奥斯烟叶"}]',
  `gamme_ar` = '[{"name":"Petit Cazadores","color":"#8B4513","force":"Medium-Full","story":"بحسب أحد تجّار التجزئة (Puroexpress)، 105 mm لقياس قطر 43. ولا تذكر Habanos أي أبعاد للمقاسات السبعة للعلامة، وكلّها من تبغ ريميديوس بحشوة قصيرة.","vitolas":["Petit Cazadores"],"wrapper":"تبغ ريميديوس"},{"name":"Conservas","color":"#A0522D","force":"Medium-Full","story":"بحسب تاجرَي تجزئة (Puroexpress وCigar Keep)، 140 mm لقياس قطر 44. تبغ ريميديوس نفسه، وحشوة قصيرة ملفوفة يدويًا نفسها.","vitolas":["Conservas"],"wrapper":"تبغ ريميديوس"}]',
  `pairings` = '[{"type":"Café","name":"Café de rue cubain","notes":"Suggestion de dégustation, sans page."},{"type":"Bière","name":"Lager glacée","notes":"Suggestion de dégustation, sans page."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Cuban street coffee","notes":"Tasting suggestion, no page."},{"type":"Beer","name":"Ice-cold lager","notes":"Tasting suggestion, no page."}]',
  `pairings_es` = '[{"type":"Café","name":"Café cubano de calle","notes":"Sugerencia de cata, sin página."},{"type":"Cerveza","name":"Lager helada","notes":"Sugerencia de cata, sin página."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Kubanischer Straßenkaffee","notes":"Verkostungsvorschlag, ohne Seite."},{"type":"Bier","name":"Eisgekühltes Lager","notes":"Verkostungsvorschlag, ohne Seite."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"古巴街头咖啡","notes":"品鉴建议，无对应页面。"},{"type":"啤酒","name":"冰镇拉格","notes":"品鉴建议，无对应页面。"}]',
  `pairings_ar` = '[{"type":"قهوة","name":"قهوة الشارع الكوبية","notes":"اقتراح تذوّق، بلا صفحة."},{"type":"بيرة","name":"لاغر مثلّجة","notes":"اقتراح تذوّق، بلا صفحة."}]',
  `source` = IF(LOCATE(CAST('cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique provinciale de Holguín mère de José L. Piedra ; Remedios, Vuelta Arriba, source de toutes ses feuilles) ; ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique provinciale de Holguín mère de José L. Piedra ; Remedios, Vuelta Arriba, source de toutes ses feuilles) ; ', ''), `source`),
  `source` = IF(LOCATE(CAST('habanos.com « José L. Piedra Brand » (page sans date, lue le' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'habanos.com « José L. Piedra Brand » (page sans date, lue le 16 octobre 2026, versions anglaise et espagnole : tabacs de Remedios, tripa corta, force moyenne à corsée, aucune fabrique, aucune dimension) ; blog.puroexpress.com « All you ever need to know about Jose L. Piedra Brand Cigars » (détaillant, page sans date : années 1880, arrêt début 1990, relance 1996, Santa Clara, Petit Cazadores 105 mm cepo 43, Conservas 140 mm cepo 44) ; cigar-keep.com « José L. Piedra: A Testament to Cuban Cigar Craftsmanship » (détaillant, page sans date : revitalisation en 1996, tripes de Remedios, Conservas 140 mm) ; habanos.com « The Habanos Brands Academia » (octobre 2026 : marque de volume)')),
  `updated_at` = NOW()
 WHERE `name` = 'José L. Piedra';

-- ── Quintero ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Quintero est le secret le mieux gardé du portefeuille Habanos. Fondée en 1924 à Cienfuegos par Agustín Quintero Benítez, la manufacture produisit pendant des décennies des cigares destinés presque exclusivement au marché espagnol — pays qui noua avec Quintero une relation de fidélité comparable à celle des Britanniques avec Romeo y Julieta.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Quintero est le secret le mieux gardé du portefeuille Habanos. Fondée en 1924 à Cienfuegos par Agustín Quintero Benítez, la manufacture produisit pendant des décennies des cigares destinés presque exclusivement au marché espagnol — pays qui noua avec Quintero une relation de fidélité comparable à celle des Britanniques avec Romeo y Julieta.', 'Quintero est l''une des rares marques de Habanos qui ne soient pas nées à La Havane. Son fondateur, Agustín Quintero, s''est installé à Cienfuegos, la perle du Sud, dit habanos.com, qui ne date pas la marque. Selon Wikipédia, elle naît en 1924 sous le nom de Quintero y Hermanos, quand Agustín et quatre frères ouvrent une petite fabrique à Cienfuegos ; un détaillant britannique donne aussi 1924, avec un « believed ».'), `history`),
  `history_en` = IF(LOCATE(CAST('Quintero is the best-kept secret of the Habanos portfolio. Founded in 1924 in Cienfuegos by Agustín Quintero Benítez, the manufacture produced for decades cigars destined almost exclusively for the Spanish market — a country that developed with Quintero a relationship of fidelity comparable to the British relationship with Romeo y Julieta.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Quintero is the best-kept secret of the Habanos portfolio. Founded in 1924 in Cienfuegos by Agustín Quintero Benítez, the manufacture produced for decades cigars destined almost exclusively for the Spanish market — a country that developed with Quintero a relationship of fidelity comparable to the British relationship with Romeo y Julieta.', 'Quintero is one of the few Habanos brands not born in Havana. Its founder, Agustín Quintero, settled in Cienfuegos, the pearl of the South, says habanos.com, which does not date the brand. According to Wikipedia, it began in 1924 as Quintero y Hermanos, when Agustín and four brothers opened a small factory in Cienfuegos; a British retailer also gives 1924, with a “believed”.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Quintero es el secreto mejor guardado del catálogo de Habanos. Fundada en 1924 en Cienfuegos por Agustín Quintero Benítez, la manufactura produjo durante décadas puros destinados casi en exclusiva al mercado español, país que trabó con Quintero una relación de fidelidad comparable a la de los británicos con Romeo y Julieta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Quintero es el secreto mejor guardado del catálogo de Habanos. Fundada en 1924 en Cienfuegos por Agustín Quintero Benítez, la manufactura produjo durante décadas puros destinados casi en exclusiva al mercado español, país que trabó con Quintero una relación de fidelidad comparable a la de los británicos con Romeo y Julieta.', 'Quintero es una de las pocas marcas de Habanos que no nacieron en La Habana. Su fundador, Agustín Quintero, se instaló en Cienfuegos, la perla del Sur, dice habanos.com, que no fecha la marca. Según Wikipedia, nace en 1924 con el nombre de Quintero y Hermanos, cuando Agustín y cuatro hermanos abren una pequeña fábrica en Cienfuegos; un minorista británico da también 1924, con un «believed».'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Quintero ist das bestgehütete Geheimnis des Habanos-Portfolios. 1924 in Cienfuegos von Agustín Quintero Benítez gegründet, stellte die Manufaktur jahrzehntelang Zigarren her, die fast ausschließlich für den spanischen Markt bestimmt waren — ein Land, das zu Quintero eine Treuebeziehung entwickelte, vergleichbar mit jener der Briten zu Romeo y Julieta.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Quintero ist das bestgehütete Geheimnis des Habanos-Portfolios. 1924 in Cienfuegos von Agustín Quintero Benítez gegründet, stellte die Manufaktur jahrzehntelang Zigarren her, die fast ausschließlich für den spanischen Markt bestimmt waren — ein Land, das zu Quintero eine Treuebeziehung entwickelte, vergleichbar mit jener der Briten zu Romeo y Julieta.', 'Quintero ist eine der wenigen Habanos-Marken, die nicht in Havanna entstanden sind. Ihr Gründer Agustín Quintero ließ sich in Cienfuegos nieder, der Perle des Südens, sagt habanos.com, das die Marke nicht datiert. Laut Wikipedia entsteht sie 1924 unter dem Namen Quintero y Hermanos, als Agustín und vier Brüder in Cienfuegos eine kleine Fabrik eröffnen; ein britischer Händler nennt ebenfalls 1924, mit einem „believed“.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Quintero 是 Habanos 旗下守得最严的秘密。1924 年由 Agustín Quintero Benítez 在 Cienfuegos 创立，这家工厂数十年间生产的雪茄几乎全部销往西班牙——西班牙与 Quintero 结下的忠诚，堪比英国人之于 Romeo y Julieta。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Quintero 是 Habanos 旗下守得最严的秘密。1924 年由 Agustín Quintero Benítez 在 Cienfuegos 创立，这家工厂数十年间生产的雪茄几乎全部销往西班牙——西班牙与 Quintero 结下的忠诚，堪比英国人之于 Romeo y Julieta。', 'Quintero 是 Habanos 少数并非诞生于哈瓦那的品牌之一。据 habanos.com 说，其创始人 Agustín Quintero 在南方的明珠 Cienfuegos 定居，该网站没有给品牌标注年份。据维基百科，它于1924年以 Quintero y Hermanos 之名诞生，当时 Agustín 与四位兄弟在 Cienfuegos 开了一家小工厂；一家英国零售商也给出1924年，并附有“believed”（据信）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('Quintero هي السرّ الأشدّ حفظاً في محفظة Habanos. تأسّست عام 1924 في Cienfuegos على يد Agustín Quintero Benítez، وظلّ المصنع عقوداً ينتج سيجاراً موجّهاً شبه حصرياً إلى السوق الإسبانية — وهي بلد نسج مع Quintero علاقة وفاء تشبه علاقة البريطانيين بـ Romeo y Julieta.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'Quintero هي السرّ الأشدّ حفظاً في محفظة Habanos. تأسّست عام 1924 في Cienfuegos على يد Agustín Quintero Benítez، وظلّ المصنع عقوداً ينتج سيجاراً موجّهاً شبه حصرياً إلى السوق الإسبانية — وهي بلد نسج مع Quintero علاقة وفاء تشبه علاقة البريطانيين بـ Romeo y Julieta.', 'Quintero من العلامات القليلة في Habanos التي لم تولد في هافانا. استقرّ مؤسسها Agustín Quintero في Cienfuegos، لؤلؤة الجنوب، بحسب habanos.com الذي لا يؤرّخ العلامة. وبحسب ويكيبيديا، وُلدت عام 1924 باسم Quintero y Hermanos، حين افتتح Agustín وأربعة إخوة مصنعًا صغيرًا في Cienfuegos؛ ويذكر تاجر تجزئة بريطاني 1924 أيضًا، مع عبارة «believed».'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Quintero';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''originalité de Quintero tient à sa provenance régionale. Contrairement aux grandes marques havanaises qui s''approvisionnent exclusivement en Vuelta Abajo occidental, Quintero utilisait historiquement des tabacs de Vuelta Arriba — les provinces orientales de Cuba — plus légères, plus herbacées, avec une signature aromatique distinctement différente du terroir occidental. Cette particularité créa un profil unique : cubain indéniablement, mais avec une légèreté et une herbosité que les amateurs de Partagás trouvaient déconcertantes, et que les amateurs de Quintero trouvaient irremplaçables.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''originalité de Quintero tient à sa provenance régionale. Contrairement aux grandes marques havanaises qui s''approvisionnent exclusivement en Vuelta Abajo occidental, Quintero utilisait historiquement des tabacs de Vuelta Arriba — les provinces orientales de Cuba — plus légères, plus herbacées, avec une signature aromatique distinctement différente du terroir occidental. Cette particularité créa un profil unique : cubain indéniablement, mais avec une légèreté et une herbosité que les amateurs de Partagás trouvaient déconcertantes, et que les amateurs de Quintero trouvaient irremplaçables.', 'Côté tabac, habanos.com écrit que tout le mélange de la marque vient de la zone de Vuelta Abajo, que la force est moyenne et que les cigares sont roulés totalement à la main, en tripe courte. Un reportage de la presse du métier (avril 2012) donne pour la cape les zones de Vuelta Abajo et de Semi Vuelta, à Pinar del Río, et un détaillant britannique cite les mêmes deux zones. La maison présente la marque comme une voie d''accès à la saveur du Habano, en force moyenne et à prix abordable.'), `history`),
  `history_en` = IF(LOCATE(CAST('Quintero''s originality lies in its regional provenance. Unlike the great Havana brands that source exclusively from western Vuelta Abajo, Quintero historically used tobaccos from Vuelta Arriba — the eastern provinces of Cuba — lighter, more herbaceous, with an aromatic signature distinctly different from the western terroir. This particularity created a unique profile: unmistakably Cuban, but with a lightness and herbaceousness that Partagás fans found disconcerting, and that Quintero enthusiasts found irreplaceable.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Quintero''s originality lies in its regional provenance. Unlike the great Havana brands that source exclusively from western Vuelta Abajo, Quintero historically used tobaccos from Vuelta Arriba — the eastern provinces of Cuba — lighter, more herbaceous, with an aromatic signature distinctly different from the western terroir. This particularity created a unique profile: unmistakably Cuban, but with a lightness and herbaceousness that Partagás fans found disconcerting, and that Quintero enthusiasts found irreplaceable.', 'As for the tobacco, habanos.com writes that the whole blend of the brand comes from the Vuelta Abajo zone, that the strength is medium and that the cigars are entirely hand-rolled, with short filler. A trade-press report (April 2012) gives the Vuelta Abajo and Semi Vuelta zones, in Pinar del Río, for the wrapper, and a British retailer names the same two zones. The house presents the brand as a way into the flavour of the Habano, at medium strength and an affordable price.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La originalidad de Quintero está en su procedencia regional. A diferencia de las grandes marcas habaneras, que se abastecen en exclusiva en la Vuelta Abajo occidental, Quintero empleaba históricamente tabacos de la Vuelta Arriba —las provincias orientales de Cuba—, más ligeros, más herbáceos, con una firma aromática claramente distinta del terruño occidental. Esa particularidad creó un perfil único: cubano sin discusión, pero con una ligereza y un carácter herbáceo que a los aficionados a Partagás desconcertaban y que a los de Quintero les resultaban insustituibles.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La originalidad de Quintero está en su procedencia regional. A diferencia de las grandes marcas habaneras, que se abastecen en exclusiva en la Vuelta Abajo occidental, Quintero empleaba históricamente tabacos de la Vuelta Arriba —las provincias orientales de Cuba—, más ligeros, más herbáceos, con una firma aromática claramente distinta del terruño occidental. Esa particularidad creó un perfil único: cubano sin discusión, pero con una ligereza y un carácter herbáceo que a los aficionados a Partagás desconcertaban y que a los de Quintero les resultaban insustituibles.', 'En cuanto al tabaco, habanos.com escribe que toda la liga de la marca procede de la zona de Vuelta Abajo, que la fuerza es media y que los puros se lían totalmente a mano, con tripa corta. Un reportaje de la prensa del oficio (abril de 2012) da para la capa las zonas de Vuelta Abajo y de Semi Vuelta, en Pinar del Río, y un minorista británico cita las mismas dos zonas. La casa presenta la marca como una vía de acceso al sabor del Habano, de fuerza media y a precio asequible.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Quinteros Eigenart liegt in ihrer regionalen Herkunft. Anders als die großen Havanna-Marken, die sich ausschließlich in der westlichen Vuelta Abajo eindecken, verwendete Quintero traditionell Tabake aus der Vuelta Arriba — den östlichen Provinzen Kubas —, leichter, krautiger, mit einer Aromatik, die sich deutlich vom westlichen Terroir unterscheidet. Daraus entstand ein einzigartiges Profil: unbestreitbar kubanisch, doch mit einer Leichtigkeit und Krautigkeit, die Partagás-Liebhaber befremdlich und Quintero-Liebhaber unersetzlich fanden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Quinteros Eigenart liegt in ihrer regionalen Herkunft. Anders als die großen Havanna-Marken, die sich ausschließlich in der westlichen Vuelta Abajo eindecken, verwendete Quintero traditionell Tabake aus der Vuelta Arriba — den östlichen Provinzen Kubas —, leichter, krautiger, mit einer Aromatik, die sich deutlich vom westlichen Terroir unterscheidet. Daraus entstand ein einzigartiges Profil: unbestreitbar kubanisch, doch mit einer Leichtigkeit und Krautigkeit, die Partagás-Liebhaber befremdlich und Quintero-Liebhaber unersetzlich fanden.', 'Zum Tabak schreibt habanos.com, die gesamte Mischung der Marke stamme aus der Zone Vuelta Abajo, die Stärke sei mittel und die Zigarren würden vollständig von Hand gerollt, mit kurzer Einlage. Eine Reportage der Fachpresse (April 2012) nennt für das Deckblatt die Zonen Vuelta Abajo und Semi Vuelta in Pinar del Río, und ein britischer Händler nennt dieselben beiden Zonen. Das Haus präsentiert die Marke als Einstieg in den Geschmack des Habano, in mittlerer Stärke und zu erschwinglichem Preis.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Quintero 的独特之处在于其烟叶的产区来源。哈瓦那各大品牌一概只取西部 Vuelta Abajo 的烟叶，Quintero 历来却使用 Vuelta Arriba——古巴东部各省——的烟叶：更轻盈、更草本，香气签名与西部风土截然不同。由此形成了独一无二的风格：无可置疑的古巴味，却带着一种轻盈与草本气，让 Partagás 的拥趸感到不解，也让 Quintero 的拥趸觉得无可替代。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Quintero 的独特之处在于其烟叶的产区来源。哈瓦那各大品牌一概只取西部 Vuelta Abajo 的烟叶，Quintero 历来却使用 Vuelta Arriba——古巴东部各省——的烟叶：更轻盈、更草本，香气签名与西部风土截然不同。由此形成了独一无二的风格：无可置疑的古巴味，却带着一种轻盈与草本气，让 Partagás 的拥趸感到不解，也让 Quintero 的拥趸觉得无可替代。', '烟叶方面，habanos.com 写道，该品牌的全部配方来自 Vuelta Abajo 产区，力度为中等，雪茄全部手工卷制，使用短茄芯。行业媒体的一篇报道（2012年4月）给出的茄衣产区是 Pinar del Río 的 Vuelta Abajo 与 Semi Vuelta，一家英国零售商也列出同样这两个产区。品牌方把这个品牌介绍为通向 Habano 风味的入门之路，力度中等，价格亲民。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تنبع خصوصية Quintero من منشأ تبغها الإقليمي. فخلافاً لكبريات علامات هافانا التي تتزوّد حصراً من Vuelta Abajo الغربية، درجت Quintero تاريخياً على استخدام تبغ Vuelta Arriba — أي المقاطعات الشرقية من كوبا — وهو أخفّ وأكثر عشبية، ببصمة عطرية تختلف بوضوح عن الأرض الغربية. وقد أنشأ ذلك طابعاً فريداً: كوبياً بلا جدال، لكن بخفّة ونفَس عشبي كان هواة Partagás يجدونهما محيّرين، وهواة Quintero يجدونهما بلا بديل.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تنبع خصوصية Quintero من منشأ تبغها الإقليمي. فخلافاً لكبريات علامات هافانا التي تتزوّد حصراً من Vuelta Abajo الغربية، درجت Quintero تاريخياً على استخدام تبغ Vuelta Arriba — أي المقاطعات الشرقية من كوبا — وهو أخفّ وأكثر عشبية، ببصمة عطرية تختلف بوضوح عن الأرض الغربية. وقد أنشأ ذلك طابعاً فريداً: كوبياً بلا جدال، لكن بخفّة ونفَس عشبي كان هواة Partagás يجدونهما محيّرين، وهواة Quintero يجدونهما بلا بديل.', 'من جهة التبغ، تكتب habanos.com إنّ خلطة العلامة كلّها من منطقة Vuelta Abajo، وإنّ القوة متوسطة، وإنّ السيجار يُلفّ كلّه يدويًّا بحشوة قصيرة. ويذكر تقرير للصحافة المتخصّصة (أبريل 2012) لغلاف السيجار منطقتي Vuelta Abajo وSemi Vuelta في Pinar del Río، ويذكر تاجر تجزئة بريطاني المنطقتين نفسيهما. وتقدّم الدار العلامة بوصفها مدخلاً إلى نكهة الـ Habano، بقوة متوسطة وسعر في المتناول.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Quintero';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Après la nationalisation, Quintero rejoignit Habanos S.A. mais conserva sa distribution prioritaire vers l''Espagne. La marque reste pratiquement inconnue hors de la péninsule ibérique et des cercles de connaisseurs très informés — une situation qui convient parfaitement aux aficionados qui la découvrent et réalisent qu''ils ont accès à des cigares cubains exceptionnels à des prix dérisoires par rapport à leur qualité réelle.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Après la nationalisation, Quintero rejoignit Habanos S.A. mais conserva sa distribution prioritaire vers l''Espagne. La marque reste pratiquement inconnue hors de la péninsule ibérique et des cercles de connaisseurs très informés — une situation qui convient parfaitement aux aficionados qui la découvrent et réalisent qu''ils ont accès à des cigares cubains exceptionnels à des prix dérisoires par rapport à leur qualité réelle.', 'Selon Wikipédia, la marque devint surtout un cigare de machine après la nationalisation du début des années 1960, et Habanos S.A. abandonna en 2002 les cigares de machine au profit de versions faites main ; un détaillant britannique écrit pourtant que la gamme compte encore des formats faits à la machine ou finis à la main, alors que la page de la maison les dit tous roulés totalement à la main : les versions divergent. Un détaillant britannique la dit grande marque d''exportation dans les années 1940, particulièrement appréciée sur le marché espagnol, et toujours populaire auprès des amateurs espagnols.'), `history`),
  `history_en` = IF(LOCATE(CAST('After nationalization, Quintero joined Habanos S.A. but retained its priority distribution to Spain. The brand remains virtually unknown outside the Iberian Peninsula and the circles of very well-informed connoisseurs — a situation that perfectly suits the aficionados who discover it and realize they have access to exceptional Cuban cigars at prices absurdly low relative to their actual quality.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'After nationalization, Quintero joined Habanos S.A. but retained its priority distribution to Spain. The brand remains virtually unknown outside the Iberian Peninsula and the circles of very well-informed connoisseurs — a situation that perfectly suits the aficionados who discover it and realize they have access to exceptional Cuban cigars at prices absurdly low relative to their actual quality.', 'According to Wikipedia, the brand became mainly a machine-made cigar after the nationalisation of the early 1960s, and Habanos S.A. abandoned machine-made cigars in 2002 in favour of hand-made versions; a British retailer nevertheless writes that the range still includes sizes that are machine-made or hand-finished, whereas the house''s page says they are all entirely hand-rolled: the accounts diverge. A British retailer calls it a major export brand in the 1940s, particularly appreciated in the Spanish market, and still popular with Spanish enthusiasts.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Tras la nacionalización, Quintero pasó a Habanos S.A. pero conservó su distribución prioritaria hacia España. La marca sigue siendo prácticamente desconocida fuera de la península ibérica y de los círculos de entendidos muy informados, una situación que conviene de maravilla a los aficionados que la descubren y comprenden que tienen acceso a puros cubanos excepcionales a precios irrisorios frente a su calidad real.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Tras la nacionalización, Quintero pasó a Habanos S.A. pero conservó su distribución prioritaria hacia España. La marca sigue siendo prácticamente desconocida fuera de la península ibérica y de los círculos de entendidos muy informados, una situación que conviene de maravilla a los aficionados que la descubren y comprenden que tienen acceso a puros cubanos excepcionales a precios irrisorios frente a su calidad real.', 'Según Wikipedia, la marca se convirtió sobre todo en un puro de máquina tras la nacionalización de principios de los años sesenta, y Habanos S.A. abandonó en 2002 los puros de máquina en favor de versiones hechas a mano; un minorista británico escribe sin embargo que la gama aún cuenta con formatos hechos a máquina o rematados a mano, mientras que la página de la casa los dice todos liados totalmente a mano: las versiones divergen. Un minorista británico la dice gran marca de exportación en los años cuarenta, especialmente apreciada en el mercado español, y todavía popular entre los aficionados españoles.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Nach der Verstaatlichung kam Quintero zu Habanos S.A., behielt aber den Vorrang der spanischen Distribution. Die Marke ist außerhalb der Iberischen Halbinsel und sehr gut unterrichteter Kennerkreise praktisch unbekannt — ein Zustand, der jenen Aficionados bestens gefällt, die sie entdecken und merken, dass ihnen außergewöhnliche kubanische Zigarren zu Preisen offenstehen, die zu ihrer tatsächlichen Güte in keinem Verhältnis stehen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Nach der Verstaatlichung kam Quintero zu Habanos S.A., behielt aber den Vorrang der spanischen Distribution. Die Marke ist außerhalb der Iberischen Halbinsel und sehr gut unterrichteter Kennerkreise praktisch unbekannt — ein Zustand, der jenen Aficionados bestens gefällt, die sie entdecken und merken, dass ihnen außergewöhnliche kubanische Zigarren zu Preisen offenstehen, die zu ihrer tatsächlichen Güte in keinem Verhältnis stehen.', 'Laut Wikipedia wurde die Marke nach der Verstaatlichung zu Beginn der 1960er Jahre vor allem eine Maschinenzigarre, und Habanos S.A. gab 2002 die Maschinenzigarren zugunsten handgefertigter Versionen auf; ein britischer Händler schreibt dennoch, das Sortiment umfasse noch maschinengefertigte oder handveredelte Formate, während die Seite des Hauses sie alle als vollständig handgerollt bezeichnet: Die Darstellungen weichen voneinander ab. Ein britischer Händler nennt sie eine große Exportmarke der 1940er Jahre, besonders geschätzt auf dem spanischen Markt und bei spanischen Liebhabern noch immer beliebt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('国有化之后，Quintero 归入 Habanos S.A.，但保留了优先供应西班牙的渠道。在伊比利亚半岛与消息极为灵通的行家圈之外，这个品牌几乎无人知晓——而这种状况恰好合了那些发现它的爱好者的心意：他们由此得以用与实际品质完全不相称的低廉价格，享用出色的古巴雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '国有化之后，Quintero 归入 Habanos S.A.，但保留了优先供应西班牙的渠道。在伊比利亚半岛与消息极为灵通的行家圈之外，这个品牌几乎无人知晓——而这种状况恰好合了那些发现它的爱好者的心意：他们由此得以用与实际品质完全不相称的低廉价格，享用出色的古巴雪茄。', '据维基百科，该品牌在1960年代初国有化之后主要成了机制雪茄，Habanos S.A. 于2002年放弃机制雪茄，改为手工版本；然而一家英国零售商写道，产品线中仍有机制或手工收尾的规格，而品牌方的页面却称它们全部为完全手工卷制：说法不一。一家英国零售商称它在1940年代是重要的出口品牌，在西班牙市场尤其受欢迎，至今仍受西班牙爱好者喜爱。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('بعد التأميم انضمّت Quintero إلى Habanos S.A. لكنها احتفظت بأولوية التوزيع نحو إسبانيا. وتظل العلامة شبه مجهولة خارج شبه الجزيرة الإيبيرية ودوائر العارفين المطّلعين جداً — وهو وضع يناسب تماماً الهواة الذين يكتشفونها فيدركون أن بين أيديهم سيجاراً كوبياً استثنائياً بأسعار زهيدة قياساً بجودته الحقيقية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'بعد التأميم انضمّت Quintero إلى Habanos S.A. لكنها احتفظت بأولوية التوزيع نحو إسبانيا. وتظل العلامة شبه مجهولة خارج شبه الجزيرة الإيبيرية ودوائر العارفين المطّلعين جداً — وهو وضع يناسب تماماً الهواة الذين يكتشفونها فيدركون أن بين أيديهم سيجاراً كوبياً استثنائياً بأسعار زهيدة قياساً بجودته الحقيقية.', 'بحسب ويكيبيديا، صارت العلامة في الغالب سيجار آلة بعد التأميم في مطلع الستينيات، وتخلّت Habanos S.A. عام 2002 عن سيجار الآلة لصالح نسخ مصنوعة يدويًّا؛ ومع ذلك يكتب تاجر تجزئة بريطاني إنّ التشكيلة ما زالت تضمّ مقاسات مصنوعة بالآلة أو مشطّبة يدويًّا، في حين تقول صفحة الدار إنّها كلّها ملفوفة يدويًّا بالكامل: الروايات متباينة. ويصفها تاجر تجزئة بريطاني بأنها علامة تصدير كبيرة في الأربعينيات، محبوبة خصوصًا في السوق الإسبانية، وما زالت رائجة لدى الهواة الإسبان.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Quintero';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le Medias Coronas (40×102mm) est la vitola la plus emblématique : rapide, économique, d''une fraîcheur herbacée et mentholée légère que les amateurs d''espresso espagnols ont adoptée comme rituel quotidien depuis plus de soixante ans. C''est probablement le cigare cubain le plus fumé en Espagne, et le moins connu de l''extérieur.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le Medias Coronas (40×102mm) est la vitola la plus emblématique : rapide, économique, d''une fraîcheur herbacée et mentholée légère que les amateurs d''espresso espagnols ont adoptée comme rituel quotidien depuis plus de soixante ans. C''est probablement le cigare cubain le plus fumé en Espagne, et le moins connu de l''extérieur.', 'Le Favoritos, cinquième format de la gamme, date de 2012 : 4 1/2 pouces (environ 114 mm) sur cepo 50, appelé Concha No. 2 en fabrique, de force moyenne, vendu en paquets de cinq. Des détaillants britanniques listent aussi les formats Petit Quintero, Panetelas et Tubulares, sans cotes lues.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Medias Coronas (40×102mm) is the house''s most iconic vitola: quick, economical, with a light herbaceous and slightly mentholated freshness that Spanish espresso drinkers have adopted as a daily ritual for more than sixty years. It is probably the most smoked Cuban cigar in Spain, and the least known outside it.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Medias Coronas (40×102mm) is the house''s most iconic vitola: quick, economical, with a light herbaceous and slightly mentholated freshness that Spanish espresso drinkers have adopted as a daily ritual for more than sixty years. It is probably the most smoked Cuban cigar in Spain, and the least known outside it.', 'The Favoritos, the fifth size in the range, dates from 2012: 4 1/2 inches (about 114 mm) on ring gauge 50, called Concha No. 2 in the factory, medium strength, sold in packs of five. British retailers also list the Petit Quintero, Panetelas and Tubulares sizes, with no dimensions read.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El Medias Coronas (40×102 mm) es la vitola más emblemática: rápida, económica, de un frescor herbáceo y ligeramente mentolado que los amantes españoles del espresso han adoptado como ritual cotidiano desde hace más de sesenta años. Es probablemente el puro cubano más fumado en España y el menos conocido fuera de ella.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El Medias Coronas (40×102 mm) es la vitola más emblemática: rápida, económica, de un frescor herbáceo y ligeramente mentolado que los amantes españoles del espresso han adoptado como ritual cotidiano desde hace más de sesenta años. Es probablemente el puro cubano más fumado en España y el menos conocido fuera de ella.', 'El Favoritos, quinto formato de la gama, data de 2012: 4 1/2 pulgadas (unos 114 mm) sobre cepo 50, llamado Concha No. 2 en fábrica, de fuerza media, vendido en paquetes de cinco. Minoristas británicos listan también los formatos Petit Quintero, Panetelas y Tubulares, sin cotas leídas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Medias Coronas (40×102 mm) ist die sinnbildlichste Vitola: schnell, günstig, von einer krautigen, leicht mentholigen Frische, die spanische Espressotrinker seit über sechzig Jahren zum täglichen Ritual gemacht haben. Sie ist wohl die meistgerauchte kubanische Zigarre Spaniens — und außerhalb die am wenigsten bekannte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Medias Coronas (40×102 mm) ist die sinnbildlichste Vitola: schnell, günstig, von einer krautigen, leicht mentholigen Frische, die spanische Espressotrinker seit über sechzig Jahren zum täglichen Ritual gemacht haben. Sie ist wohl die meistgerauchte kubanische Zigarre Spaniens — und außerhalb die am wenigsten bekannte.', 'Die Favoritos, das fünfte Format der Reihe, stammt von 2012: 4 1/2 Zoll (etwa 114 mm) bei Ringmaß 50, in der Fabrik Concha No. 2 genannt, von mittlerer Stärke, in Fünferpackungen verkauft. Britische Händler führen außerdem die Formate Petit Quintero, Panetelas und Tubulares auf, ohne gelesene Maße.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Medias Coronas（40×102mm）是最具代表性的规格：快、便宜，带着草本与淡淡薄荷的清新，六十多年来一直是西班牙浓缩咖啡爱好者的日常仪式。它很可能是西班牙抽得最多的古巴雪茄，也是境外最不为人知的一支。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Medias Coronas（40×102mm）是最具代表性的规格：快、便宜，带着草本与淡淡薄荷的清新，六十多年来一直是西班牙浓缩咖啡爱好者的日常仪式。它很可能是西班牙抽得最多的古巴雪茄，也是境外最不为人知的一支。', 'Favoritos 是产品线的第五个规格，2012年推出：4 1/2 英寸（约114mm），环径50，工厂内称为 Concha No. 2，力度中等，五支一包出售。英国零售商还列出 Petit Quintero、Panetelas 和 Tubulares 规格，未见尺寸数据。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('و Medias Coronas (40×102 مم) هو الطراز الأكثر رمزية: سريع، اقتصادي، بانتعاش عشبي ولمسة نعناع خفيفة تبنّاها عشّاق الإسبريسو الإسبان طقساً يومياً منذ أكثر من ستين عاماً. وهو على الأرجح أكثر سيجار كوبي يُدخَّن في إسبانيا، وأقلّها شهرةً في الخارج.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'و Medias Coronas (40×102 مم) هو الطراز الأكثر رمزية: سريع، اقتصادي، بانتعاش عشبي ولمسة نعناع خفيفة تبنّاها عشّاق الإسبريسو الإسبان طقساً يومياً منذ أكثر من ستين عاماً. وهو على الأرجح أكثر سيجار كوبي يُدخَّن في إسبانيا، وأقلّها شهرةً في الخارج.', 'الـ Favoritos، وهو الطراز الخامس في التشكيلة، يعود إلى 2012: 4 1/2 بوصة (نحو 114 مم) على عيار 50، ويسمّى Concha No. 2 في المصنع، بقوة متوسطة، ويُباع في عبوات من خمسة. ويدرج تجّار تجزئة بريطانيون أيضًا المقاسات Petit Quintero وPanetelas وTubulares، دون أن تُقرأ لها مقاسات.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Quintero';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est celle de Cienfuegos, ouverte vers 1925, là où la marque est née — l''une des rares du portefeuille qui ne soit pas havanaise. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle ne date pas la marque — 1924 vient de l''usage — mais la dit née hors de La Havane, à Cienfuegos, la perle du Sud, et toute roulée à la main en tripe courte, avec du tabac de Vuelta Abajo.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est celle de Cienfuegos, ouverte vers 1925, là où la marque est née — l''une des rares du portefeuille qui ne soit pas havanaise. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle ne date pas la marque — 1924 vient de l''usage — mais la dit née hors de La Havane, à Cienfuegos, la perle du Sud, et toute roulée à la main en tripe courte, avec du tabac de Vuelta Abajo.', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme pas la fabrique mère de Quintero. La marque est née à Cienfuegos (habanos.com) ; Wikipédia place une plus grande fabrique de roulage à La Havane dans les années 1940 ; la fabrique actuelle reste ouverte. En octobre 2026, habanos.com la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros ; la presse du métier annonçait ce classement le 1er août 2019, pour des cigares vendus à des prix plus abordables. La page officielle ne date pas la marque — 1924 vient de l''usage — mais la dit née hors de La Havane, à Cienfuegos, la perle du Sud, et toute roulée à la main en tripe courte, avec du tabac de Vuelta Abajo.'), `history`),
  `history_en` = IF(LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is the Cienfuegos factory, opened around 1925, where the brand was born — one of the few in the portfolio that is not from Havana. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page does not date the brand — 1924 comes from usage — but says it was born outside Havana, in Cienfuegos, the pearl of the South, and is all hand-rolled short filler, with Vuelta Abajo tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is the Cienfuegos factory, opened around 1925, where the brand was born — one of the few in the portfolio that is not from Havana. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page does not date the brand — 1924 comes from usage — but says it was born outside Havana, in Cienfuegos, the pearl of the South, and is all hand-rolled short filler, with Vuelta Abajo tobacco.', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos does not name Quintero''s mother factory. The brand was born in Cienfuegos (habanos.com); Wikipedia places a larger rolling factory in Havana in the 1940s; the present factory remains open. In October 2026, habanos.com places it among its three volume brands — José L. Piedra, Quintero, Vegueros; the trade press announced this classification on 1 August 2019, for cigars sold at more affordable prices. The official page does not date the brand — 1924 comes from usage — but says it was born outside Havana, in Cienfuegos, the pearl of the South, and is all hand-rolled short filler, with Vuelta Abajo tobacco.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es la de Cienfuegos, abierta hacia 1925, donde nació la marca — una de las pocas del portafolio que no es habanera. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial no fecha la marca — 1924 viene del uso — pero la dice nacida fuera de La Habana, en Cienfuegos, la perla del Sur, y toda liada a mano con tripa corta, con tabaco de Vuelta Abajo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es la de Cienfuegos, abierta hacia 1925, donde nació la marca — una de las pocas del portafolio que no es habanera. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial no fecha la marca — 1924 viene del uso — pero la dice nacida fuera de La Habana, en Cienfuegos, la perla del Sur, y toda liada a mano con tripa corta, con tabaco de Vuelta Abajo.', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra la fábrica madre de Quintero. La marca nació en Cienfuegos (habanos.com); Wikipedia sitúa una fábrica de liado mayor en La Habana en los años cuarenta; la fábrica actual sigue abierta. En octubre de 2026, habanos.com la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros; la prensa del oficio anunciaba esa clasificación el 1 de agosto de 2019, para puros vendidos a precios más asequibles. La página oficial no fecha la marca — 1924 viene del uso — pero la dice nacida fuera de La Habana, en Cienfuegos, la perla del Sur, y toda liada a mano con tripa corta, con tabaco de Vuelta Abajo.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist die von Cienfuegos, um 1925 eröffnet, wo die Marke entstand — eine der wenigen im Portfolio, die nicht aus Havanna ist. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite datiert die Marke nicht — 1924 stammt aus dem Gebrauch —, nennt sie aber außerhalb Havannas entstanden, in Cienfuegos, der Perle des Südens, und ganz handgerollten Shortfiller mit Vuelta-Abajo-Tabak.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist die von Cienfuegos, um 1925 eröffnet, wo die Marke entstand — eine der wenigen im Portfolio, die nicht aus Havanna ist. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite datiert die Marke nicht — 1924 stammt aus dem Gebrauch —, nennt sie aber außerhalb Havannas entstanden, in Cienfuegos, der Perle des Südens, und ganz handgerollten Shortfiller mit Vuelta-Abajo-Tabak.', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt die Mutterfabrik von Quintero nicht. Die Marke entstand in Cienfuegos (habanos.com); Wikipedia verortet in den 1940er Jahren eine größere Rollfabrik in Havanna; die heutige Fabrik bleibt geöffnet. Im Oktober 2026 zählt habanos.com sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros; die Fachpresse kündigte diese Einstufung am 1. August 2019 an, für Zigarren zu erschwinglicheren Preisen. Die offizielle Seite datiert die Marke nicht — 1924 stammt aus dem Gebrauch —, nennt sie aber außerhalb Havannas entstanden, in Cienfuegos, der Perle des Südens, und ganz handgerollten Shortfiller mit Vuelta-Abajo-Tabak.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是西恩富戈斯厂，约1925年开办，品牌就在那里诞生——是产品组合里少数不属于哈瓦那的品牌之一。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面没有给品牌标日期——1924年来自惯例——但说它诞生在哈瓦那之外的西恩富戈斯，南方的明珠，全部为手工短茄芯，用下维尔塔烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是西恩富戈斯厂，约1925年开办，品牌就在那里诞生——是产品组合里少数不属于哈瓦那的品牌之一。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面没有给品牌标日期——1924年来自惯例——但说它诞生在哈瓦那之外的西恩富戈斯，南方的明珠，全部为手工短茄芯，用下维尔塔烟叶。', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有点名 Quintero 的母厂。品牌诞生于西恩富戈斯（habanos.com）；维基百科把一家规模更大的卷制工厂放在1940年代的哈瓦那；现今的工厂仍在营业。2026年10月，habanos.com 把它列入三个量产品牌——José L. Piedra、Quintero、Vegueros；行业媒体在2019年8月1日预告了这一分类，所涉雪茄的售价更为亲民。官方页面没有给品牌标日期——1924年来自惯例——但说它诞生在哈瓦那之外的西恩富戈斯，南方的明珠，全部为手工短茄芯，用下维尔塔烟叶。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو مصنع سيينفويغوس، المفتوح نحو 1925، حيث وُلدت العلامة — وهي من القلائل في المحفظة التي ليست من هافانا. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. لا تؤرّخ الصفحة الرسمية العلامة — 1924 من العرف — لكنّها تقول إنّها وُلدت خارج هافانا، في سيينفويغوس لؤلؤة الجنوب، وإنّها كلّها ملفوفة يدويًّا بحشوة قصيرة من تبغ فويلتا أباخو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو مصنع سيينفويغوس، المفتوح نحو 1925، حيث وُلدت العلامة — وهي من القلائل في المحفظة التي ليست من هافانا. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. لا تؤرّخ الصفحة الرسمية العلامة — 1924 من العرف — لكنّها تقول إنّها وُلدت خارج هافانا، في سيينفويغوس لؤلؤة الجنوب، وإنّها كلّها ملفوفة يدويًّا بحشوة قصيرة من تبغ فويلتا أباخو.', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي Habanos المصنع الأمّ لـ Quintero. وُلدت العلامة في سيينفويغوس (habanos.com)؛ وتضع ويكيبيديا مصنع لفّ أوسع في هافانا في الأربعينيات؛ والمصنع الحالي ما زال مفتوحًا. في أكتوبر 2026 تصنّفها habanos.com ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros؛ وكانت الصحافة المتخصّصة قد أعلنت هذا التصنيف في 1 أغسطس 2019، لسيجار يُباع بأسعار أيسر. لا تؤرّخ الصفحة الرسمية العلامة — 1924 من العرف — لكنّها تقول إنّها وُلدت خارج هافانا، في سيينفويغوس لؤلؤة الجنوب، وإنّها كلّها ملفوفة يدويًّا بحشوة قصيرة من تبغ فويلتا أباخو.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Quintero';

