  `factory` = 'Habanos ne nomme aucune fabrique mère pour Quintero ; marque née à Cienfuegos (habanos.com) ; tripe courte, totalmente a mano, tabac de Vuelta Abajo',
  `gamme` = '[{"name":"Favoritos","color":"#8B6914","story":"4 1/2 pouces (environ 114 mm) sur cepo 50, appelé Concha No. 2 en fabrique ; cinquième format de la gamme et le plus épais, lancé en 2012 ; force moyenne, tripe courte faite main, vendu en paquets de cinq.","wrapper":"Vuelta Abajo et Semi Vuelta","force":"Medium"},{"name":"Petit Quintero","color":"#7A5C0F","story":"Format cité par des détaillants britanniques ; la page de la maison ne donne aucune cote.","wrapper":"Vuelta Abajo","force":"Medium"}]',
