  `gamme_de` = '[{"name":"Favoritos","color":"#8B6914","story":"4 1/2 Zoll (etwa 114 mm) bei Ringmaß 50, in der Fabrik Concha No. 2 genannt; fünftes Format der Reihe und das dickste, 2012 eingeführt; mittlere Stärke, kurze handgefertigte Einlage, in Fünferpackungen verkauft.","wrapper":"Vuelta Abajo und Semi Vuelta","force":"Medium"},{"name":"Petit Quintero","color":"#7A5C0F","story":"Format, das britische Händler nennen; die Seite des Hauses gibt keine Maße an.","wrapper":"Vuelta Abajo","force":"Medium"}]',
  `gamme_zh` = '[{"name":"Favoritos","color":"#8B6914","story":"4 1/2 英寸（约114mm），环径50，工厂内称为 Concha No. 2；产品线的第五个规格，粗度居全系列之首，2012年推出；力度中等，手工短茄芯，五支一包出售。","wrapper":"Vuelta Abajo 与 Semi Vuelta","force":"Medium"},{"name":"Petit Quintero","color":"#7A5C0F","story":"英国零售商提到的规格；品牌方页面没有给出任何尺寸。","wrapper":"Vuelta Abajo","force":"Medium"}]',
  `gamme_ar` = '[{"name":"Favoritos","color":"#8B6914","story":"4 1/2 بوصة (نحو 114 مم) على عيار 50، ويسمّى Concha No. 2 في المصنع؛ الطراز الخامس في التشكيلة، بقطر يفوق سائر طرازاتها، أُطلق عام 2012؛ بقوة متوسطة وحشوة قصيرة مصنوعة يدويًّا، ويُباع في عبوات من خمسة.","wrapper":"Vuelta Abajo وSemi Vuelta","force":"Medium"},{"name":"Petit Quintero","color":"#7A5C0F","story":"مقاس يذكره تجّار تجزئة بريطانيون؛ ولا تعطي صفحة الدار أي مقاسات.","wrapper":"Vuelta Abajo","force":"Medium"}]',
