  `pairings` = '[{"type":"Café","name":"Café con leche","notes":"Suggestion : la douceur du lait accompagne une force moyenne."},{"type":"Vin","name":"Manzanilla de Sanlúcar","notes":"Suggestion : un xérès sec et léger pour un cigare de force moyenne."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Café con leche","notes":"Suggestion: the sweetness of the milk accompanies a medium strength."},{"type":"Wine","name":"Manzanilla de Sanlúcar","notes":"Suggestion: a dry, light sherry for a medium-strength cigar."}]',
  `pairings_es` = '[{"type":"Café","name":"Café con leche","notes":"Sugerencia: el dulzor de la leche acompaña una fuerza media."},{"type":"Vino","name":"Manzanilla de Sanlúcar","notes":"Sugerencia: un jerez seco y ligero para un puro de fuerza media."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Café con leche","notes":"Vorschlag: Die Süße der Milch begleitet eine mittlere Stärke."},{"type":"Wein","name":"Manzanilla de Sanlúcar","notes":"Vorschlag: ein trockener, leichter Sherry zu einer Zigarre mittlerer Stärke."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"牛奶咖啡","notes":"建议：牛奶的柔润与中等力度相配。"},{"type":"葡萄酒","name":"桑卢卡尔曼萨尼亚雪利酒","notes":"建议：清淡的干型雪利酒，适合中等力度的雪茄。"}]',
  `pairings_ar` = '[{"type":"قهوة","name":"قهوة بالحليب","notes":"اقتراح: حلاوة الحليب ترافق قوة متوسطة."},{"type":"نبيذ","name":"مانزانييا دي سانلوكار","notes":"اقتراح: شيري جاف وخفيف لسيجار بقوة متوسطة."}]',
  `source` = IF(LOCATE(CAST('cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique provinciale de Cienfuegos, vers 1925, mère de Quintero) ; ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique provinciale de Cienfuegos, vers 1925, mère de Quintero) ; ', ''), `source`),
  `source` = IF(LOCATE(CAST('habanos.com « Quintero Brand » et version espagnole (sans da' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'habanos.com « Quintero Brand » et version espagnole (sans date, lues le 16 octobre 2026 : fondateur Agustín Quintero à Cienfuegos, tout le mélange de Vuelta Abajo, force moyenne, totalmente a mano, tripe courte) ; cigaraficionado.com « Cuban Quintero Brand Gets New Size » (20 avril 2012 : Favoritos, 4 1/2 pouces x 50, Concha No. 2, Vuelta Abajo et Semi Vuelta) ; en.wikipedia.org « Quintero (cigar) » (1924, Quintero y Hermanos, article à source unique) ; cigarsunlimited.co.uk et simplycigars.co.uk (détaillants : formats, 1924 « believed », marché espagnol)')),
