-- ── Diplomáticos ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Diplomáticos est née d''une commande : en 1966, le monopole français du tabac cherchait une marque à son propre usage, moins chère que Montecristo mais bâtie sur le même registre. La Havane lui a fourni exactement cela — une gamme parallèle, aux formats numérotés comme ceux de Montecristo, et à l''assemblage très proche.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Diplomáticos est née d''une commande : en 1966, le monopole français du tabac cherchait une marque à son propre usage, moins chère que Montecristo mais bâtie sur le même registre. La Havane lui a fourni exactement cela — une gamme parallèle, aux formats numérotés comme ceux de Montecristo, et à l''assemblage très proche.', 'Diplomáticos naît en 1966, écrivent la presse du métier (2025) et Wikipédia, comme une alternative moins chère à Montecristo ; Habanos la date seulement des années 1960. Wikipédia lui donne un assemblage un peu plus doux et une cape plus claire pour plaire au consommateur français. Les cinq formats d''origine (n° 1 à 5) reprenaient les cotes des Montecristo n° 1 à 5 ; les n° 6 et 7, ajoutés en 1976 sur les cotes des Montecristo Especial n° 1 et 2, ont été abandonnés au milieu des années 1980.'), `history`),
  `history_en` = IF(LOCATE(CAST('Diplomáticos was born of an order: in 1966 the French tobacco monopoly was looking for a brand for its own use, cheaper than Montecristo but built in the same register. Havana supplied exactly that — a parallel range, with formats numbered like Montecristo''s, and a very close blend.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Diplomáticos was born of an order: in 1966 the French tobacco monopoly was looking for a brand for its own use, cheaper than Montecristo but built in the same register. Havana supplied exactly that — a parallel range, with formats numbered like Montecristo''s, and a very close blend.', 'Diplomáticos was born in 1966, according to the trade press (2025) and Wikipedia, as a cheaper alternative to Montecristo; Habanos dates it only to the 1960s. Wikipedia gives it a slightly milder blend and a lighter wrapper to please the French consumer. The five original sizes (Nos. 1 to 5) took the dimensions of Montecristo Nos. 1 to 5; Nos. 6 and 7, added in 1976 on the dimensions of Montecristo Especial Nos. 1 and 2, were dropped in the mid-1980s.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Diplomáticos nació de un encargo: en 1966 el monopolio francés del tabaco buscaba una marca para su propio uso, más barata que Montecristo pero construida en el mismo registro. La Habana le proporcionó exactamente eso — una gama paralela, con formatos numerados como los de Montecristo y una liga muy próxima.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Diplomáticos nació de un encargo: en 1966 el monopolio francés del tabaco buscaba una marca para su propio uso, más barata que Montecristo pero construida en el mismo registro. La Habana le proporcionó exactamente eso — una gama paralela, con formatos numerados como los de Montecristo y una liga muy próxima.', 'Diplomáticos nace en 1966, escriben la prensa del oficio (2025) y Wikipedia, como una alternativa más barata a Montecristo; Habanos la fecha solo en los años sesenta. Wikipedia le da una liga algo más suave y una capa más clara para agradar al consumidor francés. Los cinco formatos de origen (n.º 1 a 5) reproducían las medidas de los Montecristo n.º 1 a 5; los n.º 6 y 7, añadidos en 1976 sobre las medidas de los Montecristo Especial n.º 1 y 2, se abandonaron a mediados de los años ochenta.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Diplomáticos entstand aus einer Bestellung: 1966 suchte das französische Tabakmonopol eine Marke für den eigenen Gebrauch, günstiger als Montecristo, aber im selben Register gebaut. Havanna lieferte genau das — eine Parallelserie mit Formaten, die wie die von Montecristo nummeriert sind, und einem sehr ähnlichen Blend.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Diplomáticos entstand aus einer Bestellung: 1966 suchte das französische Tabakmonopol eine Marke für den eigenen Gebrauch, günstiger als Montecristo, aber im selben Register gebaut. Havanna lieferte genau das — eine Parallelserie mit Formaten, die wie die von Montecristo nummeriert sind, und einem sehr ähnlichen Blend.', 'Diplomáticos entsteht 1966, schreiben die Fachpresse (2025) und Wikipedia, als günstigere Alternative zu Montecristo; Habanos datiert sie nur auf die 1960er Jahre. Laut Wikipedia hat sie eine etwas mildere Mischung und ein helleres Deckblatt, um dem französischen Verbraucher zu gefallen. Die fünf ursprünglichen Formate (Nr. 1 bis 5) übernahmen die Maße der Montecristo Nr. 1 bis 5; die Nr. 6 und 7, 1976 auf den Maßen der Montecristo Especial Nr. 1 und 2 hinzugefügt, wurden Mitte der 1980er Jahre aufgegeben.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('外交官系列诞生于一份订单：1966年，法国烟草专卖机构想要一个供自己使用的品牌，价格低于蒙特克里斯托，却建立在同样的路数之上。哈瓦那提供的正是如此——一条平行产品线，尺寸编号方式与蒙特克里斯托一致，配方也极为接近。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '外交官系列诞生于一份订单：1966年，法国烟草专卖机构想要一个供自己使用的品牌，价格低于蒙特克里斯托，却建立在同样的路数之上。哈瓦那提供的正是如此——一条平行产品线，尺寸编号方式与蒙特克里斯托一致，配方也极为接近。', 'Diplomáticos 诞生于1966年，行业媒体（2025）与维基百科都这样写，是作为 Montecristo 的廉价替代品；Habanos 只把它定在1960年代。维基百科称它的配方略温和、茄衣颜色更浅，以迎合法国消费者。原有的五个规格（No. 1至5）沿用 Montecristo No. 1至5 的尺寸；1976年增加的 No. 6 和 No. 7 采用 Montecristo Especial No. 1 和 No. 2 的尺寸，于1980年代中期停产。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وُلدت «ديبلوماتيكوس» من طلبيّة: ففي 1966 كان احتكار التبغ الفرنسي يبحث عن علامة لاستخدامه الخاص، أرخص من مونتيكريستو لكن مبنيّة على المستوى نفسه. وقدّمت له هافانا ذلك تماماً — تشكيلة موازية، بمقاسات مرقّمة كمقاسات مونتيكريستو، وخلطة شديدة القرب.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وُلدت «ديبلوماتيكوس» من طلبيّة: ففي 1966 كان احتكار التبغ الفرنسي يبحث عن علامة لاستخدامه الخاص، أرخص من مونتيكريستو لكن مبنيّة على المستوى نفسه. وقدّمت له هافانا ذلك تماماً — تشكيلة موازية، بمقاسات مرقّمة كمقاسات مونتيكريستو، وخلطة شديدة القرب.', 'تولد Diplomáticos عام 1966، كما تكتب الصحافة المتخصّصة (2025) وويكيبيديا، بديلاً أرخص من Montecristo؛ ولا تؤرّخها Habanos إلا بالستينيات. وتعطيها ويكيبيديا خلطة ألطف قليلاً وغلافاً أفتح لوناً لإرضاء المستهلك الفرنسي. وكانت المقاسات الخمسة الأصلية (No. 1 إلى 5) تعيد مقاسات Montecristo No. 1 إلى 5؛ أمّا No. 6 وNo. 7، اللذان أُضيفا عام 1976 على مقاسات Montecristo Especial No. 1 وNo. 2، فقد أُسقطا في منتصف الثمانينيات.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Diplomáticos';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Ce parallélisme, longtemps tenu pour un secret d''initiés, est devenu l''argument principal de la marque : les amateurs y voient l''occasion d''un profil montecristien à un prix plus doux. La comparaison est un peu injuste — les assemblages ont divergé au fil des décennies — mais elle a fait la réputation de la maison.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Ce parallélisme, longtemps tenu pour un secret d''initiés, est devenu l''argument principal de la marque : les amateurs y voient l''occasion d''un profil montecristien à un prix plus doux. La comparaison est un peu injuste — les assemblages ont divergé au fil des décennies — mais elle a fait la réputation de la maison.', 'La comparaison avec Montecristo fait l''identité de la marque : des formats numérotés comme les siens, à un prix un peu inférieur à celui du format équivalent, dit Wikipédia. La presse du métier écrit qu''elle n''a jamais atteint la réputation de Montecristo.'), `history`),
  `history_en` = IF(LOCATE(CAST('That parallelism, long treated as an insiders'' secret, has become the brand''s chief argument: enthusiasts see in it the chance of a Montecristo profile at a gentler price. The comparison is a little unfair — the blends have diverged over the decades — but it made the reputation of the house.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'That parallelism, long treated as an insiders'' secret, has become the brand''s chief argument: enthusiasts see in it the chance of a Montecristo profile at a gentler price. The comparison is a little unfair — the blends have diverged over the decades — but it made the reputation of the house.', 'The comparison with Montecristo makes the identity of the brand: sizes numbered like its own, at a price a little below that of the equivalent size, says Wikipedia. The trade press writes that it never reached the reputation of Montecristo.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Ese paralelismo, considerado durante mucho tiempo un secreto de iniciados, se ha convertido en el argumento principal de la marca: los aficionados ven en él la ocasión de un perfil montecristiano a un precio más suave. La comparación es algo injusta — las ligas han divergido con las décadas — pero hizo la fama de la casa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Ese paralelismo, considerado durante mucho tiempo un secreto de iniciados, se ha convertido en el argumento principal de la marca: los aficionados ven en él la ocasión de un perfil montecristiano a un precio más suave. La comparación es algo injusta — las ligas han divergido con las décadas — pero hizo la fama de la casa.', 'La comparación con Montecristo hace la identidad de la marca: formatos numerados como los suyos, a un precio algo inferior al del formato equivalente, dice Wikipedia. La prensa del oficio escribe que nunca alcanzó la reputación de Montecristo.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Diese Parallelität, lange als Insidergeheimnis gehandelt, ist zum Hauptargument der Marke geworden: Liebhaber sehen darin die Gelegenheit zu einem Montecristo-Profil zu sanfterem Preis. Der Vergleich ist etwas unfair — die Blends sind über die Jahrzehnte auseinandergegangen —, doch er hat den Ruf des Hauses begründet.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Diese Parallelität, lange als Insidergeheimnis gehandelt, ist zum Hauptargument der Marke geworden: Liebhaber sehen darin die Gelegenheit zu einem Montecristo-Profil zu sanfterem Preis. Der Vergleich ist etwas unfair — die Blends sind über die Jahrzehnte auseinandergegangen —, doch er hat den Ruf des Hauses begründet.', 'Der Vergleich mit Montecristo prägt die Identität der Marke: wie bei ihr nummerierte Formate zu einem etwas niedrigeren Preis als das entsprechende Format, sagt Wikipedia. Die Fachpresse schreibt, sie habe den Ruf von Montecristo nie erreicht.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这种平行关系长期被当作内行的秘密，如今却成了这个品牌的主要卖点：爱好者视之为以更温和价格获得蒙特克里斯托风格的机会。这一比较略欠公允——几十年来配方已经分化——但它成就了这家的名声。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这种平行关系长期被当作内行的秘密，如今却成了这个品牌的主要卖点：爱好者视之为以更温和价格获得蒙特克里斯托风格的机会。这一比较略欠公允——几十年来配方已经分化——但它成就了这家的名声。', '与 Montecristo 的比较构成了这个品牌的身份：规格编号方式与其相同，价格比对应规格略低，维基百科如是说。行业媒体写道，它从未达到 Montecristo 的声誉。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('هذا التوازي، الذي عُدّ طويلاً سرّ العارفين، صار الحجّة الأساسية للعلامة: يرى فيه الهواة فرصةً لطابع مونتيكريستي بسعر ألطف. المقارنة مجحفة قليلاً — إذ تباعدت الخلطات عبر العقود — لكنها صنعت سمعة الدار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'هذا التوازي، الذي عُدّ طويلاً سرّ العارفين، صار الحجّة الأساسية للعلامة: يرى فيه الهواة فرصةً لطابع مونتيكريستي بسعر ألطف. المقارنة مجحفة قليلاً — إذ تباعدت الخلطات عبر العقود — لكنها صنعت سمعة الدار.', 'تصنع المقارنة بـ Montecristo هوية العلامة: مقاسات مرقّمة مثل مقاساتها، بسعر أدنى قليلاً من سعر المقاس المماثل، كما تقول ويكيبيديا. وتكتب الصحافة المتخصّصة إنّها لم تبلغ قط سمعة Montecristo.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Diplomáticos';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le profil actuel est médium : cacao, café au lait, une pointe de cuir, une régularité de combustion que les fumeurs réguliers apprécient. Le No.2, un Pirámide, en est l''expression la plus recherchée.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le profil actuel est médium : cacao, café au lait, une pointe de cuir, une régularité de combustion que les fumeurs réguliers apprécient. Le No.2, un Pirámide, en est l''expression la plus recherchée.', 'Habanos décrit un Habano de force moyenne à forte, entièrement roulé à la main en tripe longue, avec cape et tripe de la zone de Vuelta Abajo, à Pinar del Río. Wikipédia donne le No. 2, une pirámide, à 6 1/8 pouces sur cepo 52 (156 mm).'), `history`),
  `history_en` = IF(LOCATE(CAST('The present profile is medium: cocoa, café au lait, a touch of leather, an evenness of burn that regular smokers appreciate. The No.2, a Pirámide, is its most sought-after expression.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The present profile is medium: cocoa, café au lait, a touch of leather, an evenness of burn that regular smokers appreciate. The No.2, a Pirámide, is its most sought-after expression.', 'Habanos describes a Habano of medium to strong strength, entirely hand-rolled with long filler, with wrapper and filler from the Vuelta Abajo zone, in Pinar del Río. Wikipedia gives the No. 2, a pirámide, at 6 1/8 inches on ring gauge 52 (156 mm).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El perfil actual es medio: cacao, café con leche, una pizca de cuero, una regularidad de combustión que los fumadores habituales aprecian. El No.2, un Pirámide, es su expresión más buscada.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El perfil actual es medio: cacao, café con leche, una pizca de cuero, una regularidad de combustión que los fumadores habituales aprecian. El No.2, un Pirámide, es su expresión más buscada.', 'Habanos describe un Habano de fuerza media a fuerte, enteramente liado a mano con tripa larga, con capa y tripa de la zona de Vuelta Abajo, en Pinar del Río. Wikipedia da el No. 2, una pirámide, con 6 1/8 pulgadas sobre cepo 52 (156 mm).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das heutige Profil ist medium: Kakao, Milchkaffee, ein Hauch Leder, eine Gleichmäßigkeit des Abbrands, die regelmäßige Raucher schätzen. Die No.2, eine Pirámide, ist ihr begehrtester Ausdruck.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das heutige Profil ist medium: Kakao, Milchkaffee, ein Hauch Leder, eine Gleichmäßigkeit des Abbrands, die regelmäßige Raucher schätzen. Die No.2, eine Pirámide, ist ihr begehrtester Ausdruck.', 'Habanos beschreibt einen Habano von mittlerer bis starker Stärke, vollständig von Hand gerollt mit langer Einlage, mit Deckblatt und Einlage aus der Zone Vuelta Abajo in Pinar del Río. Wikipedia nennt die No. 2, eine Pirámide, mit 6 1/8 Zoll bei Ringmaß 52 (156 mm).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('如今的风格属中度：可可、欧蕾咖啡、一丝皮革，以及常抽者所看重的燃烧稳定性。No.2 这款金字塔形是它最受追捧的表达。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '如今的风格属中度：可可、欧蕾咖啡、一丝皮革，以及常抽者所看重的燃烧稳定性。No.2 这款金字塔形是它最受追捧的表达。', 'Habanos 描述这是一款力度中等至浓的 Habano，全程手工卷制，使用长茄芯，茄衣与茄芯均来自 Pinar del Río 的 Vuelta Abajo 产区。维基百科给出的 No. 2 是一款金字塔形，6 1/8 英寸，环径52（156mm）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('الطابع الحالي متوسط: كاكاو وقهوة بالحليب ولمسة جلد، وانتظام احتراق يقدّره المدخّنون المنتظمون. و«رقم 2»، وهو «بيراميدي»، تعبيرها الأكثر طلباً.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'الطابع الحالي متوسط: كاكاو وقهوة بالحليب ولمسة جلد، وانتظام احتراق يقدّره المدخّنون المنتظمون. و«رقم 2»، وهو «بيراميدي»، تعبيرها الأكثر طلباً.', 'تصف Habanos سيجار Habano بقوة متوسطة إلى شديدة، ملفوفاً يدوياً بالكامل بحشوة طويلة، بغلاف وحشوة من منطقة Vuelta Abajo في Pinar del Río. وتعطي ويكيبيديا No. 2، وهو هرمي الشكل، بمقاس 6 1/8 بوصة على عيار 52 (156 مم).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Diplomáticos';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme, réduite dans les années 2000 à une poignée de références, reste distribuée principalement en Europe — un héritage direct de sa naissance administrative.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme, réduite dans les années 2000 à une poignée de références, reste distribuée principalement en Europe — un héritage direct de sa naissance administrative.', 'La presse du métier écrit en octobre 2025 que les formats ont été réduits avec le temps et que seul le No. 2 reste dans la gamme courante ; elle présente le Cancilleres (5 1/8 pouces sur cepo 50, coffret de 25, lancé à Sofia fin novembre 2025) comme la première nouvelle taille de production régulière depuis des décennies. La marque paraît aussi dans les éditions régionales : Excelencia pour Cuba (2015), Reserva Especial pour les Caraïbes et l''Amérique centrale (2021), Leal pour Cuba (2023).'), `history`),
  `history_en` = IF(LOCATE(CAST('The range, cut back in the 2000s to a handful of references, remains distributed mainly in Europe — a direct legacy of its administrative birth.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The range, cut back in the 2000s to a handful of references, remains distributed mainly in Europe — a direct legacy of its administrative birth.', 'The trade press writes in October 2025 that the sizes have been cut back over time and that only the No. 2 remains in the current range; it presents the Cancilleres (5 1/8 inches on ring gauge 50, box of 25, launched in Sofia at the end of November 2025) as the first new regular-production size in decades. The brand also appears in the regional editions: Excelencia for Cuba (2015), Reserva Especial for the Caribbean and Central America (2021), Leal for Cuba (2023).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama, reducida en los años dos mil a un puñado de referencias, sigue distribuyéndose sobre todo en Europa — herencia directa de su nacimiento administrativo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama, reducida en los años dos mil a un puñado de referencias, sigue distribuyéndose sobre todo en Europa — herencia directa de su nacimiento administrativo.', 'La prensa del oficio escribe en octubre de 2025 que los formatos se han ido reduciendo con el tiempo y que solo el No. 2 sigue en la gama corriente; presenta el Cancilleres (5 1/8 pulgadas sobre cepo 50, caja de 25, lanzado en Sofía a finales de noviembre de 2025) como el primer tamaño nuevo de producción regular en décadas. La marca figura también en las ediciones regionales: Excelencia para Cuba (2015), Reserva Especial para el Caribe y Centroamérica (2021), Leal para Cuba (2023).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das in den 2000er Jahren auf eine Handvoll Referenzen gekürzte Sortiment wird weiterhin überwiegend in Europa vertrieben — ein direktes Erbe seiner administrativen Geburt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das in den 2000er Jahren auf eine Handvoll Referenzen gekürzte Sortiment wird weiterhin überwiegend in Europa vertrieben — ein direktes Erbe seiner administrativen Geburt.', 'Die Fachpresse schreibt im Oktober 2025, die Formate seien mit der Zeit reduziert worden und nur die No. 2 verbleibe im laufenden Sortiment; sie stellt die Cancilleres (5 1/8 Zoll bei Ringmaß 50, 25er-Kiste, Ende November 2025 in Sofia eingeführt) als erstes neues Format regulärer Produktion seit Jahrzehnten vor. Die Marke erscheint auch in den Regionaleditionen: Excelencia für Kuba (2015), Reserva Especial für die Karibik und Mittelamerika (2021), Leal für Kuba (2023).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('产品线在2000年代被削减至寥寥数款，至今仍主要在欧洲销售——这是它行政式诞生的直接遗产。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '产品线在2000年代被削减至寥寥数款，至今仍主要在欧洲销售——这是它行政式诞生的直接遗产。', '行业媒体在2025年10月写道，规格数量已随时间缩减，现行产品线中只剩 No. 2；它把 Cancilleres（5 1/8 英寸，环径50，25支装盒装，2025年11月底在索非亚推出）介绍为数十年来首款常规生产的新尺寸。该品牌也出现在地区限定版中：古巴的 Excelencia（2015年）、加勒比与中美洲的 Reserva Especial（2021年）、古巴的 Leal（2023年）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أمّا التشكيلة، التي قُلّصت في الألفية إلى حفنة من المراجع، فلا تزال تُوزَّع أساساً في أوروبا — إرثٌ مباشر من ولادتها الإدارية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أمّا التشكيلة، التي قُلّصت في الألفية إلى حفنة من المراجع، فلا تزال تُوزَّع أساساً في أوروبا — إرثٌ مباشر من ولادتها الإدارية.', 'تكتب الصحافة المتخصّصة في أكتوبر 2025 أنّ المقاسات قُلّصت مع الوقت وأنّ No. 2 وحده يبقى في التشكيلة الجارية؛ وتقدّم Cancilleres (5 1/8 بوصة على عيار 50، علبة من 25، أُطلق في صوفيا نهاية نوفمبر 2025) على أنّه أول مقاس جديد من الإنتاج المنتظم منذ عقود. وتظهر العلامة أيضاً في الإصدارات الإقليمية: Excelencia لكوبا (2015)، وReserva Especial لمنطقة الكاريبي وأمريكا الوسطى (2021)، وLeal لكوبا (2023).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Diplomáticos';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est H. Upmann — la José Martí, ainsi nommée depuis 1960 —, qui a changé plusieurs fois d''adresse et occupe depuis 2011 l''ancien bâtiment Romeo y Julieta de Belascoaín, à Centro Habana. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la date des années 1960 et la dit numérotée comme Montecristo, dont elle est née ; elle ne nomme pas sa fabrique, que la presse du métier place chez H. Upmann, comme Montecristo.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est H. Upmann — la José Martí, ainsi nommée depuis 1960 —, qui a changé plusieurs fois d''adresse et occupe depuis 2011 l''ancien bâtiment Romeo y Julieta de Belascoaín, à Centro Habana. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la date des années 1960 et la dit numérotée comme Montecristo, dont elle est née ; elle ne nomme pas sa fabrique, que la presse du métier place chez H. Upmann, comme Montecristo.', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme pas de fabrique. Un reportage de la presse du métier (2011) écrit que la fabrique Romeo y Julieta / H. Upmann de Belascoaín a la charge de la marque, mais qu''aucun Diplomáticos n''y était roulé en mai ; Wikipédia la dit faite à la fabrique José Martí, à La Havane. En octobre 2026, habanos.com la range parmi les treize autres marques du portefeuille de vingt-sept, hors des six globales, des cinq de valeur et des trois de volume ; la presse du métier comptait en 2019 vingt et une marques de portefeuille, Diplomáticos dans la catégorie des autres. La page officielle la dit relativement récente, des années 1960, d''une ressemblance marquée avec Montecristo et aux formats désignés par des numéros plutôt que par des noms ; elle ne nomme ni fabrique ni vitola.'), `history`),
  `history_en` = IF(LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is H. Upmann — the José Martí, so named since 1960 —, which has moved several times and has occupied since 2011 the former Romeo y Julieta building on Belascoaín, Centro Habana. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it to the 1960s and says it is numbered like Montecristo, from which it was born; it does not name its factory, which the trade press places at H. Upmann, like Montecristo.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is H. Upmann — the José Martí, so named since 1960 —, which has moved several times and has occupied since 2011 the former Romeo y Julieta building on Belascoaín, Centro Habana. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it to the 1960s and says it is numbered like Montecristo, from which it was born; it does not name its factory, which the trade press places at H. Upmann, like Montecristo.', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos names no factory. A trade-press report (2011) writes that the Romeo y Julieta / H. Upmann factory on Belascoaín is in charge of the brand, but that no Diplomáticos was being rolled there in May; Wikipedia says it is made at the José Martí factory, in Havana. In October 2026 habanos.com places it among the thirteen other brands of the portfolio of twenty-seven, outside the six global brands, the five value brands and the three volume brands; in 2019 the trade press counted twenty-one portfolio brands, Diplomáticos in the category of the others. The official page calls it relatively recent, from the 1960s, strongly resembling Montecristo and with sizes designated by numbers rather than names; it names neither a factory nor a vitola.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es H. Upmann — la José Martí, así llamada desde 1960 —, que cambió varias veces de dirección y ocupa desde 2011 el antiguo edificio Romeo y Julieta de Belascoaín, en Centro Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la fecha en los años sesenta y la dice numerada como Montecristo, de la que nació; no nombra su fábrica, que la prensa del oficio sitúa en H. Upmann, como Montecristo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es H. Upmann — la José Martí, así llamada desde 1960 —, que cambió varias veces de dirección y ocupa desde 2011 el antiguo edificio Romeo y Julieta de Belascoaín, en Centro Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la fecha en los años sesenta y la dice numerada como Montecristo, de la que nació; no nombra su fábrica, que la prensa del oficio sitúa en H. Upmann, como Montecristo.', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra ninguna fábrica. Un reportaje de la prensa del oficio (2011) escribe que la fábrica Romeo y Julieta / H. Upmann de Belascoaín tiene a su cargo la marca, pero que allí no se liaba ningún Diplomáticos en mayo; Wikipedia la dice hecha en la fábrica José Martí, en La Habana. En octubre de 2026, habanos.com la clasifica entre las otras trece marcas del portafolio de veintisiete, fuera de las seis globales, las cinco de valor y las tres de volumen; la prensa del oficio contaba en 2019 veintiuna marcas de portafolio, con Diplomáticos en la categoría de las otras. La página oficial la dice relativamente reciente, de los años sesenta, de marcado parecido con Montecristo y con formatos designados por números en lugar de nombres; no nombra ni fábrica ni vitola.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist H. Upmann — die José Martí, so benannt seit 1960 —, die mehrmals umzog und seit 2011 das frühere Romeo-y-Julieta-Gebäude an der Belascoaín in Centro Habana belegt. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie in die 1960er Jahre und nennt sie nummeriert wie Montecristo, aus der sie hervorging; sie nennt ihre Fabrik nicht, die die Fachpresse bei H. Upmann verortet, wie Montecristo.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist H. Upmann — die José Martí, so benannt seit 1960 —, die mehrmals umzog und seit 2011 das frühere Romeo-y-Julieta-Gebäude an der Belascoaín in Centro Habana belegt. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie in die 1960er Jahre und nennt sie nummeriert wie Montecristo, aus der sie hervorging; sie nennt ihre Fabrik nicht, die die Fachpresse bei H. Upmann verortet, wie Montecristo.', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt keine Fabrik. Eine Reportage der Fachpresse (2011) schreibt, die Fabrik Romeo y Julieta / H. Upmann an der Belascoaín betreue die Marke, doch im Mai sei dort keine Diplomáticos gerollt worden; Wikipedia sagt, sie werde in der Fabrik José Martí in Havanna hergestellt. Im Oktober 2026 zählt habanos.com sie zu den dreizehn übrigen Marken des Portfolios von siebenundzwanzig, außerhalb der sechs globalen, der fünf Wertmarken und der drei Volumenmarken; die Fachpresse zählte 2019 einundzwanzig Portfoliomarken, Diplomáticos in der Kategorie der übrigen. Die offizielle Seite nennt sie relativ jung, aus den 1960er Jahren, mit ausgeprägter Ähnlichkeit zu Montecristo und mit Formaten, die durch Nummern statt durch Namen bezeichnet werden; sie nennt weder Fabrik noch Vitola.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是乌普曼——即1960年起得名的 José Martí 厂——几度搬迁，2011年起占用中哈瓦那贝拉斯科艾因街原罗密欧与朱丽叶厂房。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把它定在1960年代，并说它像 Montecristo 一样以数字命名，它正是从后者衍生；页面没有点名工厂，行业媒体把它和 Montecristo 一样放在乌普曼厂。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是乌普曼——即1960年起得名的 José Martí 厂——几度搬迁，2011年起占用中哈瓦那贝拉斯科艾因街原罗密欧与朱丽叶厂房。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把它定在1960年代，并说它像 Montecristo 一样以数字命名，它正是从后者衍生；页面没有点名工厂，行业媒体把它和 Montecristo 一样放在乌普曼厂。', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有点名任何工厂。行业媒体的一篇报道（2011年）写道，贝拉斯科艾因街的 Romeo y Julieta / H. Upmann 厂负责这个品牌，但5月那里并没有卷制任何 Diplomáticos；维基百科说它在哈瓦那的 José Martí 厂制造。2026年10月，habanos.com 把它列入二十七个组合品牌中的其余十三个，不在六个全球品牌、五个价值品牌与三个量产品牌之列；行业媒体2019年统计有二十一个组合品牌，Diplomáticos 在其余品牌一类。官方页面称它相对较新，始于1960年代，与 Montecristo 极为相似，规格以数字而非名称命名；页面既没有点名工厂，也没有点名规格。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو H. Upmann — مصنع خوسيه مارتي، بهذا الاسم منذ 1960 — الذي غيّر عنوانه مرارًا ويشغل منذ 2011 مبنى Romeo y Julieta السابق في بيلاسكوين، سنترو هابانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤرّخها الصفحة الرسمية في الستينيات وتقول إنّها مرقّمة مثل Montecristo التي وُلدت منها؛ ولا تسمّي مصنعها، الذي تضعه الصحافة المتخصّصة عند H. Upmann مثل Montecristo.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو H. Upmann — مصنع خوسيه مارتي، بهذا الاسم منذ 1960 — الذي غيّر عنوانه مرارًا ويشغل منذ 2011 مبنى Romeo y Julieta السابق في بيلاسكوين، سنترو هابانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤرّخها الصفحة الرسمية في الستينيات وتقول إنّها مرقّمة مثل Montecristo التي وُلدت منها؛ ولا تسمّي مصنعها، الذي تضعه الصحافة المتخصّصة عند H. Upmann مثل Montecristo.', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي Habanos أيّ مصنع. ويكتب تقرير للصحافة المتخصّصة (2011) أنّ مصنع Romeo y Julieta / H. Upmann في بيلاسكوين مكلّف بالعلامة، لكن لم يكن يُلفّ فيه أيّ Diplomáticos في مايو؛ وتقول ويكيبيديا إنّها تُصنع في مصنع خوسيه مارتي في هافانا. في أكتوبر 2026 تصنّفها habanos.com ضمن العلامات الثلاث عشرة الأخرى من محفظة السبع والعشرين، خارج العلامات العالمية الست وعلامات القيمة الخمس وعلامات الحجم الثلاث؛ وكانت الصحافة المتخصّصة تحصي عام 2019 إحدى وعشرين علامة في المحفظة، وDiplomáticos في فئة الأخرى. تصفها الصفحة الرسمية بأنها حديثة نسبياً، من الستينيات، شديدة الشبه بـ Montecristo ومقاساتها تُسمّى بأرقام لا بأسماء؛ ولا تسمّي مصنعاً ولا مقاساً.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Diplomáticos';

UPDATE `brands` SET
  `limited_eds` = '["Diplomáticos Excelencia (Edición Regional Cuba, 2015)","Diplomáticos Reserva Especial (Edición Regional Caraïbes et Amérique centrale, 2021)","Diplomáticos Leal (Edición Regional Cuba, 2023)","Diplomáticos Genios (Edición Regional Phoenicia)"]',
  `founded` = '1966 (presse du métier) — La Havane, Cuba',
  `factory` = 'Habanos ne nomme pas la fabrique ; la presse du métier (2011) cite la fabrique H. Upmann de Belascoaín, Wikipédia la José Martí',
  `gamme` = '[{"name":"No.2","color":"#8B4513","force":"Medium-Full","story":"Pirámide : 6 1/8 pouces sur cepo 52 (156 mm), selon Wikipédia ; seule taille que la presse du métier dit rester dans la gamme courante en octobre 2025. Force moyenne à forte pour la marque, tripe longue, tabac de Vuelta Abajo, dit habanos.com.","vitolas":["Pirámide"],"wrapper":"Vuelta Abajo"},{"name":"No.4","color":"#A0522D","force":"Medium","story":"Mareva : 5 1/8 pouces sur cepo 42 (130 mm), listé par Wikipédia ; la presse du métier écrivait pourtant en octobre 2025 que seul le No. 2 reste dans la gamme courante : les versions divergent.","vitolas":["Mareva"],"wrapper":"Vuelta Abajo"},{"name":"Cancilleres","color":"#5c3317","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"5 1/8 pouces sur cepo 50, coffret de 25, lancé à Sofia fin novembre 2025 ; présenté par la presse du métier comme la première nouvelle taille de production régulière de la marque depuis des décennies. Têtes montées, sans pigtail."}]',
  `gamme_en` = '[{"name":"No.2","color":"#8B4513","force":"Medium-Full","story":"Pirámide: 6 1/8 inches on ring gauge 52 (156 mm), according to Wikipedia; the only size that the trade press says remains in the current range in October 2025. Medium to strong strength for the brand, long filler, Vuelta Abajo tobacco, says habanos.com.","vitolas":["Pirámide"],"wrapper":"Vuelta Abajo"},{"name":"No.4","color":"#A0522D","force":"Medium","story":"Mareva: 5 1/8 inches on ring gauge 42 (130 mm), listed by Wikipedia; the trade press nevertheless wrote in October 2025 that only the No. 2 remains in the current range: the accounts diverge.","vitolas":["Mareva"],"wrapper":"Vuelta Abajo"},{"name":"Cancilleres","color":"#5c3317","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"5 1/8 inches on ring gauge 50, box of 25, launched in Sofia at the end of November 2025; presented by the trade press as the brand''s first new regular-production size in decades. Capped heads, no pigtail."}]',
  `gamme_es` = '[{"name":"No.2","color":"#8B4513","force":"Medium-Full","story":"Pirámide: 6 1/8 pulgadas sobre cepo 52 (156 mm), según Wikipedia; único tamaño que la prensa del oficio dice que sigue en la gama corriente en octubre de 2025. Fuerza media a fuerte para la marca, tripa larga, tabaco de Vuelta Abajo, dice habanos.com.","vitolas":["Pirámide"],"wrapper":"Vuelta Abajo"},{"name":"No.4","color":"#A0522D","force":"Medium","story":"Mareva: 5 1/8 pulgadas sobre cepo 42 (130 mm), listado por Wikipedia; la prensa del oficio escribía sin embargo en octubre de 2025 que solo el No. 2 sigue en la gama corriente: las versiones divergen.","vitolas":["Mareva"],"wrapper":"Vuelta Abajo"},{"name":"Cancilleres","color":"#5c3317","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"5 1/8 pulgadas sobre cepo 50, caja de 25, lanzado en Sofía a finales de noviembre de 2025; presentado por la prensa del oficio como el primer tamaño nuevo de producción regular de la marca en décadas. Cabezas montadas, sin pigtail."}]',
  `gamme_de` = '[{"name":"No.2","color":"#8B4513","force":"Medium-Full","story":"Pirámide: 6 1/8 Zoll bei Ringmaß 52 (156 mm), laut Wikipedia; die einzige Größe, die nach Angabe der Fachpresse im Oktober 2025 im laufenden Sortiment bleibt. Für die Marke mittlere bis starke Stärke, lange Einlage, Tabak aus Vuelta Abajo, sagt habanos.com.","vitolas":["Pirámide"],"wrapper":"Vuelta Abajo"},{"name":"No.4","color":"#A0522D","force":"Medium","story":"Mareva: 5 1/8 Zoll bei Ringmaß 42 (130 mm), von Wikipedia aufgeführt; die Fachpresse schrieb im Oktober 2025 dennoch, nur die No. 2 verbleibe im laufenden Sortiment: Die Darstellungen weichen voneinander ab.","vitolas":["Mareva"],"wrapper":"Vuelta Abajo"},{"name":"Cancilleres","color":"#5c3317","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"5 1/8 Zoll bei Ringmaß 50, 25er-Kiste, Ende November 2025 in Sofia eingeführt; von der Fachpresse als erstes neues Format regulärer Produktion der Marke seit Jahrzehnten bezeichnet. Montierte Köpfe, ohne Pigtail."}]',
  `gamme_zh` = '[{"name":"No.2","color":"#8B4513","force":"Medium-Full","story":"金字塔形（Pirámide）：6 1/8 英寸，环径52（156mm），据维基百科；这是行业媒体称2025年10月仍留在现行产品线中的唯一尺寸。就该品牌而言力度中等至浓，长茄芯，Vuelta Abajo 烟叶，habanos.com 如是说。","vitolas":["Pirámide"],"wrapper":"Vuelta Abajo"},{"name":"No.4","color":"#A0522D","force":"Medium","story":"Mareva：5 1/8 英寸，环径42（130mm），维基百科有列出；然而行业媒体在2025年10月写道，现行产品线中只剩 No. 2：说法不一。","vitolas":["Mareva"],"wrapper":"Vuelta Abajo"},{"name":"Cancilleres","color":"#5c3317","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"5 1/8 英寸，环径50，25支装盒装，2025年11月底在索非亚推出；行业媒体称其为该品牌数十年来首款常规生产的新尺寸。烟头已封好，不带辫尾。"}]',
  `gamme_ar` = '[{"name":"No.2","color":"#8B4513","force":"Medium-Full","story":"Pirámide: 6 1/8 بوصة على عيار 52 (156 مم)، بحسب ويكيبيديا؛ وهو المقاس الوحيد الذي تقول الصحافة المتخصّصة إنّه يبقى في التشكيلة الجارية في أكتوبر 2025. قوة متوسطة إلى شديدة بالنسبة إلى العلامة، حشوة طويلة، تبغ Vuelta Abajo، كما تقول habanos.com.","vitolas":["Pirámide"],"wrapper":"Vuelta Abajo"},{"name":"No.4","color":"#A0522D","force":"Medium","story":"Mareva: 5 1/8 بوصة على عيار 42 (130 مم)، تدرجه ويكيبيديا؛ ومع ذلك كتبت الصحافة المتخصّصة في أكتوبر 2025 أنّ No. 2 وحده يبقى في التشكيلة الجارية: الروايات متباينة.","vitolas":["Mareva"],"wrapper":"Vuelta Abajo"},{"name":"Cancilleres","color":"#5c3317","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"5 1/8 بوصة على عيار 50، علبة من 25، أُطلق في صوفيا نهاية نوفمبر 2025؛ وتقدّمه الصحافة المتخصّصة على أنّه أول مقاس جديد من الإنتاج المنتظم للعلامة منذ عقود. رؤوس مركّبة بلا ضفيرة طرفية."}]',
  `celebrities` = '[]',
  `celebrities_en` = '[]',
  `celebrities_es` = '[]',
  `celebrities_de` = '[]',
  `celebrities_zh` = '[]',
  `celebrities_ar` = '[]',
  `pairings` = '[{"type":"Café","name":"Cappuccino","notes":"Suggestion : un café au lait pour un cigare de force moyenne à forte."},{"type":"Spiritueux","name":"Armagnac","notes":"Suggestion : un spiritueux de raisin vieilli pour une force moyenne à forte."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Cappuccino","notes":"Suggestion: a milky coffee for a cigar of medium to strong strength."},{"type":"Spirits","name":"Armagnac","notes":"Suggestion: an aged grape spirit for a medium to strong strength."}]',
  `pairings_es` = '[{"type":"Café","name":"Capuchino","notes":"Sugerencia: un café con leche para un puro de fuerza media a fuerte."},{"type":"Destilados","name":"Armañac","notes":"Sugerencia: un destilado de uva envejecido para una fuerza media a fuerte."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Cappuccino","notes":"Vorschlag: ein Milchkaffee zu einer Zigarre von mittlerer bis starker Stärke."},{"type":"Spirituosen","name":"Armagnac","notes":"Vorschlag: ein gereiftes Traubendestillat zu mittlerer bis starker Stärke."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"卡布奇诺","notes":"建议：搭配欧蕾咖啡，适合中等至浓烈力度的雪茄。"},{"type":"烈酒","name":"雅文邑","notes":"建议：陈酿的葡萄蒸馏酒，适合中等至浓烈的力度。"}]',
  `pairings_ar` = '[{"type":"قهوة","name":"كابوتشينو","notes":"اقتراح: قهوة بالحليب لسيجار بقوة متوسطة إلى شديدة."},{"type":"مشروبات روحية","name":"أرمانياك","notes":"اقتراح: مشروب روحي معتّق من العنب لقوة متوسطة إلى شديدة."}]',
  `source` = IF(LOCATE(CAST('cubancigarwebsite.com « Tobacco and Cigar Production » (H. Upmann mère de Montecristo et Diplomáticos) ; ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cubancigarwebsite.com « Tobacco and Cigar Production » (H. Upmann mère de Montecristo et Diplomáticos) ; ', ''), `source`),
  `source` = IF(LOCATE(CAST('Diplomáticos roulée à la fabrique de Belascoaín' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'Diplomáticos roulée à la fabrique de Belascoaín', 'la fabrique H. Upmann de Belascoaín a la charge de la marque, aucun Diplomáticos n''y étant roulé en mai'), `source`),
  `source` = IF(LOCATE(CAST(' ; créée en 1966 pour le marché français selon l''ancienne lecture de la page' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; créée en 1966 pour le marché français selon l''ancienne lecture de la page', ''), `source`),
  `source` = IF(LOCATE(CAST('habanos.com « Diplomáticos Brand » et version espagnole (san' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'habanos.com « Diplomáticos Brand » et version espagnole (sans date, lues le 16 octobre 2026 : années 1960, ressemblance avec Montecristo, tripe longue, Vuelta Abajo, medium à full) ; cigaraficionado.com « New Diplomaticos From Cuba Debuting in Late November » (14 octobre 2025 : créée en 1966, seul le No. 2 dans la gamme courante) et « Cuban Diplomaticos Premieres in Bulgaria Sans Pigtail » (1er décembre 2025 : Cancilleres 5 1/8 x 50) ; en.wikipedia.org « Diplomáticos (brand) » (1966, cotes des No. 2 et 4, José Martí) ; cigaraficionado.com « A Regional Edition Diplomaticos Just For Cuba » (26 décembre 2023 : Leal) ; habanos.com « New Regional Edition for the Caribbean and Central America » (27 août 2021 : Reserva Especial)')),
  `updated_at` = NOW()
 WHERE `name` = 'Diplomáticos';

-- ── Cuaba ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Cuaba est une marque de résurrection. Lancée en 1996, elle a été créée pour faire revivre une forme abandonnée depuis les années 1940 : le double figurado, effilé aux deux extrémités, que les rouleurs du XIXe siècle produisaient couramment et que la mécanisation du XXe a fait disparaître des catalogues.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Cuaba est une marque de résurrection. Lancée en 1996, elle a été créée pour faire revivre une forme abandonnée depuis les années 1940 : le double figurado, effilé aux deux extrémités, que les rouleurs du XIXe siècle produisaient couramment et que la mécanisation du XXe a fait disparaître des catalogues.', 'Cuaba est une marque de résurrection. Lancée en 1996, elle reprend le double figurado, effilé aux deux extrémités, un style à la mode à la fin du XIXe siècle que habanos.com dit relancé un siècle plus tard, en 1996, à la fabrique Romeo y Julieta. Wikipédia écrit que Habanos la lança le 19 novembre 1996 à Londres, au Claridge''s, et que les figurados, populaires au début du XXe siècle, déclinèrent à partir des années 1950.'), `history`),
  `history_en` = IF(LOCATE(CAST('Cuaba is a brand of resurrection. Launched in 1996, it was created to bring back a shape abandoned since the 1940s: the double figurado, tapered at both ends, which nineteenth-century rollers produced routinely and which the mechanisation of the twentieth made disappear from the catalogues.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Cuaba is a brand of resurrection. Launched in 1996, it was created to bring back a shape abandoned since the 1940s: the double figurado, tapered at both ends, which nineteenth-century rollers produced routinely and which the mechanisation of the twentieth made disappear from the catalogues.', 'Cuaba is a brand of resurrection. Launched in 1996, it takes up the double figurado, tapered at both ends, a style in fashion in the late nineteenth century that habanos.com says was revived a century later, in 1996, at the Romeo y Julieta factory. Wikipedia writes that Habanos launched it on 19 November 1996 in London, at Claridge''s, and that figurados, popular in the early twentieth century, declined from the 1950s.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Cuaba es una marca de resurrección. Lanzada en 1996, fue creada para hacer revivir una forma abandonada desde los años cuarenta: el doble figurado, afilado en ambos extremos, que los torcedores del siglo XIX producían corrientemente y que la mecanización del siglo XX hizo desaparecer de los catálogos.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Cuaba es una marca de resurrección. Lanzada en 1996, fue creada para hacer revivir una forma abandonada desde los años cuarenta: el doble figurado, afilado en ambos extremos, que los torcedores del siglo XIX producían corrientemente y que la mecanización del siglo XX hizo desaparecer de los catálogos.', 'Cuaba es una marca de resurrección. Lanzada en 1996, retoma el doble figurado, afilado en ambos extremos, un estilo de moda a finales del siglo XIX que habanos.com dice relanzado un siglo después, en 1996, en la fábrica Romeo y Julieta. Wikipedia escribe que Habanos la lanzó el 19 de noviembre de 1996 en Londres, en el Claridge''s, y que los figurados, populares a principios del siglo XX, declinaron a partir de los años cincuenta.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Cuaba ist eine Marke der Wiederauferstehung. 1996 auf den Markt gebracht, wurde sie geschaffen, um eine seit den 1940er Jahren aufgegebene Form wiederzubeleben: das doppelte Figurado, an beiden Enden zulaufend, das die Roller des 19. Jahrhunderts routinemäßig herstellten und das die Mechanisierung des 20. aus den Katalogen verschwinden ließ.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Cuaba ist eine Marke der Wiederauferstehung. 1996 auf den Markt gebracht, wurde sie geschaffen, um eine seit den 1940er Jahren aufgegebene Form wiederzubeleben: das doppelte Figurado, an beiden Enden zulaufend, das die Roller des 19. Jahrhunderts routinemäßig herstellten und das die Mechanisierung des 20. aus den Katalogen verschwinden ließ.', 'Cuaba ist eine Marke der Wiederauferstehung. 1996 eingeführt, greift sie das doppelte Figurado auf, an beiden Enden zulaufend, einen Stil, der Ende des 19. Jahrhunderts in Mode war und von dem habanos.com sagt, er sei ein Jahrhundert später, 1996, in der Fabrik Romeo y Julieta wieder aufgelegt worden. Wikipedia schreibt, Habanos habe sie am 19. November 1996 in London im Claridge''s vorgestellt, und die Figurados, Anfang des 20. Jahrhunderts beliebt, seien ab den 1950er Jahren zurückgegangen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('库阿巴是一个「复活」的品牌。它于1996年推出，目的是让一种自1940年代起被弃用的形制重生：两端渐尖的双头异形茄——十九世纪的卷制师常做这种形状，而二十世纪的机械化让它从产品目录中消失。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '库阿巴是一个「复活」的品牌。它于1996年推出，目的是让一种自1940年代起被弃用的形制重生：两端渐尖的双头异形茄——十九世纪的卷制师常做这种形状，而二十世纪的机械化让它从产品目录中消失。', '库阿巴是一个「复活」的品牌。它于1996年推出，重拾两端渐尖的双头异形茄——这是十九世纪末流行的样式，habanos.com 称其一个世纪后即1996年在 Romeo y Julieta 工厂重新推出。维基百科写道，Habanos 于1996年11月19日在伦敦的 Claridge''s 酒店推出该品牌，而异形茄在二十世纪初流行，自1950年代起衰落。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('«كوابا» علامة بَعْث. أُطلقت سنة 1996 لإحياء شكلٍ مهجور منذ الأربعينيات: «الفيغورادو المزدوج»، المدبّب من طرفيه، الذي كان لافّو القرن التاسع عشر ينتجونه بانتظام وأزالته مكننةُ القرن العشرين من الكتالوغات.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '«كوابا» علامة بَعْث. أُطلقت سنة 1996 لإحياء شكلٍ مهجور منذ الأربعينيات: «الفيغورادو المزدوج»، المدبّب من طرفيه، الذي كان لافّو القرن التاسع عشر ينتجونه بانتظام وأزالته مكننةُ القرن العشرين من الكتالوغات.', '«كوابا» علامة بَعْث. أُطلقت سنة 1996، وهي تستعيد الفيغورادو المزدوج، المدبّب من طرفيه، وهو طراز كان رائجاً في أواخر القرن التاسع عشر وتقول habanos.com إنه أُعيد إطلاقه بعد قرن، سنة 1996، في مصنع Romeo y Julieta. وتكتب ويكيبيديا أنّ Habanos أطلقتها في 19 نوفمبر 1996 في لندن، في فندق Claridge''s، وأنّ الفيغورادو، الذائعة في مطلع القرن العشرين، تراجعت ابتداءً من خمسينيات القرن الماضي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuaba';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La forme n''est pas un caprice esthétique. Un cigare effilé aux deux bouts commence étroit, s''élargit, puis se resserre : le volume de fumée et la concentration des arômes changent en continu, ce qu''un format droit ne fait jamais. Elle est aussi beaucoup plus difficile à rouler, ce qui explique qu''elle ait été abandonnée et pourquoi Cuaba est confiée à des torcedores expérimentés.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La forme n''est pas un caprice esthétique. Un cigare effilé aux deux bouts commence étroit, s''élargit, puis se resserre : le volume de fumée et la concentration des arômes changent en continu, ce qu''un format droit ne fait jamais. Elle est aussi beaucoup plus difficile à rouler, ce qui explique qu''elle ait été abandonnée et pourquoi Cuaba est confiée à des torcedores expérimentés.', 'Habanos présente les doubles figurados comme le sommet de l''art du rouleur de cigares. Wikipédia écrit que chaque Cuaba est roulé à la main par des rouleurs de grade 7, le plus haut niveau de certification, et que les premiers, faits sans moule, variaient légèrement de taille, les moules n''arrivant qu''environ un an plus tard. Les tailles d''origine étaient Divinos, Tradicionales, Generosos et Exclusivos ; Distinguido, Diadema et Salomón les ont rejointes au portefeuille régulier en 2003, dit habanos.com.'), `history`),
  `history_en` = IF(LOCATE(CAST('The shape is not an aesthetic whim. A cigar tapered at both ends begins narrow, widens, then narrows again: the volume of smoke and the concentration of aromas change continuously, which a straight format never does. It is also far harder to roll, which explains why it was abandoned and why Cuaba is entrusted to experienced torcedores.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The shape is not an aesthetic whim. A cigar tapered at both ends begins narrow, widens, then narrows again: the volume of smoke and the concentration of aromas change continuously, which a straight format never does. It is also far harder to roll, which explains why it was abandoned and why Cuaba is entrusted to experienced torcedores.', 'Habanos presents double figurados as the pinnacle of the cigar roller''s art. Wikipedia writes that every Cuaba is hand-rolled by grade 7 rollers, the highest level of certification, and that the first ones, made without a mould, varied slightly in size, the moulds arriving only about a year later. The original sizes were Divinos, Tradicionales, Generosos and Exclusivos; Distinguido, Diadema and Salomón joined them in the regular portfolio in 2003, says habanos.com.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La forma no es un capricho estético. Un cigarro afilado en los dos extremos empieza estrecho, se ensancha y luego se estrecha: el volumen de humo y la concentración de aromas cambian continuamente, cosa que un formato recto nunca hace. Es además mucho más difícil de liar, lo que explica que se abandonara y por qué Cuaba se confía a torcedores experimentados.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La forma no es un capricho estético. Un cigarro afilado en los dos extremos empieza estrecho, se ensancha y luego se estrecha: el volumen de humo y la concentración de aromas cambian continuamente, cosa que un formato recto nunca hace. Es además mucho más difícil de liar, lo que explica que se abandonara y por qué Cuaba se confía a torcedores experimentados.', 'Habanos presenta los dobles figurados como la cumbre del arte del torcedor de puros. Wikipedia escribe que cada Cuaba se lía a mano por torcedores de grado 7, el nivel más alto de certificación, y que los primeros, hechos sin molde, variaban ligeramente de tamaño, pues los moldes llegaron solo un año después, aproximadamente. Los tamaños de origen eran Divinos, Tradicionales, Generosos y Exclusivos; Distinguido, Diadema y Salomón se les unieron en el portafolio regular en 2003, dice habanos.com.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Form ist keine ästhetische Laune. Eine an beiden Enden zulaufende Zigarre beginnt schmal, weitet sich und verengt sich wieder: Rauchvolumen und Aromenkonzentration verändern sich fortwährend, was ein gerades Format nie tut. Sie ist zudem weit schwerer zu rollen, was erklärt, warum sie aufgegeben wurde und warum Cuaba erfahrenen Torcedores anvertraut wird.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Form ist keine ästhetische Laune. Eine an beiden Enden zulaufende Zigarre beginnt schmal, weitet sich und verengt sich wieder: Rauchvolumen und Aromenkonzentration verändern sich fortwährend, was ein gerades Format nie tut. Sie ist zudem weit schwerer zu rollen, was erklärt, warum sie aufgegeben wurde und warum Cuaba erfahrenen Torcedores anvertraut wird.', 'Habanos stellt die doppelten Figurados als Gipfel der Kunst des Zigarrenrollers dar. Wikipedia schreibt, jede Cuaba werde von Rollern der Stufe 7 von Hand gerollt, der höchsten Zertifizierungsstufe, und die ersten, ohne Form hergestellt, hätten in der Größe leicht variiert, da die Formen erst etwa ein Jahr später kamen. Die ursprünglichen Größen waren Divinos, Tradicionales, Generosos und Exclusivos; Distinguido, Diadema und Salomón stießen 2003 zum regulären Portfolio, sagt habanos.com.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这个形状并非审美上的任性。两端渐尖的雪茄由窄而宽、再由宽而窄：烟量与香气浓度持续变化，这是直筒尺寸永远做不到的。它也远比直筒难卷，这既解释了它为何被弃用，也解释了为何库阿巴要交给经验丰富的卷制师。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这个形状并非审美上的任性。两端渐尖的雪茄由窄而宽、再由宽而窄：烟量与香气浓度持续变化，这是直筒尺寸永远做不到的。它也远比直筒难卷，这既解释了它为何被弃用，也解释了为何库阿巴要交给经验丰富的卷制师。', 'Habanos 将双头异形茄视为卷制师技艺的巅峰。维基百科写道，每支 Cuaba 都由7级卷制师手工卷制，这是认证的顶级水平；头几批不用模具，尺寸略有差异，模具大约一年后才出现。原始尺寸为 Divinos、Tradicionales、Generosos 和 Exclusivos；Distinguido、Diadema 和 Salomón 于2003年加入常规产品线，habanos.com 如是说。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('والشكل ليس نزوة جمالية. فالسيجار المدبّب من طرفيه يبدأ ضيّقاً، ثم يتّسع، ثم يضيق مجدّداً: يتغيّر حجم الدخان وتركيز النكهات باستمرار، وهو ما لا يفعله المقاس المستقيم أبداً. كما أنه أصعب لفّاً بكثير، ما يفسّر هجره ويفسّر لماذا تُوكَل «كوابا» إلى لافّين مخضرمين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'والشكل ليس نزوة جمالية. فالسيجار المدبّب من طرفيه يبدأ ضيّقاً، ثم يتّسع، ثم يضيق مجدّداً: يتغيّر حجم الدخان وتركيز النكهات باستمرار، وهو ما لا يفعله المقاس المستقيم أبداً. كما أنه أصعب لفّاً بكثير، ما يفسّر هجره ويفسّر لماذا تُوكَل «كوابا» إلى لافّين مخضرمين.', 'تقدّم Habanos الفيغورادو المزدوج بوصفه قمّة فنّ لافّ السيجار. وتكتب ويكيبيديا أنّ كلّ Cuaba يلفّه يدوياً لافّون من الدرجة 7، وهي أرفع مستويات الاعتماد، وأنّ الأوائل منها، المصنوعة بلا قالب، كانت تتفاوت قليلاً في الحجم، إذ لم تصل القوالب إلا بعد نحو سنة. وكانت المقاسات الأصلية Divinos وTradicionales وGenerosos وExclusivos؛ وانضمّت إليها Distinguido وDiadema وSalomón إلى المحفظة النظامية سنة 2003، بحسب habanos.com.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuaba';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le profil est médium à corsé, avec des notes de bois épicé, de poivre et de fruits secs, et une intensité qui culmine au deuxième tiers — exactement là où le diamètre est maximal.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le profil est médium à corsé, avec des notes de bois épicé, de poivre et de fruits secs, et une intensité qui culmine au deuxième tiers — exactement là où le diamètre est maximal.', 'Habanos décrit la marque de force moyenne à pleine (medium to full), avec une cape et une tripe de la Vuelta Abajo, à Pinar del Río.'), `history`),
  `history_en` = IF(LOCATE(CAST('The profile is medium to full, with notes of spiced wood, pepper and dried fruit, and an intensity that peaks in the second third — exactly where the diameter is greatest.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The profile is medium to full, with notes of spiced wood, pepper and dried fruit, and an intensity that peaks in the second third — exactly where the diameter is greatest.', 'Habanos describes the brand as medium to full in strength, with a wrapper and filler from the Vuelta Abajo, in Pinar del Río.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El perfil es medio a fuerte, con notas de madera especiada, pimienta y frutos secos, y una intensidad que culmina en el segundo tercio — exactamente donde el diámetro es máximo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El perfil es medio a fuerte, con notas de madera especiada, pimienta y frutos secos, y una intensidad que culmina en el segundo tercio — exactamente donde el diámetro es máximo.', 'Habanos describe la marca como de fuerza media a plena, con capa y tripa de la Vuelta Abajo, en Pinar del Río.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Profil ist medium bis kräftig, mit Noten von würzigem Holz, Pfeffer und Trockenfrüchten, und einer Intensität, die im zweiten Drittel gipfelt — genau dort, wo der Durchmesser am größten ist.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Profil ist medium bis kräftig, mit Noten von würzigem Holz, Pfeffer und Trockenfrüchten, und einer Intensität, die im zweiten Drittel gipfelt — genau dort, wo der Durchmesser am größten ist.', 'Habanos beschreibt die Marke als von mittlerer bis voller Stärke, mit Deckblatt und Einlage aus der Vuelta Abajo in Pinar del Río.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('其风格属中至浓，带香料木质、胡椒与干果的气息，强度在第二段达到顶峰——恰是直径最大之处。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '其风格属中至浓，带香料木质、胡椒与干果的气息，强度在第二段达到顶峰——恰是直径最大之处。', 'Habanos 称该品牌力度中等至饱满，茄衣与茄芯均来自 Pinar del Río 的 Vuelta Abajo。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('الطابع متوسط إلى قويّ، بنفحات خشب متبَّل وفلفل وفواكه مجفّفة، وشدّة تبلغ ذروتها في الثلث الثاني — تماماً حيث يبلغ القطر أقصاه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'الطابع متوسط إلى قويّ، بنفحات خشب متبَّل وفلفل وفواكه مجفّفة، وشدّة تبلغ ذروتها في الثلث الثاني — تماماً حيث يبلغ القطر أقصاه.', 'تصف Habanos العلامة بأنها ذات قوة متوسطة إلى تامّة، بغلاف وحشوة من Vuelta Abajo في Pinar del Río.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuaba';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le nom vient d''un arbuste cubain dont les Taïnos utilisaient l''écorce pour allumer leurs feux, et que les premiers Espagnols ont vu servir à allumer le tabac.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le nom vient d''un arbuste cubain dont les Taïnos utilisaient l''écorce pour allumer leurs feux, et que les premiers Espagnols ont vu servir à allumer le tabac.', 'Le nom est, dit habanos.com, un mot indien de l''époque de Christophe Colomb pour un buisson très combustible qui servait à allumer les cigares lors de cérémonies religieuses ; la presse du métier y voit un buisson que les Taïnos employaient pour allumer leurs cigares.'), `history`),
  `history_en` = IF(LOCATE(CAST('The name comes from a Cuban shrub whose bark the Taíno used to light their fires, and which the first Spaniards saw serving to light tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The name comes from a Cuban shrub whose bark the Taíno used to light their fires, and which the first Spaniards saw serving to light tobacco.', 'The name is, says habanos.com, an Indian word from the time of Christopher Columbus for a highly combustible bush that was used to light cigars during religious ceremonies; the trade press sees in it a bush that the Taíno used to light their cigars.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El nombre viene de un arbusto cubano cuya corteza usaban los taínos para encender sus fuegos, y que los primeros españoles vieron servir para encender el tabaco.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El nombre viene de un arbusto cubano cuya corteza usaban los taínos para encender sus fuegos, y que los primeros españoles vieron servir para encender el tabaco.', 'El nombre es, dice habanos.com, una palabra india de la época de Cristóbal Colón para un arbusto muy combustible que servía para encender los puros en ceremonias religiosas; la prensa del oficio ve en él un arbusto que los taínos empleaban para encender sus puros.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Name stammt von einem kubanischen Strauch, dessen Rinde die Taíno zum Entfachen ihrer Feuer nutzten und den die ersten Spanier zum Anzünden von Tabak dienen sahen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Name stammt von einem kubanischen Strauch, dessen Rinde die Taíno zum Entfachen ihrer Feuer nutzten und den die ersten Spanier zum Anzünden von Tabak dienen sahen.', 'Der Name ist, sagt habanos.com, ein indianisches Wort aus der Zeit von Christoph Kolumbus für einen leicht brennbaren Strauch, der bei religiösen Zeremonien zum Anzünden von Zigarren diente; die Fachpresse sieht darin einen Strauch, den die Taíno zum Anzünden ihrer Zigarren nutzten.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这个名字来自一种古巴灌木，泰诺人用它的树皮生火，而最初到来的西班牙人看到它被用来点燃烟草。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这个名字来自一种古巴灌木，泰诺人用它的树皮生火，而最初到来的西班牙人看到它被用来点燃烟草。', '这个名字，habanos.com 称，是克里斯托弗·哥伦布时代的一个印第安词，指一种极易燃的灌木，宗教仪式上用它点燃雪茄；行业媒体则认为那是泰诺人用来点燃雪茄的灌木。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أمّا الاسم فمن شجيرة كوبية كان التاينو يستخدمون لحاءها لإشعال نيرانهم، ورآها الإسبان الأوائل تُستخدم لإشعال التبغ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أمّا الاسم فمن شجيرة كوبية كان التاينو يستخدمون لحاءها لإشعال نيرانهم، ورآها الإسبان الأوائل تُستخدم لإشعال التبغ.', 'الاسم، بحسب habanos.com، كلمة هندية من زمن كريستوفر كولومبوس تدلّ على شجيرة شديدة الاشتعال كانت تُستخدم لإشعال السيجار في الاحتفالات الدينية؛ أمّا الصحافة المتخصّصة فترى فيه شجيرة كان التاينو يستخدمونها لإشعال سيجارهم.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuaba';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la fait naître en 1996 à la fabrique Romeo y Julieta, qui remit au goût du jour les doubles figurados ; la presse du métier place ensuite sa fabrique mère à La Corona. Tout est roulé à la main en tripe longue.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la fait naître en 1996 à la fabrique Romeo y Julieta, qui remit au goût du jour les doubles figurados ; la presse du métier place ensuite sa fabrique mère à La Corona. Tout est roulé à la main en tripe longue.', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, avenue 20 de Mayo, au Cerro, ancienne fabrique de cigarettes transformée en fabrique de cigares en 2000, dit la presse du métier (2011 et 2015), qui la nomme mère de Cuaba, de Hoyo de Monterrey et de Punch. En octobre 2026, la page The Habanos Brands Academia de habanos.com range Cuaba parmi les treize autres marques d''un portefeuille de 27, hors des six marques globales, des cinq marques de valeur et des trois marques de volume. Habanos écrit que le style de Cuaba a été relancé en 1996 à la fabrique Romeo y Julieta, sans nommer de fabrique mère ; Wikipédia écrit que la plupart des Cuaba sont faits à la fabrique Briones Montoto, celle des Romeo y Julieta, et la presse du métier place la fabrique mère à La Corona : les deux versions s''écrivent. Tout est roulé à la main en tripe longue.'), `history`),
  `history_en` = IF(LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page has it born in 1996 at the Romeo y Julieta factory, which revived double figurados; the trade press then places its mother factory at La Corona. Everything is hand-rolled with long filler.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page has it born in 1996 at the Romeo y Julieta factory, which revived double figurados; the trade press then places its mother factory at La Corona. Everything is hand-rolled with long filler.', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, on 20 de Mayo Avenue, in Cerro, a former cigarette factory converted into a cigar factory in 2000, says the trade press (2011 and 2015), which names it as mother of Cuaba, Hoyo de Monterrey and Punch. In October 2026, the page The Habanos Brands Academia on habanos.com places Cuaba among the thirteen other brands of a portfolio of 27, outside the six global brands, the five value brands and the three volume brands. Habanos writes that the Cuaba style was revived in 1996 at the Romeo y Julieta factory, without naming a mother factory; Wikipedia writes that most Cuaba are made at the Briones Montoto factory, that of Romeo y Julieta, and the trade press places the mother factory at La Corona: both versions are given. Everything is hand-rolled with long filler.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la hace nacer en 1996 en la fábrica Romeo y Julieta, que puso de nuevo de moda los dobles figurados; la prensa del oficio sitúa luego su fábrica madre en La Corona. Todo se lía a mano con tripa larga.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la hace nacer en 1996 en la fábrica Romeo y Julieta, que puso de nuevo de moda los dobles figurados; la prensa del oficio sitúa luego su fábrica madre en La Corona. Todo se lía a mano con tripa larga.', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, avenida 20 de Mayo, en el Cerro, antigua fábrica de cigarrillos transformada en fábrica de puros en 2000, dice la prensa del oficio (2011 y 2015), que la nombra madre de Cuaba, de Hoyo de Monterrey y de Punch. En octubre de 2026, la página Habanos Brands Academia de habanos.com clasifica Cuaba entre las otras trece marcas de un portafolio de 27, fuera de las seis marcas globales, de las cinco marcas de valor y de las tres marcas de volumen. Habanos escribe que el estilo de Cuaba fue relanzado en 1996 en la fábrica Romeo y Julieta, sin nombrar fábrica madre; Wikipedia escribe que la mayoría de los Cuaba se hacen en la fábrica Briones Montoto, la de Romeo y Julieta, y la prensa del oficio sitúa la fábrica madre en La Corona: se escriben las dos versiones. Todo se lía a mano con tripa larga.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite lässt sie 1996 in der Fabrik Romeo y Julieta entstehen, die die Doppelfigurados wiederbelebte; die Fachpresse verortet ihre Mutterfabrik dann bei La Corona. Alles wird von Hand mit Longfiller gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite lässt sie 1996 in der Fabrik Romeo y Julieta entstehen, die die Doppelfigurados wiederbelebte; die Fachpresse verortet ihre Mutterfabrik dann bei La Corona. Alles wird von Hand mit Longfiller gerollt.', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, Avenida 20 de Mayo, im Cerro, eine frühere Zigarettenfabrik, die 2000 zur Zigarrenfabrik umgebaut wurde, sagt die Fachpresse (2011 und 2015), die sie als Mutter von Cuaba, Hoyo de Monterrey und Punch nennt. Im Oktober 2026 reiht die Seite Habanos Brands Academia von habanos.com Cuaba unter die dreizehn übrigen Marken eines Portfolios von 27 ein, außerhalb der sechs globalen Marken, der fünf Wertmarken und der drei Volumenmarken. Habanos schreibt, der Stil von Cuaba sei 1996 in der Fabrik Romeo y Julieta wieder aufgelegt worden, ohne eine Mutterfabrik zu nennen; Wikipedia schreibt, die meisten Cuaba würden in der Fabrik Briones Montoto gefertigt, der von Romeo y Julieta, und die Fachpresse verortet die Mutterfabrik bei La Corona: Beide Versionen werden festgehalten. Alles wird von Hand mit Longfiller gerollt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它1996年诞生于罗密欧与朱丽叶厂，该厂重新推出双头异形雪茄；行业媒体随后把它的母厂定在 La Corona。全部手工长茄芯。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它1996年诞生于罗密欧与朱丽叶厂，该厂重新推出双头异形雪茄；行业媒体随后把它的母厂定在 La Corona。全部手工长茄芯。', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。它的母厂是 La Corona——即 Miguel Fernández Roig 厂——位于塞罗区 20 de Mayo 大道，原为卷烟厂，2000年改建为雪茄厂，行业媒体（2011年和2015年）如是说，并称其为 Cuaba、Hoyo de Monterrey 和 Punch 的母厂。2026年10月，habanos.com 的 Habanos Brands Academia 页面把 Cuaba 列入一个27个品牌的组合中的另外十三个品牌，不在六个全球品牌、五个价值品牌和三个销量品牌之内。Habanos 写道，Cuaba 的风格于1996年在 Romeo y Julieta 工厂重新推出，但未点名母厂；维基百科写道，大部分 Cuaba 在 Briones Montoto 工厂制作，即 Romeo y Julieta 的工厂，而行业媒体把母厂定在 La Corona：两种说法并存。全部手工长茄芯。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تجعلها الصفحة الرسمية تولد سنة 1996 في مصنع Romeo y Julieta الذي أعاد الفيغورادو المزدوج إلى الرواج؛ ثمّ تضع الصحافة المتخصّصة مصنعها الأمّ في La Corona. كلّه ملفوف يدويًّا بحشوة طويلة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تجعلها الصفحة الرسمية تولد سنة 1996 في مصنع Romeo y Julieta الذي أعاد الفيغورادو المزدوج إلى الرواج؛ ثمّ تضع الصحافة المتخصّصة مصنعها الأمّ في La Corona. كلّه ملفوف يدويًّا بحشوة طويلة.', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع Miguel Fernández Roig —، في شارع 20 de Mayo بحيّ سيرو، وهو مصنع سجائر سابق تحوّل إلى مصنع سيجار سنة 2000، بحسب الصحافة المتخصّصة (2011 و2015) التي تسمّيه أمّاً لـCuaba وHoyo de Monterrey وPunch. وفي أكتوبر 2026 تصنّف صفحة Habanos Brands Academia في habanos.com علامة Cuaba ضمن العلامات الثلاث عشرة الأخرى في محفظة من 27 علامة، خارج العلامات العالمية الستّ وعلامات القيمة الخمس وعلامات الحجم الثلاث. وتكتب Habanos أنّ أسلوب Cuaba أُعيد إطلاقه سنة 1996 في مصنع Romeo y Julieta دون أن تسمّي مصنعاً أمّاً؛ وتكتب ويكيبيديا أنّ معظم سيجار Cuaba يُصنع في مصنع Briones Montoto، مصنع Romeo y Julieta، وتضع الصحافة المتخصّصة المصنع الأمّ في La Corona: الروايتان مكتوبتان. كلّه ملفوف يدويًّا بحشوة طويلة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuaba';

UPDATE `brands` SET
  `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, selon la presse du métier ; habanos.com dit le style relancé en 1996 à la fabrique Romeo y Julieta ; Wikipédia cite Briones Montoto',
  `gamme` = '[{"name":"Salomones","color":"#8B4513","force":"Medium-Full","story":"Salomón, entré au portefeuille régulier en 2003 avec Distinguido et Diadema, dit habanos.com. Wikipédia le décrit comme un double perfecto de 184 mm pour un cepo 57 (Salomónes I).","vitolas":["Salomón"],"wrapper":"Vuelta Abajo"},{"name":"Divinos","color":"#A0522D","force":"Medium","story":"L''une des quatre tailles d''origine de la marque, avec Tradicionales, Generosos et Exclusivos, dit habanos.com. Wikipédia la décrit comme un petit perfecto de 102 mm pour un cepo 43, nommé Petit Bouquet.","vitolas":["Petit Bouquet"],"wrapper":"Vuelta Abajo"},{"name":"Distinguidos et Diademas","color":"#7A4A2B","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"Distinguido et Diadema complètent la gamme régulière depuis 2003, dit habanos.com. Wikipédia donne 162 mm pour un cepo 52 au Distinguido et 232 mm pour un cepo 55 à la Diadema, un perfecto de très grande taille."}]',
  `gamme_en` = '[{"name":"Salomones","color":"#8B4513","force":"Medium-Full","story":"Salomón, which joined the regular portfolio in 2003 with Distinguido and Diadema, says habanos.com. Wikipedia describes it as a double perfecto of 184 mm with a cepo of 57 (Salomónes I).","vitolas":["Salomón"],"wrapper":"Vuelta Abajo"},{"name":"Divinos","color":"#A0522D","force":"Medium","story":"One of the brand''s four original sizes, with Tradicionales, Generosos and Exclusivos, says habanos.com. Wikipedia describes it as a small perfecto of 102 mm with a cepo of 43, named Petit Bouquet.","vitolas":["Petit Bouquet"],"wrapper":"Vuelta Abajo"},{"name":"Distinguidos et Diademas","color":"#7A4A2B","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"Distinguido and Diadema have completed the regular range since 2003, says habanos.com. Wikipedia gives 162 mm with a cepo of 52 for the Distinguido and 232 mm with a cepo of 55 for the Diadema, a perfecto of very large size."}]',
  `gamme_es` = '[{"name":"Salomones","color":"#8B4513","force":"Medium-Full","story":"Salomón, que entró en el portafolio regular en 2003 con Distinguido y Diadema, dice habanos.com. Wikipedia lo describe como un doble perfecto de 184 mm para un cepo 57 (Salomónes I).","vitolas":["Salomón"],"wrapper":"Vuelta Abajo"},{"name":"Divinos","color":"#A0522D","force":"Medium","story":"Una de las cuatro tallas de origen de la marca, con Tradicionales, Generosos y Exclusivos, dice habanos.com. Wikipedia la describe como un pequeño perfecto de 102 mm para un cepo 43, llamado Petit Bouquet.","vitolas":["Petit Bouquet"],"wrapper":"Vuelta Abajo"},{"name":"Distinguidos et Diademas","color":"#7A4A2B","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"Distinguido y Diadema completan la gama regular desde 2003, dice habanos.com. Wikipedia da 162 mm para un cepo 52 al Distinguido y 232 mm para un cepo 55 a la Diadema, un perfecto de muy gran tamaño."}]',
  `gamme_de` = '[{"name":"Salomones","color":"#8B4513","force":"Medium-Full","story":"Salomón, 2003 zusammen mit Distinguido und Diadema ins reguläre Portfolio aufgenommen, sagt habanos.com. Wikipedia beschreibt ihn als doppeltes Perfecto von 184 mm bei Cepo 57 (Salomónes I).","vitolas":["Salomón"],"wrapper":"Vuelta Abajo"},{"name":"Divinos","color":"#A0522D","force":"Medium","story":"Eine der vier ursprünglichen Größen der Marke, neben Tradicionales, Generosos und Exclusivos, sagt habanos.com. Wikipedia beschreibt sie als kleines Perfecto von 102 mm bei Cepo 43, Petit Bouquet genannt.","vitolas":["Petit Bouquet"],"wrapper":"Vuelta Abajo"},{"name":"Distinguidos et Diademas","color":"#7A4A2B","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"Distinguido und Diadema ergänzen seit 2003 das reguläre Sortiment, sagt habanos.com. Wikipedia nennt 162 mm bei Cepo 52 für das Distinguido und 232 mm bei Cepo 55 für die Diadema, ein Perfecto von sehr großem Format."}]',
  `gamme_zh` = '[{"name":"Salomones","color":"#8B4513","force":"Medium-Full","story":"Salomón 于2003年与 Distinguido 和 Diadema 一同进入常规产品线，habanos.com 如是说。维基百科把它描述为184 mm、cepo 57 的双头 perfecto（Salomónes I）。","vitolas":["Salomón"],"wrapper":"Vuelta Abajo"},{"name":"Divinos","color":"#A0522D","force":"Medium","story":"该品牌四个原始尺寸之一，另三个为 Tradicionales、Generosos 和 Exclusivos，habanos.com 如是说。维基百科把它描述为102 mm、cepo 43 的小型 perfecto，名为 Petit Bouquet。","vitolas":["Petit Bouquet"],"wrapper":"Vuelta Abajo"},{"name":"Distinguidos et Diademas","color":"#7A4A2B","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"Distinguido 和 Diadema 自2003年起补全常规产品线，habanos.com 如是说。维基百科给出 Distinguido 为162 mm、cepo 52，Diadema 为232 mm、cepo 55，后者是体量很大的 perfecto。"}]',
  `gamme_ar` = '[{"name":"Salomones","color":"#8B4513","force":"Medium-Full","story":"انضمّ Salomón إلى المحفظة النظامية سنة 2003 مع Distinguido وDiadema، بحسب habanos.com. وتصفه ويكيبيديا بأنه بيرفيكتو مزدوج طوله 184 mm بقياس cepo 57 (Salomónes I).","vitolas":["Salomón"],"wrapper":"Vuelta Abajo"},{"name":"Divinos","color":"#A0522D","force":"Medium","story":"أحد المقاسات الأربعة الأصلية للعلامة، إلى جانب Tradicionales وGenerosos وExclusivos، بحسب habanos.com. وتصفه ويكيبيديا بأنه بيرفيكتو صغير طوله 102 mm بقياس cepo 43، يسمّى Petit Bouquet.","vitolas":["Petit Bouquet"],"wrapper":"Vuelta Abajo"},{"name":"Distinguidos et Diademas","color":"#7A4A2B","force":null,"wrapper":"Vuelta Abajo","vitolas":[],"story":"يكمّل Distinguido وDiadema التشكيلة النظامية منذ 2003، بحسب habanos.com. وتعطي ويكيبيديا 162 mm بقياس cepo 52 لـDistinguido و232 mm بقياس cepo 55 لـDiadema، وهو بيرفيكتو كبير الحجم جداً."}]',
  `celebrities` = '[{"name":"Les Taïnos","anecdote":"Cuaba est, dit la presse du métier, le nom taïno d''un buisson que les habitants de l''île employaient pour allumer leurs cigares ; habanos.com y voit un mot indien de l''époque de Christophe Colomb, un buisson très combustible utilisé lors de cérémonies religieuses. La marque de 1996 a repris le mot pour des doubles figurados."},{"name":"Carlos Izquierdo González","anecdote":"Wikipédia le donne pour le créateur de la marque, lancée le 19 novembre 1996 à Londres ; il aurait modelé le mélange sur celui de Montecristo, une affirmation que la même page rapporte sans la confirmer."}]',
  `celebrities_en` = '[{"name":"Les Taïnos","anecdote":"Cuaba is, says the trade press, the Taíno name of a bush that the island''s inhabitants used to light their cigars; habanos.com sees in it an Indian word from the time of Christopher Columbus, a highly combustible bush used in religious ceremonies. The 1996 brand took the word back for double figurados."},{"name":"Carlos Izquierdo González","anecdote":"Wikipedia names him as the creator of the brand, launched on 19 November 1996 in London; he is said to have modelled the blend on that of Montecristo, a claim the same page reports without confirming it."}]',
  `celebrities_es` = '[{"name":"Les Taïnos","anecdote":"Cuaba es, dice la prensa del oficio, el nombre taíno de un arbusto que los habitantes de la isla empleaban para encender sus puros; habanos.com ve en él una palabra india de la época de Cristóbal Colón, un arbusto muy combustible usado en ceremonias religiosas. La marca de 1996 recuperó la palabra para dobles figurados."},{"name":"Carlos Izquierdo González","anecdote":"Wikipedia lo da por creador de la marca, lanzada el 19 de noviembre de 1996 en Londres; habría modelado la mezcla sobre la de Montecristo, una afirmación que la misma página recoge sin confirmarla."}]',
  `celebrities_de` = '[{"name":"Les Taïnos","anecdote":"Cuaba ist, sagt die Fachpresse, der Taíno-Name eines Strauchs, den die Bewohner der Insel zum Anzünden ihrer Zigarren nutzten; habanos.com sieht darin ein indianisches Wort aus der Zeit von Christoph Kolumbus, einen leicht brennbaren Strauch, der bei religiösen Zeremonien verwendet wurde. Die Marke von 1996 griff das Wort für doppelte Figurados wieder auf."},{"name":"Carlos Izquierdo González","anecdote":"Wikipedia nennt ihn als Schöpfer der Marke, die am 19. November 1996 in London vorgestellt wurde; er soll die Mischung nach der von Montecristo gestaltet haben, eine Behauptung, die dieselbe Seite wiedergibt, ohne sie zu bestätigen."}]',
  `celebrities_zh` = '[{"name":"Les Taïnos","anecdote":"行业媒体称，Cuaba 是泰诺语中一种灌木的名字，岛上居民用它来点燃雪茄；habanos.com 则认为这是克里斯托弗·哥伦布时代的一个印第安词，指一种极易燃、用于宗教仪式的灌木。1996年的这个品牌取回了这个词，用于双头异形茄。"},{"name":"Carlos Izquierdo González","anecdote":"维基百科称他是该品牌的创建者，品牌于1996年11月19日在伦敦推出；据说他仿照 Montecristo 的配方调制了混合，同一页面转述了这一说法，但没有证实。"}]',
  `celebrities_ar` = '[{"name":"Les Taïnos","anecdote":"Cuaba، بحسب الصحافة المتخصّصة، اسم تاينوي لشجيرة كان سكان الجزيرة يستخدمونها لإشعال سيجارهم؛ أمّا habanos.com فترى فيه كلمة هندية من زمن كريستوفر كولومبوس، شجيرة شديدة الاشتعال استُخدمت في الاحتفالات الدينية. استعادت علامة 1996 الكلمة للفيغورادو المزدوج."},{"name":"Carlos Izquierdo González","anecdote":"تذكره ويكيبيديا بوصفه مبتكر العلامة التي أُطلقت في 19 نوفمبر 1996 في لندن؛ ويُقال إنه صاغ الخلطة على غرار خلطة Montecristo، وهو ادّعاء تنقله الصفحة نفسها دون أن تؤكّده."}]',
  `pairings` = '[{"type":"Spiritueux","name":"Rhum ambré 12 ans","notes":"Suggestion d''accord, sans page derrière, pour une marque que Habanos décrit de force moyenne à pleine."},{"type":"Café","name":"Expresso serré","notes":"Suggestion d''accord, sans page derrière, pour un double figurado de la marque."}]',
  `pairings_en` = '[{"type":"Spirits","name":"12-year-old amber rum","notes":"A pairing suggestion, with no page behind it, for a brand that Habanos describes as medium to full in strength."},{"type":"Coffee","name":"Tight espresso","notes":"A pairing suggestion, with no page behind it, for one of the brand''s double figurados."}]',
  `pairings_es` = '[{"type":"Destilados","name":"Ron ámbar de 12 años","notes":"Sugerencia de maridaje, sin página detrás, para una marca que Habanos describe de fuerza media a plena."},{"type":"Café","name":"Espresso corto","notes":"Sugerencia de maridaje, sin página detrás, para un doble figurado de la marca."}]',
  `pairings_de` = '[{"type":"Spirituosen","name":"Zwölfjähriger Amber-Rum","notes":"Kombinationsvorschlag ohne zugehörige Seite, für eine Marke, die Habanos als mittelkräftig bis kräftig beschreibt."},{"type":"Kaffee","name":"Kurzer Espresso","notes":"Kombinationsvorschlag ohne zugehörige Seite, für ein doppeltes Figurado der Marke."}]',
  `pairings_zh` = '[{"type":"烈酒","name":"12年琥珀朗姆","notes":"搭配建议，背后没有页面支撑，针对 Habanos 称力度中等至饱满的品牌。"},{"type":"咖啡","name":"短萃浓缩","notes":"搭配建议，背后没有页面支撑，针对该品牌的一款双头异形茄。"}]',
  `pairings_ar` = '[{"type":"مشروبات روحية","name":"روم كهرماني عمره 12 سنة","notes":"اقتراح مرافقة بلا صفحة خلفه، لعلامة تصفها Habanos بأنها ذات قوة متوسطة إلى تامّة."},{"type":"قهوة","name":"إسبريسو مركّز","notes":"اقتراح مرافقة بلا صفحة خلفه، لفيغورادو مزدوج من العلامة."}]',
  `source` = IF(LOCATE(CAST('cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de Cuaba) ; ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de Cuaba) ; ', ''), `source`),
  `source` = IF(LOCATE(CAST('habanos.com « Cuaba Brand » (https://www.habanos.com/en/the-' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'habanos.com « Cuaba Brand » (https://www.habanos.com/en/the-world-of-the-habano/the-habanos-brands-academia/cuaba-brand/, page sans date, lue le 16 octobre 2026 : style relancé en 1996 à la fabrique Romeo y Julieta, tailles d''origine, trois vitolas depuis 2003, force medium à full, Vuelta Abajo, aucune fabrique mère) ; habanos.com « The Habanos Brands Academia » (page sans date, lue le 16 octobre 2026 : 27 marques, Cuaba parmi les 13 autres) ; en.wikipedia.org « Cuaba (cigar) » (page sans date : lancement du 19 novembre 1996, Briones Montoto, dimensions des vitolas) ; cigaraficionado.com « Cuaba » (page de marque sans date : nom taïno, 1996 et 2003) ; cigaraficionado.com « The Temples of Cigars » (mai-juin 2015 : La Corona mère de Hoyo, Cuaba et Punch)')),
  `updated_at` = NOW()
 WHERE `name` = 'Cuaba';

-- ── El Rey del Mundo ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le nom claque comme une enseigne du XIXe siècle, et c''en est une : « le roi du monde », déposé en 1848 par Emilio Ohmstedt, à une époque où l''on ne reculait devant aucune emphase pour vendre du tabac. La marque fut longtemps l''une des plus chères de La Havane, réputée pour la sélection de ses feuilles plus que pour la puissance de ses assemblages.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le nom claque comme une enseigne du XIXe siècle, et c''en est une : « le roi du monde », déposé en 1848 par Emilio Ohmstedt, à une époque où l''on ne reculait devant aucune emphase pour vendre du tabac. La marque fut longtemps l''une des plus chères de La Havane, réputée pour la sélection de ses feuilles plus que pour la puissance de ses assemblages.', 'Le nom signifie le roi du monde. Wikipédia et Origin of Cigar écrivent que la marque aurait été créée en 1848 par l''Allemand Emilio Ohmstedt, en même temps que Sancho Panza ; Origin of Cigar rapporte aussi la version de ceux qui font d''Antonio Allones lui-même le fondateur en 1848. Habanos date de 1882 le lancement, sous Antonio Allones, qui faisait déjà des cigares à La Havane depuis plus de trente ans, d''une marque de qualité et de prix élevés dont le nom fut vite connu pour son prestige.'), `history`),
  `history_en` = IF(LOCATE(CAST('The name cracks like a nineteenth-century shop sign, and that is exactly what it is: "the king of the world", registered in 1848 by Emilio Ohmstedt, at a time when no emphasis was too great for selling tobacco. The brand was long one of the most expensive in Havana, esteemed for the selection of its leaves rather than for the power of its blends.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The name cracks like a nineteenth-century shop sign, and that is exactly what it is: "the king of the world", registered in 1848 by Emilio Ohmstedt, at a time when no emphasis was too great for selling tobacco. The brand was long one of the most expensive in Havana, esteemed for the selection of its leaves rather than for the power of its blends.', 'The name means the king of the world. Wikipedia and Origin of Cigar write that the brand is said to have been created in 1848 by the German Emilio Ohmstedt, at the same time as Sancho Panza; Origin of Cigar also reports the version of those who make Antonio Allones himself the founder in 1848. Habanos dates to 1882 the launch, under Antonio Allones, who had already been making cigars in Havana for more than thirty years, of a brand of high quality and high prices whose name was soon known for its prestige.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El nombre restalla como un rótulo del siglo XIX, y eso es exactamente lo que es: «el rey del mundo», registrado en 1848 por Emilio Ohmstedt, en una época en la que no se retrocedía ante ninguna énfasis para vender tabaco. La marca fue durante mucho tiempo una de las más caras de La Habana, reputada por la selección de sus hojas más que por la potencia de sus ligas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El nombre restalla como un rótulo del siglo XIX, y eso es exactamente lo que es: «el rey del mundo», registrado en 1848 por Emilio Ohmstedt, en una época en la que no se retrocedía ante ninguna énfasis para vender tabaco. La marca fue durante mucho tiempo una de las más caras de La Habana, reputada por la selección de sus hojas más que por la potencia de sus ligas.', 'El nombre significa el rey del mundo. Wikipedia y Origin of Cigar escriben que la marca habría sido creada en 1848 por el alemán Emilio Ohmstedt, al mismo tiempo que Sancho Panza; Origin of Cigar recoge también la versión de quienes hacen del propio Antonio Allones el fundador en 1848. Habanos fecha en 1882 el lanzamiento, bajo Antonio Allones, que ya hacía puros en La Habana desde hacía más de treinta años, de una marca de calidad y precios elevados cuyo nombre fue pronto conocido por su prestigio.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Name knallt wie ein Ladenschild des 19. Jahrhunderts, und genau das ist er: „der König der Welt“, 1848 von Emilio Ohmstedt eingetragen, zu einer Zeit, in der man vor keinem Pathos zurückschreckte, um Tabak zu verkaufen. Die Marke war lange eine der teuersten Havannas, geschätzt für die Auswahl ihrer Blätter mehr als für die Kraft ihrer Blends.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Name knallt wie ein Ladenschild des 19. Jahrhunderts, und genau das ist er: „der König der Welt“, 1848 von Emilio Ohmstedt eingetragen, zu einer Zeit, in der man vor keinem Pathos zurückschreckte, um Tabak zu verkaufen. Die Marke war lange eine der teuersten Havannas, geschätzt für die Auswahl ihrer Blätter mehr als für die Kraft ihrer Blends.', 'Der Name bedeutet der König der Welt. Wikipedia und Origin of Cigar schreiben, die Marke sei 1848 vom Deutschen Emilio Ohmstedt geschaffen worden, zeitgleich mit Sancho Panza; Origin of Cigar gibt auch die Version derer wieder, die Antonio Allones selbst zum Gründer im Jahr 1848 machen. Habanos datiert auf 1882 die Einführung, unter Antonio Allones, der schon seit mehr als dreißig Jahren in Havanna Zigarren herstellte, einer Marke von hoher Qualität und hohem Preis, deren Name rasch für sein Prestige bekannt wurde.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这名字像十九世纪的店招一样脆响，而它确实就是：「世界之王」，1848年由埃米利奥·奥姆施泰特注册，那个年代为卖烟草不惜任何夸张之辞。这个品牌长期是哈瓦那最昂贵者之一，其名声来自选叶，而非配方的力度。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这名字像十九世纪的店招一样脆响，而它确实就是：「世界之王」，1848年由埃米利奥·奥姆施泰特注册，那个年代为卖烟草不惜任何夸张之辞。这个品牌长期是哈瓦那最昂贵者之一，其名声来自选叶，而非配方的力度。', '这个名字的意思是世界之王。维基百科和 Origin of Cigar 写道，该品牌据称由德国人 Emilio Ohmstedt 于1848年创制，与 Sancho Panza 同时；Origin of Cigar 还转述了另一种说法，即把 Antonio Allones 本人视为1848年的创始人。Habanos 把1882年定为推出时间，当时由 Antonio Allones 主持，他在哈瓦那制作雪茄已超过三十年，推出的是一个品质与价格都高的品牌，其名号很快因声望而闻名。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('الاسم يطقطق كلافتة متجر من القرن التاسع عشر، وهو كذلك فعلاً: «ملك العالم»، سُجّل سنة 1848 على يد إميليو أومشتيت، في زمن لم يكن يُتورَّع فيه عن أي مبالغة لبيع التبغ. وكانت العلامة طويلاً من أغلى علامات هافانا، تُعرف بانتقاء أوراقها أكثر مما تُعرف بقوّة خلطاتها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'الاسم يطقطق كلافتة متجر من القرن التاسع عشر، وهو كذلك فعلاً: «ملك العالم»، سُجّل سنة 1848 على يد إميليو أومشتيت، في زمن لم يكن يُتورَّع فيه عن أي مبالغة لبيع التبغ. وكانت العلامة طويلاً من أغلى علامات هافانا، تُعرف بانتقاء أوراقها أكثر مما تُعرف بقوّة خلطاتها.', 'يعني الاسم ملك العالم. تكتب ويكيبيديا وOrigin of Cigar أنّ العلامة يُقال إنها أُنشئت سنة 1848 على يد الألماني Emilio Ohmstedt، في الوقت نفسه مع Sancho Panza؛ وتنقل Origin of Cigar أيضاً رواية من يجعلون Antonio Allones نفسه المؤسّس سنة 1848. وتؤرّخ Habanos لإطلاق العلامة بسنة 1882، في عهد Antonio Allones الذي كان يصنع السيجار في هافانا منذ ما يزيد على ثلاثين سنة، وهي علامة رفيعة الجودة والسعر ذاع اسمها سريعاً بما لها من مكانة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'El Rey del Mundo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('C''est précisément ce qui la rend intéressante aujourd''hui. El Rey del Mundo appartient au registre doux à médium du portefeuille cubain — celui que la mode des années 2000, tournée vers les assemblages de plus en plus forts, a laissé de côté. La marque n''a pas suivi ; elle a gardé un profil de bois blond, de foin sec et d''amande, avec une longueur en bouche qui doit tout à la qualité de la matière et rien à l''intensité.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'C''est précisément ce qui la rend intéressante aujourd''hui. El Rey del Mundo appartient au registre doux à médium du portefeuille cubain — celui que la mode des années 2000, tournée vers les assemblages de plus en plus forts, a laissé de côté. La marque n''a pas suivi ; elle a gardé un profil de bois blond, de foin sec et d''amande, avec une longueur en bouche qui doit tout à la qualité de la matière et rien à l''intensité.', 'Habanos la dit de saveur légère à moyenne, en feuilles de la Vuelta Abajo, roulée à la main en tripe longue. Habanos écrit aussi que la marque a souvent servi pour des éditions régionales. Wikipédia écrit qu''elle resta populaire pendant les années 1960 et 1970.'), `history`),
  `history_en` = IF(LOCATE(CAST('That is precisely what makes it interesting today. El Rey del Mundo belongs to the mild-to-medium register of the Cuban portfolio — the one the fashion of the 2000s, turned towards ever stronger blends, left aside. The brand did not follow; it kept a profile of pale wood, dry hay and almond, with a length on the palate that owes everything to the quality of the material and nothing to intensity.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'That is precisely what makes it interesting today. El Rey del Mundo belongs to the mild-to-medium register of the Cuban portfolio — the one the fashion of the 2000s, turned towards ever stronger blends, left aside. The brand did not follow; it kept a profile of pale wood, dry hay and almond, with a length on the palate that owes everything to the quality of the material and nothing to intensity.', 'Habanos describes it as light to medium in flavour, in leaves from the Vuelta Abajo, hand-rolled with long filler. Habanos also writes that the brand has often been used for regional editions. Wikipedia writes that it remained popular during the 1960s and 1970s.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Es precisamente eso lo que la hace interesante hoy. El Rey del Mundo pertenece al registro suave a medio del portafolio cubano — aquel que la moda de los años dos mil, volcada en ligas cada vez más fuertes, dejó de lado. La marca no siguió; conservó un perfil de madera clara, heno seco y almendra, con una longitud en boca que se lo debe todo a la calidad de la materia y nada a la intensidad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Es precisamente eso lo que la hace interesante hoy. El Rey del Mundo pertenece al registro suave a medio del portafolio cubano — aquel que la moda de los años dos mil, volcada en ligas cada vez más fuertes, dejó de lado. La marca no siguió; conservó un perfil de madera clara, heno seco y almendra, con una longitud en boca que se lo debe todo a la calidad de la materia y nada a la intensidad.', 'Habanos la dice de sabor ligero a medio, en hojas de la Vuelta Abajo, liada a mano con tripa larga. Habanos escribe también que la marca ha servido a menudo para ediciones regionales. Wikipedia escribe que siguió siendo popular durante los años sesenta y setenta.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Genau das macht sie heute interessant. El Rey del Mundo gehört zum milden bis mittleren Register des kubanischen Sortiments — jenem, das die Mode der 2000er Jahre mit ihren immer kräftigeren Blends links liegen ließ. Die Marke folgte nicht; sie behielt ein Profil aus hellem Holz, trockenem Heu und Mandel, mit einer Länge am Gaumen, die alles der Qualität des Materials und nichts der Intensität verdankt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Genau das macht sie heute interessant. El Rey del Mundo gehört zum milden bis mittleren Register des kubanischen Sortiments — jenem, das die Mode der 2000er Jahre mit ihren immer kräftigeren Blends links liegen ließ. Die Marke folgte nicht; sie behielt ein Profil aus hellem Holz, trockenem Heu und Mandel, mit einer Länge am Gaumen, die alles der Qualität des Materials und nichts der Intensität verdankt.', 'Habanos bezeichnet sie als von leichtem bis mittlerem Geschmack, aus Blättern der Vuelta Abajo, von Hand mit Longfiller gerollt. Habanos schreibt außerdem, die Marke habe oft für regionale Editionen gedient. Wikipedia schreibt, sie sei in den 1960er und 1970er Jahren beliebt geblieben.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('而这恰恰是它今天有意思的地方。世界之王属于古巴产品序列中偏柔至中度的路数——正是2000年代那股愈发追求浓烈的风潮所忽略的一路。这个品牌没有跟随；它保住了浅色木质、干草与杏仁的风格，口中的绵长全然来自原料的品质，与强度无关。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '而这恰恰是它今天有意思的地方。世界之王属于古巴产品序列中偏柔至中度的路数——正是2000年代那股愈发追求浓烈的风潮所忽略的一路。这个品牌没有跟随；它保住了浅色木质、干草与杏仁的风格，口中的绵长全然来自原料的品质，与强度无关。', 'Habanos 称其风味轻至中等，采用 Vuelta Abajo 的叶片，手工长茄芯卷制。Habanos 还写道，该品牌常用于地区限量版。维基百科写道，它在1960年代和1970年代依然广受欢迎。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وهذا تحديداً ما يجعلها مثيرة للاهتمام اليوم. تنتمي «إل ري ديل موندو» إلى المستوى اللطيف-المتوسط في المحفظة الكوبية — ذاك الذي تركته جانباً موضةُ الألفية المتّجهة إلى خلطات أقوى فأقوى. لم تسايرها العلامة؛ بل احتفظت بطابع من خشب فاتح وقشّ جافّ ولوز، بطول في الفم يدين بكل شيء لجودة المادة ولا شيء للشدّة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وهذا تحديداً ما يجعلها مثيرة للاهتمام اليوم. تنتمي «إل ري ديل موندو» إلى المستوى اللطيف-المتوسط في المحفظة الكوبية — ذاك الذي تركته جانباً موضةُ الألفية المتّجهة إلى خلطات أقوى فأقوى. لم تسايرها العلامة؛ بل احتفظت بطابع من خشب فاتح وقشّ جافّ ولوز، بطول في الفم يدين بكل شيء لجودة المادة ولا شيء للشدّة.', 'تصفها Habanos بأنها خفيفة إلى متوسطة النكهة، من أوراق Vuelta Abajo، ملفوفة يدوياً بحشوة طويلة. وتكتب Habanos أيضاً أنّ العلامة استُخدمت كثيراً في إصدارات إقليمية. وتكتب ويكيبيديا أنها ظلّت رائجة في ستينيات القرن العشرين وسبعينياته.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'El Rey del Mundo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme s''est réduite au fil des décennies, comme celle de plusieurs marques historiques que Habanos a resserrées. Le Choix Suprême, un Hermoso No.4, en reste l''expression la plus connue : un format court, régulier, qui se fume en une heure et ne demande pas d''estomac plein.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme s''est réduite au fil des décennies, comme celle de plusieurs marques historiques que Habanos a resserrées. Le Choix Suprême, un Hermoso No.4, en reste l''expression la plus connue : un format court, régulier, qui se fume en une heure et ne demande pas d''estomac plein.', 'Origin of Cigar écrit, en décembre 2025, que la gamme standard ne compte que le Choix Suprême et le Demi Tasse. Le Choix Suprême est un Hermoso No.4, 127 mm pour un cepo 48, et le Demi Tasse une Entreacto, 98 mm pour un cepo 30, selon la reprise de Wikipédia par Alchetron.'), `history`),
  `history_en` = IF(LOCATE(CAST('The range has shrunk over the decades, like that of several historic brands Habanos has tightened. The Choix Suprême, an Hermoso No.4, remains its best-known expression: a short, even format, smoked in an hour, that does not require a full stomach.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The range has shrunk over the decades, like that of several historic brands Habanos has tightened. The Choix Suprême, an Hermoso No.4, remains its best-known expression: a short, even format, smoked in an hour, that does not require a full stomach.', 'Origin of Cigar writes, in December 2025, that the standard range includes only the Choix Suprême and the Demi Tasse. The Choix Suprême is an Hermoso No.4, 127 mm with a cepo of 48, and the Demi Tasse an Entreacto, 98 mm with a cepo of 30, according to Alchetron''s reuse of Wikipedia.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama se ha reducido con las décadas, como la de varias marcas históricas que Habanos ha estrechado. El Choix Suprême, un Hermoso No.4, sigue siendo su expresión más conocida: un formato corto y regular, que se fuma en una hora y no exige el estómago lleno.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama se ha reducido con las décadas, como la de varias marcas históricas que Habanos ha estrechado. El Choix Suprême, un Hermoso No.4, sigue siendo su expresión más conocida: un formato corto y regular, que se fuma en una hora y no exige el estómago lleno.', 'Origin of Cigar escribe, en diciembre de 2025, que la gama estándar solo cuenta con el Choix Suprême y el Demi Tasse. El Choix Suprême es un Hermoso No.4, 127 mm para un cepo 48, y el Demi Tasse un Entreacto, 98 mm para un cepo 30, según la reutilización de Wikipedia por Alchetron.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Sortiment ist über die Jahrzehnte geschrumpft, wie das mehrerer historischer Marken, die Habanos gestrafft hat. Die Choix Suprême, eine Hermoso No.4, bleibt ihr bekanntester Ausdruck: ein kurzes, gleichmäßiges Format, in einer Stunde geraucht, das keinen vollen Magen verlangt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Sortiment ist über die Jahrzehnte geschrumpft, wie das mehrerer historischer Marken, die Habanos gestrafft hat. Die Choix Suprême, eine Hermoso No.4, bleibt ihr bekanntester Ausdruck: ein kurzes, gleichmäßiges Format, in einer Stunde geraucht, das keinen vollen Magen verlangt.', 'Origin of Cigar schreibt im Dezember 2025, das Standardsortiment umfasse nur die Choix Suprême und den Demi Tasse. Die Choix Suprême ist ein Hermoso No.4, 127 mm bei Cepo 48, und der Demi Tasse ein Entreacto, 98 mm bei Cepo 30, nach der Übernahme von Wikipedia durch Alchetron.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('几十年来其产品线不断收缩，正如哈瓦那雪茄公司精简过的几个历史品牌。Choix Suprême（一款 Hermoso No.4）仍是它最知名的表达：短小而均匀，一小时抽完，不需要先吃饱。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '几十年来其产品线不断收缩，正如哈瓦那雪茄公司精简过的几个历史品牌。Choix Suprême（一款 Hermoso No.4）仍是它最知名的表达：短小而均匀，一小时抽完，不需要先吃饱。', 'Origin of Cigar 于2025年12月写道，标准产品线只有 Choix Suprême 和 Demi Tasse。据 Alchetron 转载的维基百科，Choix Suprême 是 Hermoso No.4，127 mm、cepo 48；Demi Tasse 是 Entreacto，98 mm、cepo 30。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تقلّصت التشكيلة عبر العقود، كما تقلّصت تشكيلات علامات تاريخية عدّة ضغطتها «هابانوس». ويبقى «شوا سوبريم»، وهو «إيرموسو رقم 4»، تعبيرها الأشهر: مقاس قصير منتظم، يُدخَّن في ساعة ولا يستدعي معدة ممتلئة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تقلّصت التشكيلة عبر العقود، كما تقلّصت تشكيلات علامات تاريخية عدّة ضغطتها «هابانوس». ويبقى «شوا سوبريم»، وهو «إيرموسو رقم 4»، تعبيرها الأشهر: مقاس قصير منتظم، يُدخَّن في ساعة ولا يستدعي معدة ممتلئة.', 'تكتب Origin of Cigar، في ديسمبر 2025، أنّ التشكيلة القياسية لا تضمّ سوى Choix Suprême وDemi Tasse. وChoix Suprême هو Hermoso No.4 طوله 127 mm بقياس cepo 48، وDemi Tasse هو Entreacto طوله 98 mm بقياس cepo 30، بحسب نقل Alchetron عن ويكيبيديا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'El Rey del Mundo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Une marque de connaisseurs, donc — au sens le moins snob du terme : celle qu''on redécouvre quand on se lasse de chercher la force.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Une marque de connaisseurs, donc — au sens le moins snob du terme : celle qu''on redécouvre quand on se lasse de chercher la force.', 'Il existe un autre El Rey del Mundo, hondurien, fait par la famille Villazon, dit Wikipédia : c''est un autre cigare, et la présente fiche ne concerne que la marque cubaine de Habanos S.A.'), `history`),
  `history_en` = IF(LOCATE(CAST('A connoisseur''s brand, then — in the least snobbish sense of the word: the one you rediscover when you tire of looking for strength.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'A connoisseur''s brand, then — in the least snobbish sense of the word: the one you rediscover when you tire of looking for strength.', 'There is another El Rey del Mundo, Honduran, made by the Villazon family, says Wikipedia: it is a different cigar, and this entry concerns only the Cuban brand of Habanos S.A.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Una marca de conocedores, pues — en el sentido menos snob del término: la que se redescubre cuando uno se cansa de buscar la fuerza.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Una marca de conocedores, pues — en el sentido menos snob del término: la que se redescubre cuando uno se cansa de buscar la fuerza.', 'Existe otro El Rey del Mundo, hondureño, hecho por la familia Villazon, dice Wikipedia: es otro puro, y esta ficha solo concierne a la marca cubana de Habanos S.A.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Eine Kennermarke also — im unsnobistischsten Sinne des Wortes: jene, die man wiederentdeckt, wenn man es müde ist, nach Kraft zu suchen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Eine Kennermarke also — im unsnobistischsten Sinne des Wortes: jene, die man wiederentdeckt, wenn man es müde ist, nach Kraft zu suchen.', 'Es gibt einen anderen El Rey del Mundo, honduranisch, von der Familie Villazon hergestellt, sagt Wikipedia: Das ist eine andere Zigarre, und dieser Eintrag betrifft nur die kubanische Marke von Habanos S.A.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('所以这是一个行家的品牌——在最不势利的意义上：当你厌倦了追逐力度时，会重新发现的那一个。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '所以这是一个行家的品牌——在最不势利的意义上：当你厌倦了追逐力度时，会重新发现的那一个。', '另有一款洪都拉斯的 El Rey del Mundo，由 Villazon 家族制作，维基百科如是说：那是另一种雪茄，本词条只涉及 Habanos S.A. 的古巴品牌。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('علامة خبراء إذاً — بأقلّ معاني الكلمة تعالياً: تلك التي تعيد اكتشافها حين تملّ البحث عن القوّة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'علامة خبراء إذاً — بأقلّ معاني الكلمة تعالياً: تلك التي تعيد اكتشافها حين تملّ البحث عن القوّة.', 'ثمّة El Rey del Mundo آخر هندوراسي، من صنع عائلة Villazon، بحسب ويكيبيديا: إنه سيجار آخر، وهذه البطاقة لا تخصّ إلا العلامة الكوبية التابعة لـHabanos S.A.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'El Rey del Mundo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Romeo y Julieta : le bâtiment historique de Belascoaín a été cédé à H. Upmann en 2011, et c''est l''ancienne fabrique Carlos Baliño — celle qui portait le nom d''El Rey del Mundo —, rebaptisée, qui tient ce rôle depuis la fin des années 2010, selon la presse spécialisée. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. Deux dates pour une marque : 1848 et Emilio Ohmstedt selon l''usage et Wikipédia, 1882 et Antonio Allones selon la page officielle, qui fait de cette année-là le lancement de la marque haut de gamme ; la fiche écrit les deux. La fabrique qui portait son nom a cédé son bâtiment à Partagás en 2010 et son nom à Romeo y Julieta ; la marque suit cette dernière.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Romeo y Julieta : le bâtiment historique de Belascoaín a été cédé à H. Upmann en 2011, et c''est l''ancienne fabrique Carlos Baliño — celle qui portait le nom d''El Rey del Mundo —, rebaptisée, qui tient ce rôle depuis la fin des années 2010, selon la presse spécialisée. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. Deux dates pour une marque : 1848 et Emilio Ohmstedt selon l''usage et Wikipédia, 1882 et Antonio Allones selon la page officielle, qui fait de cette année-là le lancement de la marque haut de gamme ; la fiche écrit les deux. La fabrique qui portait son nom a cédé son bâtiment à Partagás en 2010 et son nom à Romeo y Julieta ; la marque suit cette dernière.', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme aucune fabrique pour El Rey del Mundo. La presse du métier (avril 2014) dit que le 852 Belascoaín, connu aussi comme la fabrique Briones Montoto, est le bâtiment qu''un annuaire de 1940 donne à l''El Rey del Mundo Cigar Company et où la marque Romeo y Julieta fut logée jusqu''en 2000 ; la presse du métier écrit en 2011 que la fabrique Romeo y Julieta de Belascoaín 852 tourne alors sous le nom de H. Upmann, et que la production de Partagás doit être transférée à la fabrique El Rey del Mundo, fermée en mai pour rénovation ; Origin of Cigar place Romeo y Julieta depuis 2015 à la fabrique Carlos Baliño, à Marianao, ancien site de José L. Piedra. Ces pages divergent sur la fabrique actuelle de la marque, et aucune ne dit que Carlos Baliño porta le nom d''El Rey del Mundo. En octobre 2026, la page The Habanos Brands Academia de habanos.com range El Rey del Mundo parmi les treize autres marques d''un portefeuille de 27, hors des six marques globales, des cinq marques de valeur et des trois marques de volume. Deux dates pour une marque : 1848 et Emilio Ohmstedt selon Wikipédia et Origin of Cigar, 1882 et Antonio Allones selon habanos.com, qui en fait le lancement de la marque de prix élevé ; Origin of Cigar ajoute que la marque figure à l''annuaire de La Havane en 1873 et qu''Allones l''aurait réenregistrée en 1882 selon certaines sources. La presse du métier écrit en 2011 que la production de Partagás doit rejoindre la fabrique El Rey del Mundo, alors fermée pour rénovation.'), `history`),
  `history_en` = IF(LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Romeo y Julieta: the historic Belascoaín building was ceded to H. Upmann in 2011, and it is the former Carlos Baliño factory — the one that bore the El Rey del Mundo name —, renamed, that has held the role since the late 2010s, according to the specialist press. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. Two dates for one brand: 1848 and Emilio Ohmstedt by usage and Wikipedia, 1882 and Antonio Allones by the official page, which makes that year the launch of the premium brand; the entry writes both. The factory that bore its name ceded its building to Partagás in 2010 and its name to Romeo y Julieta; the brand follows the latter.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Romeo y Julieta: the historic Belascoaín building was ceded to H. Upmann in 2011, and it is the former Carlos Baliño factory — the one that bore the El Rey del Mundo name —, renamed, that has held the role since the late 2010s, according to the specialist press. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. Two dates for one brand: 1848 and Emilio Ohmstedt by usage and Wikipedia, 1882 and Antonio Allones by the official page, which makes that year the launch of the premium brand; the entry writes both. The factory that bore its name ceded its building to Partagás in 2010 and its name to Romeo y Julieta; the brand follows the latter.', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos does not name any factory for El Rey del Mundo. The trade press (April 2014) says that 852 Belascoaín, also known as the Briones Montoto factory, is the building that a 1940 directory gives to the El Rey del Mundo Cigar Company and where the Romeo y Julieta brand was housed until 2000; the trade press writes in 2011 that the Romeo y Julieta factory at Belascoaín 852 is then running under the name H. Upmann, and that Partagás production is to be transferred to the El Rey del Mundo factory, closed in May for renovation; Origin of Cigar places Romeo y Julieta since 2015 at the Carlos Baliño factory, in Marianao, the former site of José L. Piedra. These pages diverge on the brand''s current factory, and none says that Carlos Baliño bore the name El Rey del Mundo. In October 2026, the page The Habanos Brands Academia on habanos.com places El Rey del Mundo among the thirteen other brands of a portfolio of 27, outside the six global brands, the five value brands and the three volume brands. Two dates for one brand: 1848 and Emilio Ohmstedt according to Wikipedia and Origin of Cigar, 1882 and Antonio Allones according to habanos.com, which makes it the launch of the high-priced brand; Origin of Cigar adds that the brand appears in the Havana directory in 1873 and that Allones is said to have re-registered it in 1882 according to some sources. The trade press writes in 2011 that Partagás production is to join the El Rey del Mundo factory, then closed for renovation.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Romeo y Julieta: el edificio histórico de Belascoaín se cedió a H. Upmann en 2011, y es la antigua fábrica Carlos Baliño — la que llevaba el nombre de El Rey del Mundo —, rebautizada, la que cumple ese papel desde finales de los años 2010, según la prensa especializada. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. Dos fechas para una marca: 1848 y Emilio Ohmstedt según el uso y Wikipedia, 1882 y Antonio Allones según la página oficial, que hace de ese año el lanzamiento de la marca de alta gama; la ficha escribe las dos. La fábrica que llevaba su nombre cedió su edificio a Partagás en 2010 y su nombre a Romeo y Julieta; la marca sigue a esta última.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Romeo y Julieta: el edificio histórico de Belascoaín se cedió a H. Upmann en 2011, y es la antigua fábrica Carlos Baliño — la que llevaba el nombre de El Rey del Mundo —, rebautizada, la que cumple ese papel desde finales de los años 2010, según la prensa especializada. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. Dos fechas para una marca: 1848 y Emilio Ohmstedt según el uso y Wikipedia, 1882 y Antonio Allones según la página oficial, que hace de ese año el lanzamiento de la marca de alta gama; la ficha escribe las dos. La fábrica que llevaba su nombre cedió su edificio a Partagás en 2010 y su nombre a Romeo y Julieta; la marca sigue a esta última.', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra ninguna fábrica para El Rey del Mundo. La prensa del sector (abril de 2014) dice que el 852 de Belascoaín, conocido también como la fábrica Briones Montoto, es el edificio que un anuario de 1940 asigna a El Rey del Mundo Cigar Company y donde la marca Romeo y Julieta estuvo alojada hasta 2000; la prensa del sector escribe en 2011 que la fábrica Romeo y Julieta de Belascoaín 852 funciona entonces con el nombre de H. Upmann, y que la producción de Partagás debe trasladarse a la fábrica El Rey del Mundo, cerrada en mayo por renovación; Origin of Cigar sitúa Romeo y Julieta desde 2015 en la fábrica Carlos Baliño, en Marianao, antiguo emplazamiento de José L. Piedra. Estas páginas divergen sobre la fábrica actual de la marca, y ninguna dice que Carlos Baliño llevara el nombre de El Rey del Mundo. En octubre de 2026, la página Habanos Brands Academia de habanos.com clasifica El Rey del Mundo entre las otras trece marcas de un portafolio de 27, fuera de las seis marcas globales, de las cinco marcas de valor y de las tres marcas de volumen. Dos fechas para una marca: 1848 y Emilio Ohmstedt según Wikipedia y Origin of Cigar, 1882 y Antonio Allones según habanos.com, que hace de ello el lanzamiento de la marca de precio elevado; Origin of Cigar añade que la marca figura en el anuario de La Habana en 1873 y que Allones la habría vuelto a registrar en 1882 según algunas fuentes. La prensa del sector escribe en 2011 que la producción de Partagás debe unirse a la fábrica El Rey del Mundo, entonces cerrada por renovación.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Romeo y Julieta: Das historische Gebäude an der Belascoaín wurde 2011 an H. Upmann abgetreten, und die frühere Fabrik Carlos Baliño — die den Namen El Rey del Mundo trug —, umbenannt, hat diese Rolle seit Ende der 2010er Jahre inne, laut Fachpresse. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Zwei Daten für eine Marke: 1848 und Emilio Ohmstedt nach Gebrauch und Wikipedia, 1882 und Antonio Allones nach der offiziellen Seite, die jenes Jahr zum Start der Premiummarke macht; der Eintrag schreibt beide. Die Fabrik, die ihren Namen trug, trat ihr Gebäude 2010 an Partagás ab und ihren Namen an Romeo y Julieta; die Marke folgt Letzterer.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Romeo y Julieta: Das historische Gebäude an der Belascoaín wurde 2011 an H. Upmann abgetreten, und die frühere Fabrik Carlos Baliño — die den Namen El Rey del Mundo trug —, umbenannt, hat diese Rolle seit Ende der 2010er Jahre inne, laut Fachpresse. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Zwei Daten für eine Marke: 1848 und Emilio Ohmstedt nach Gebrauch und Wikipedia, 1882 und Antonio Allones nach der offiziellen Seite, die jenes Jahr zum Start der Premiummarke macht; der Eintrag schreibt beide. Die Fabrik, die ihren Namen trug, trat ihr Gebäude 2010 an Partagás ab und ihren Namen an Romeo y Julieta; die Marke folgt Letzterer.', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt für El Rey del Mundo keine Fabrik. Die Fachpresse (April 2014) sagt, die Belascoaín 852, auch als Fabrik Briones Montoto bekannt, sei das Gebäude, das ein Adressbuch von 1940 der El Rey del Mundo Cigar Company zuweist und in dem die Marke Romeo y Julieta bis 2000 untergebracht war; die Fachpresse schreibt 2011, die Fabrik Romeo y Julieta in der Belascoaín 852 laufe dann unter dem Namen H. Upmann, und die Produktion von Partagás solle in die Fabrik El Rey del Mundo verlegt werden, die im Mai zur Renovierung geschlossen worden sei; Origin of Cigar verortet Romeo y Julieta seit 2015 in der Fabrik Carlos Baliño in Marianao, dem früheren Standort von José L. Piedra. Diese Seiten gehen über die heutige Fabrik der Marke auseinander, und keine sagt, dass Carlos Baliño den Namen El Rey del Mundo trug. Im Oktober 2026 reiht die Seite Habanos Brands Academia von habanos.com El Rey del Mundo unter die dreizehn übrigen Marken eines Portfolios von 27 ein, außerhalb der sechs globalen Marken, der fünf Wertmarken und der drei Volumenmarken. Zwei Daten für eine Marke: 1848 und Emilio Ohmstedt nach Wikipedia und Origin of Cigar, 1882 und Antonio Allones nach habanos.com, das darin den Start der hochpreisigen Marke sieht; Origin of Cigar fügt hinzu, die Marke stehe 1873 im Adressbuch von Havanna, und Allones habe sie nach manchen Quellen 1882 neu eintragen lassen. Die Fachpresse schreibt 2011, die Produktion von Partagás solle zur Fabrik El Rey del Mundo stoßen, die damals zur Renovierung geschlossen war.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是罗密欧与朱丽叶：贝拉斯科艾因街的历史厂房2011年让给了乌普曼，据专业媒体，自2010年代末起由原 Carlos Baliño 厂——曾以 El Rey del Mundo 为名——更名后担任这一角色。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 一个品牌两个日期：按惯例和维基百科是1848年、埃米利奥·奥姆施泰特；按官方页面是1882年、安东尼奥·阿约内斯，页面把那一年当作高端品牌的推出；词条两者都写。曾以它为名的工厂2010年把厂房让给帕塔加斯、把名字让给罗密欧与朱丽叶；品牌跟随后者。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是罗密欧与朱丽叶：贝拉斯科艾因街的历史厂房2011年让给了乌普曼，据专业媒体，自2010年代末起由原 Carlos Baliño 厂——曾以 El Rey del Mundo 为名——更名后担任这一角色。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 一个品牌两个日期：按惯例和维基百科是1848年、埃米利奥·奥姆施泰特；按官方页面是1882年、安东尼奥·阿约内斯，页面把那一年当作高端品牌的推出；词条两者都写。曾以它为名的工厂2010年把厂房让给帕塔加斯、把名字让给罗密欧与朱丽叶；品牌跟随后者。', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有为 El Rey del Mundo 点名任何工厂。行业媒体（2014年4月）称，Belascoaín 852，又称 Briones Montoto 工厂，是1940年的一本名录划给 El Rey del Mundo Cigar Company 的建筑，Romeo y Julieta 品牌曾设在那里直到2000年；行业媒体于2011年写道，Belascoaín 852 的 Romeo y Julieta 工厂当时以 H. Upmann 之名运转，Partagás 的生产将转到 El Rey del Mundo 工厂，该厂于5月因翻修关闭；Origin of Cigar 把 Romeo y Julieta 自2015年起定在 Marianao 的 Carlos Baliño 工厂，即 José L. Piedra 的旧址。这些页面对该品牌现在的工厂说法不一，且没有一页说 Carlos Baliño 曾用 El Rey del Mundo 之名。2026年10月，habanos.com 的 Habanos Brands Academia 页面把 El Rey del Mundo 列入一个27个品牌的组合中的另外十三个品牌，不在六个全球品牌、五个价值品牌和三个销量品牌之内。一个品牌两个日期：维基百科和 Origin of Cigar 为1848年、Emilio Ohmstedt，habanos.com 为1882年、Antonio Allones，并把它当作高价品牌的推出；Origin of Cigar 补充说，该品牌1873年已见于哈瓦那名录，Allones 据某些来源于1882年重新注册了它。行业媒体于2011年写道，Partagás 的生产将并入 El Rey del Mundo 工厂，该厂当时因翻修关闭。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Romeo y Julieta: تنازل المبنى التاريخي في بيلاسكوين لـH. Upmann سنة 2011، ومصنع كارلوس بالينيو السابق — الذي كان يحمل اسم El Rey del Mundo — هو الذي يؤدّي هذا الدور بعد إعادة تسميته منذ أواخر عقد 2010، بحسب الصحافة المتخصّصة. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تاريخان لعلامة واحدة: 1848 وإميليو أومشتيت بحسب العرف وويكيبيديا، و1882 وأنطونيو أيونيس بحسب الصفحة الرسمية التي تجعل من تلك السنة إطلاق العلامة الراقية؛ تكتب البطاقة الاثنين. والمصنع الذي كان يحمل اسمها تنازل عن مبناه لـPartagás سنة 2010 وعن اسمه لـRomeo y Julieta؛ وتتبع العلامة هذه الأخيرة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Romeo y Julieta: تنازل المبنى التاريخي في بيلاسكوين لـH. Upmann سنة 2011، ومصنع كارلوس بالينيو السابق — الذي كان يحمل اسم El Rey del Mundo — هو الذي يؤدّي هذا الدور بعد إعادة تسميته منذ أواخر عقد 2010، بحسب الصحافة المتخصّصة. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تاريخان لعلامة واحدة: 1848 وإميليو أومشتيت بحسب العرف وويكيبيديا، و1882 وأنطونيو أيونيس بحسب الصفحة الرسمية التي تجعل من تلك السنة إطلاق العلامة الراقية؛ تكتب البطاقة الاثنين. والمصنع الذي كان يحمل اسمها تنازل عن مبناه لـPartagás سنة 2010 وعن اسمه لـRomeo y Julieta؛ وتتبع العلامة هذه الأخيرة.', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي Habanos أي مصنع لـEl Rey del Mundo. وتقول الصحافة المتخصّصة (أبريل 2014) إنّ Belascoaín 852، المعروف أيضاً بمصنع Briones Montoto، هو المبنى الذي يعزوه دليل سنة 1940 إلى El Rey del Mundo Cigar Company والذي أُسكنت فيه علامة Romeo y Julieta حتى سنة 2000؛ وتكتب الصحافة المتخصّصة سنة 2011 أنّ مصنع Romeo y Julieta في Belascoaín 852 يعمل حينئذ باسم H. Upmann، وأنّ إنتاج Partagás سيُنقل إلى مصنع El Rey del Mundo المغلق في مايو للتجديد؛ وتضع Origin of Cigar مصنع Romeo y Julieta منذ 2015 في مصنع Carlos Baliño في Marianao، الموقع السابق لـJosé L. Piedra. وتتباين هذه الصفحات في شأن المصنع الحالي للعلامة، ولا تقول أيّ منها إنّ Carlos Baliño حمل اسم El Rey del Mundo. وفي أكتوبر 2026 تصنّف صفحة Habanos Brands Academia في habanos.com علامة El Rey del Mundo ضمن العلامات الثلاث عشرة الأخرى في محفظة من 27 علامة، خارج العلامات العالمية الستّ وعلامات القيمة الخمس وعلامات الحجم الثلاث. تاريخان لعلامة واحدة: 1848 وEmilio Ohmstedt بحسب ويكيبيديا وOrigin of Cigar، و1882 وAntonio Allones بحسب habanos.com التي تجعل منه إطلاق العلامة مرتفعة السعر؛ وتضيف Origin of Cigar أنّ العلامة واردة في دليل هافانا سنة 1873 وأنّ Allones، بحسب بعض المصادر، أعاد تسجيلها سنة 1882. وتكتب الصحافة المتخصّصة سنة 2011 أنّ إنتاج Partagás سيلتحق بمصنع El Rey del Mundo، المغلق حينئذ للتجديد.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'El Rey del Mundo';

UPDATE `brands` SET
  `factory` = 'Non nommée par habanos.com. Presse : Romeo y Julieta (Belascoaín 852), puis Carlos Baliño (Marianao, Origin of Cigar) ; versions divergentes',
  `gamme` = '[{"name":"Choix Suprême","color":"#C9A227","force":"Medium","story":"Hermoso No.4, 127 mm pour un cepo 48 selon la reprise de Wikipédia par Alchetron ; avec le Demi Tasse, il forme la gamme standard, écrit Origin of Cigar en décembre 2025. Habanos décrit la marque de saveur légère à moyenne.","vitolas":["Hermoso No.4"],"wrapper":"Vuelta Abajo"},{"name":"Demi Tasse","color":"#D4B44A","force":"Light","story":"Entreacto, petit panetela de 98 mm pour un cepo 30 selon la reprise de Wikipédia par Alchetron ; l''une des deux lignes de la gamme standard, écrit Origin of Cigar en décembre 2025.","vitolas":["Entreactos"],"wrapper":"Vuelta Abajo"}]',
  `gamme_en` = '[{"name":"Choix Suprême","color":"#C9A227","force":"Medium","story":"Hermoso No.4, 127 mm with a cepo of 48 according to Alchetron''s reuse of Wikipedia; together with the Demi Tasse it forms the standard range, writes Origin of Cigar in December 2025. Habanos describes the brand as light to medium in flavour.","vitolas":["Hermoso No.4"],"wrapper":"Vuelta Abajo"},{"name":"Demi Tasse","color":"#D4B44A","force":"Light","story":"Entreacto, a small panetela of 98 mm with a cepo of 30 according to Alchetron''s reuse of Wikipedia; one of the two lines of the standard range, writes Origin of Cigar in December 2025.","vitolas":["Entreactos"],"wrapper":"Vuelta Abajo"}]',
  `gamme_es` = '[{"name":"Choix Suprême","color":"#C9A227","force":"Medium","story":"Hermoso No.4, 127 mm para un cepo 48 según la reutilización de Wikipedia por Alchetron; con el Demi Tasse forma la gama estándar, escribe Origin of Cigar en diciembre de 2025. Habanos describe la marca de sabor ligero a medio.","vitolas":["Hermoso No.4"],"wrapper":"Vuelta Abajo"},{"name":"Demi Tasse","color":"#D4B44A","force":"Light","story":"Entreacto, pequeña panetela de 98 mm para un cepo 30 según la reutilización de Wikipedia por Alchetron; una de las dos líneas de la gama estándar, escribe Origin of Cigar en diciembre de 2025.","vitolas":["Entreactos"],"wrapper":"Vuelta Abajo"}]',
  `gamme_de` = '[{"name":"Choix Suprême","color":"#C9A227","force":"Medium","story":"Hermoso No.4, 127 mm bei Cepo 48 nach der Übernahme von Wikipedia durch Alchetron; zusammen mit dem Demi Tasse bildet sie das Standardsortiment, schreibt Origin of Cigar im Dezember 2025. Habanos beschreibt die Marke als leicht bis mittel im Geschmack.","vitolas":["Hermoso No.4"],"wrapper":"Vuelta Abajo"},{"name":"Demi Tasse","color":"#D4B44A","force":"Light","story":"Entreacto, kleine Panetela von 98 mm bei Cepo 30 nach der Übernahme von Wikipedia durch Alchetron; eine der beiden Linien des Standardsortiments, schreibt Origin of Cigar im Dezember 2025.","vitolas":["Entreactos"],"wrapper":"Vuelta Abajo"}]',
  `gamme_zh` = '[{"name":"Choix Suprême","color":"#C9A227","force":"Medium","story":"Hermoso No.4，127 mm、cepo 48，据 Alchetron 转载的维基百科；与 Demi Tasse 一起构成标准产品线，Origin of Cigar 于2025年12月写道。Habanos 称该品牌风味轻至中等。","vitolas":["Hermoso No.4"],"wrapper":"Vuelta Abajo"},{"name":"Demi Tasse","color":"#D4B44A","force":"Light","story":"Entreacto，小型 panetela，98 mm、cepo 30，据 Alchetron 转载的维基百科；标准产品线两条线之一，Origin of Cigar 于2025年12月写道。","vitolas":["Entreactos"],"wrapper":"Vuelta Abajo"}]',
  `gamme_ar` = '[{"name":"Choix Suprême","color":"#C9A227","force":"Medium","story":"Hermoso No.4، طوله 127 mm بقياس cepo 48 بحسب نقل Alchetron عن ويكيبيديا؛ ويشكّل مع Demi Tasse التشكيلة القياسية، بحسب ما كتبته Origin of Cigar في ديسمبر 2025. وتصف Habanos العلامة بأنها خفيفة إلى متوسطة النكهة.","vitolas":["Hermoso No.4"],"wrapper":"Vuelta Abajo"},{"name":"Demi Tasse","color":"#D4B44A","force":"Light","story":"Entreacto، بانيتيلا صغيرة طولها 98 mm بقياس cepo 30 بحسب نقل Alchetron عن ويكيبيديا؛ أحد خطّي التشكيلة القياسية، بحسب ما كتبته Origin of Cigar في ديسمبر 2025.","vitolas":["Entreactos"],"wrapper":"Vuelta Abajo"}]',
  `celebrities` = '[{"name":"Antonio Allones","anecdote":"Originaire de Galice et frère de Ramón Allones, il arrive à La Havane au milieu du XIXe siècle, dit Origin of Cigar. Habanos écrit qu''il lança la marque en 1882, après plus de trente ans de cigares roulés à La Havane ; Wikipédia écrit qu''il la reprit vers 1882."},{"name":"Emilio Ohmstedt","anecdote":"Wikipédia et Origin of Cigar font de cet homme d''affaires allemand le créateur de la marque en 1848, avec Sancho Panza ; Origin of Cigar le dit mort en 1870 et rapporte que d''autres attribuent la création d''El Rey del Mundo à Allones."}]',
  `celebrities_en` = '[{"name":"Antonio Allones","anecdote":"A native of Galicia and brother of Ramón Allones, he arrived in Havana in the middle of the nineteenth century, says Origin of Cigar. Habanos writes that he launched the brand in 1882, after more than thirty years of cigars rolled in Havana; Wikipedia writes that he took it over around 1882."},{"name":"Emilio Ohmstedt","anecdote":"Wikipedia and Origin of Cigar make this German businessman the creator of the brand in 1848, with Sancho Panza; Origin of Cigar says he died in 1870 and reports that others attribute the creation of El Rey del Mundo to Allones."}]',
  `celebrities_es` = '[{"name":"Antonio Allones","anecdote":"Originario de Galicia y hermano de Ramón Allones, llega a La Habana a mediados del siglo XIX, dice Origin of Cigar. Habanos escribe que lanzó la marca en 1882, tras más de treinta años de puros liados en La Habana; Wikipedia escribe que la retomó hacia 1882."},{"name":"Emilio Ohmstedt","anecdote":"Wikipedia y Origin of Cigar hacen de este hombre de negocios alemán el creador de la marca en 1848, junto con Sancho Panza; Origin of Cigar lo da por muerto en 1870 y recoge que otros atribuyen la creación de El Rey del Mundo a Allones."}]',
  `celebrities_de` = '[{"name":"Antonio Allones","anecdote":"Aus Galicien stammend und Bruder von Ramón Allones, kam er Mitte des 19. Jahrhunderts nach Havanna, sagt Origin of Cigar. Habanos schreibt, er habe die Marke 1882 eingeführt, nach mehr als dreißig Jahren in Havanna gerollter Zigarren; Wikipedia schreibt, er habe sie um 1882 übernommen."},{"name":"Emilio Ohmstedt","anecdote":"Wikipedia und Origin of Cigar machen diesen deutschen Geschäftsmann zum Schöpfer der Marke im Jahr 1848, zusammen mit Sancho Panza; Origin of Cigar nennt ihn 1870 gestorben und berichtet, andere schrieben die Schaffung von El Rey del Mundo Allones zu."}]',
  `celebrities_zh` = '[{"name":"Antonio Allones","anecdote":"出身加利西亚，Ramón Allones 之兄，十九世纪中叶抵达哈瓦那，Origin of Cigar 如是说。Habanos 写道，他在哈瓦那卷制雪茄三十多年后于1882年推出该品牌；维基百科写道，他约在1882年接手了它。"},{"name":"Emilio Ohmstedt","anecdote":"维基百科和 Origin of Cigar 称这位德国商人是该品牌1848年的创制者，同时创制了 Sancho Panza；Origin of Cigar 说他卒于1870年，并转述另有人把 El Rey del Mundo 的创制归于 Allones。"}]',
  `celebrities_ar` = '[{"name":"Antonio Allones","anecdote":"من أصل غاليسي وأخو Ramón Allones، وصل إلى هافانا في منتصف القرن التاسع عشر، بحسب Origin of Cigar. وتكتب Habanos أنه أطلق العلامة سنة 1882، بعد ما يزيد على ثلاثين سنة من لفّ السيجار في هافانا؛ وتكتب ويكيبيديا أنه تسلّمها نحو سنة 1882."},{"name":"Emilio Ohmstedt","anecdote":"تجعل ويكيبيديا وOrigin of Cigar من هذا التاجر الألماني مبتكر العلامة سنة 1848، مع Sancho Panza؛ وتذكر Origin of Cigar أنه توفي سنة 1870 وتنقل أنّ آخرين ينسبون ابتكار El Rey del Mundo إلى Allones."}]',
  `pairings` = '[{"type":"Café","name":"Café filtre d''Amérique centrale","notes":"Suggestion d''accord, sans page derrière, pour une marque que Habanos décrit de saveur légère à moyenne."},{"type":"Spiritueux","name":"Cognac VSOP","notes":"Suggestion d''accord, sans page derrière, pour un format court comme l''Hermoso No.4 du Choix Suprême."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Central American filter coffee","notes":"A pairing suggestion, with no page behind it, for a brand that Habanos describes as light to medium in flavour."},{"type":"Spirits","name":"VSOP cognac","notes":"A pairing suggestion, with no page behind it, for a short format such as the Hermoso No.4 of the Choix Suprême."}]',
  `pairings_es` = '[{"type":"Café","name":"Café de filtro de América Central","notes":"Sugerencia de maridaje, sin página detrás, para una marca que Habanos describe de sabor ligero a medio."},{"type":"Destilados","name":"Coñac VSOP","notes":"Sugerencia de maridaje, sin página detrás, para un formato corto como el Hermoso No.4 del Choix Suprême."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Filterkaffee aus Mittelamerika","notes":"Kombinationsvorschlag ohne zugehörige Seite, für eine Marke, die Habanos als leicht bis mittel im Geschmack beschreibt."},{"type":"Spirituosen","name":"Cognac VSOP","notes":"Kombinationsvorschlag ohne zugehörige Seite, für ein kurzes Format wie den Hermoso No.4 der Choix Suprême."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"中美洲滤泡咖啡","notes":"搭配建议，背后没有页面支撑，针对 Habanos 称风味轻至中等的品牌。"},{"type":"烈酒","name":"VSOP 干邑","notes":"搭配建议，背后没有页面支撑，针对 Choix Suprême 中 Hermoso No.4 这样的短尺寸。"}]',
  `pairings_ar` = '[{"type":"قهوة","name":"قهوة مرشَّحة من أميركا الوسطى","notes":"اقتراح مرافقة بلا صفحة خلفه، لعلامة تصفها Habanos بأنها خفيفة إلى متوسطة النكهة."},{"type":"مشروبات روحية","name":"كونياك VSOP","notes":"اقتراح مرافقة بلا صفحة خلفه، لمقاس قصير مثل Hermoso No.4 من Choix Suprême."}]',
  `source` = IF(LOCATE(CAST(' — l''ancienne lecture de la fiche attribuait 1848 à la page officielle' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' — l''ancienne lecture de la fiche attribuait 1848 à la page officielle', ''), `source`),
  `source` = IF(LOCATE(CAST(' ; cubancigarwebsite.com « Tobacco and Cigar Production » (l''ancienne fabrique El Rey del Mundo / Carlos Baliño rebaptisée Romeo y Julieta, mère d''El Rey del Mundo et Saint Luis Rey)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; cubancigarwebsite.com « Tobacco and Cigar Production » (l''ancienne fabrique El Rey del Mundo / Carlos Baliño rebaptisée Romeo y Julieta, mère d''El Rey del Mundo et Saint Luis Rey)', ''), `source`),
  `source` = IF(LOCATE(CAST('habanos.com « El Rey del Mundo Brand » (https://www.habanos.' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'habanos.com « El Rey del Mundo Brand » (https://www.habanos.com/en/the-world-of-the-habano/the-habanos-brands-academia/el-rey-del-mundo-brand/, page sans date, lue le 16 octobre 2026 : 1882, Antonio Allones, légère à moyenne, aucune fabrique) ; habanos.com « The Habanos Brands Academia » (page sans date, lue le 16 octobre 2026 : 27 marques, El Rey del Mundo parmi les 13 autres) ; origin-of-cigar.com « El Rey del Mundo history » (12 décembre 2025 : 1848 Ohmstedt ou Allones, 1873, 1882, gamme standard de deux lignes) et « Romeo y Julieta history » (2 novembre 2025 : Carlos Baliño à Marianao depuis 2015) ; cigarjournal.com « Building of Many Names: Antonio Briones Montoto Factory » (15 avril 2014 : 852 Belascoaín, annuaire de 1940) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011 : Romeo y Julieta sous le nom de H. Upmann, production de Partagás vers la fabrique El Rey del Mundo) ; prensa-latina.cu « El misterioso epicentro de las fábricas de tabaco de Cuba » (29 février 2024 : Carlos Baliño, nouvelle fabrique Romeo y Julieta) ; alchetron.com « El Rey del Mundo (cigar) » (reprise de Wikipédia, sans date : dimensions du Choix Supreme et du Demi Tasse)')),
  `updated_at` = NOW()
 WHERE `name` = 'El Rey del Mundo';

-- ── Pays cuba ──
UPDATE `producer_countries` SET
  `brands` = '[{"desc":"Née en 1966, fabrique El Laguito ; l''une des six marques globales de Habanos","name":"Cohiba","iconic":true},{"desc":"Née en 1935 à la fabrique H. Upmann ; l''une des six marques globales","name":"Montecristo","iconic":true},{"desc":"Fabrique créée en 1845 par Jaime Partagás, dit Habanos ; fabrique mère Partagás ; marque globale","name":"Partagás","iconic":true},{"desc":"Nom créé en 1875 selon Habanos ; marque globale ; Churchills, vitola la plus connue de la marque, dit Habanos","name":"Romeo y Julieta","iconic":true},{"desc":"Marque de 1844 selon Habanos, fondée par le banquier allemand Herman Upmann ; marque globale","name":"H. Upmann","iconic":false},{"desc":"Créée en 1902 selon Habanos ; nom de Simón Bolívar ; fabrique mère Partagás ; marque de valeur","name":"Bolivar","iconic":false},{"desc":"Créée en 1969 pour les cadeaux diplomatiques, commercialisée en 1998 ; marque de valeur","name":"Trinidad","iconic":false},{"desc":"Enregistrée en 1840 selon Habanos, pour le marché anglais ; fabrique La Corona, avec Hoyo de Monterrey","name":"Punch","iconic":false},{"desc":"Marque enregistrée en 1865 par José Gener ; plantation de San Juan y Martínez ; marque globale","name":"Hoyo de Monterrey","iconic":true},{"desc":"Créée en 1997 en hommage à Alejandro Robaina, planteur de San Luis ; fabrique non nommée par Habanos","name":"Vegas Robaina","iconic":false},{"desc":"Née à Cienfuegos, tripe courte roulée main, tabac de Vuelta Abajo ; marque de volume","name":"Quintero","iconic":false},{"desc":"1837 selon Habanos (1845 selon Wikipédia) ; fabrique mère Partagás selon la presse ; marque de valeur","name":"Ramón Allones","iconic":true},{"desc":"1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos","name":"El Rey del Mundo","iconic":false},{"desc":"Fondée en 1885 ; série Medaille d''Or ; tripe longue ; fabrique mère Partagás","name":"La Gloria Cubana","iconic":false},{"desc":"Années 1870 (1876 selon l''usage) ; gamme réduite aux Selección No. 1 et No. 2","name":"Juan López","iconic":false},{"desc":"Fondée en 1834 ; tripe longue ou courte selon les vitoles ; fabrique La Corona","name":"Por Larrañaga","iconic":false},{"desc":"Créée dans les années 1930 ; nom de fabrique Cervantes ; avis de dégustation sous le couvercle des boîtes","name":"Rafael González","iconic":false},{"desc":"Enregistrée en 1848, nom tiré de Don Quichotte ; gamme réduite à trois havanes","name":"Sancho Panza","iconic":false},{"desc":"Avant la Seconde Guerre mondiale (1938 ou 1940) ; nom du district de San Luis, dans la Vuelta Abajo","name":"Saint Luis Rey","iconic":false},{"desc":"Années 1960 selon Habanos (1966 selon la presse) ; fabrique H. Upmann selon la presse (2011)","name":"Diplomáticos","iconic":false},{"desc":"Fondée dans les années 1890 ; présentée sous papier de soie ; tripe longue et courte","name":"Fonseca","iconic":false},{"desc":"Style de la fin du XIXe siècle relancé en 1996, dit Habanos ; fabrique mère La Corona selon la presse","name":"Cuaba","iconic":false},{"desc":"Lancée en 1999 ; vitoles aux noms de quatre forteresses de La Havane ; réseau Casas del Habano","name":"San Cristóbal de La Habana","iconic":false},{"desc":"Lancée en 1996 (1997 selon d''autres lectures) à Pinar del Río ; fabrique Francisco Donatien ; marque de volume","name":"Vegueros","iconic":false},{"desc":"Créée en 1973 par Cubatabaco à la demande de la Seita ; marque de valeur ; fabrique Partagás","name":"Quai d''Orsay","iconic":false},{"desc":"Famille venue des Asturies dans les années 1880 ; tripe courte roulée main, tabac de Remedios ; marque de volume","name":"José L. Piedra","iconic":false},{"desc":"Marque ancienne (1884 selon l''usage) ; tripe courte roulée main ; fabrique La Corona","name":"La Flor de Cano","iconic":false}]',
  `updated_at` = NOW()
 WHERE `id` = 'cuba';

