  (SHA1('1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos'), 'en', '1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos', '1882 according to Habanos, 1848 according to Wikipedia; mother factory not named by Habanos'),
