-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Ramón Allones' hote, 'celebrities' champ
        UNION ALL SELECT 'Ramón Allones' hote, 'gamme' champ
        UNION ALL SELECT 'Ramón Allones' hote, 'history' champ
        UNION ALL SELECT 'Vegas Robaina' hote, 'celebrities' champ
        UNION ALL SELECT 'Vegas Robaina' hote, 'gamme' champ
        UNION ALL SELECT 'Vegas Robaina' hote, 'history' champ
        UNION ALL SELECT 'Vegas Robaina' hote, 'pairings' champ
        UNION ALL SELECT 'Vegueros' hote, 'gamme' champ
        UNION ALL SELECT 'Vegueros' hote, 'history' champ
        UNION ALL SELECT 'Vegueros' hote, 'pairings' champ
        UNION ALL SELECT 'José L. Piedra' hote, 'gamme' champ
        UNION ALL SELECT 'José L. Piedra' hote, 'history' champ
        UNION ALL SELECT 'José L. Piedra' hote, 'pairings' champ
