        UNION ALL SELECT 'Quintero' hote, 'history' champ
        UNION ALL SELECT 'Quintero' hote, 'pairings' champ
        UNION ALL SELECT 'Diplomáticos' hote, 'celebrities' champ
        UNION ALL SELECT 'Diplomáticos' hote, 'gamme' champ
        UNION ALL SELECT 'Diplomáticos' hote, 'history' champ
        UNION ALL SELECT 'Diplomáticos' hote, 'pairings' champ
        UNION ALL SELECT 'Cuaba' hote, 'celebrities' champ
        UNION ALL SELECT 'Cuaba' hote, 'gamme' champ
        UNION ALL SELECT 'Cuaba' hote, 'history' champ
        UNION ALL SELECT 'Cuaba' hote, 'pairings' champ
        UNION ALL SELECT 'El Rey del Mundo' hote, 'celebrities' champ
        UNION ALL SELECT 'El Rey del Mundo' hote, 'gamme' champ
