-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Ramón Allones' AS hote, 'fr' AS lang, 'limited_eds : Allones No. 2 Edición Limitada 2019' AS quoi, (JSON_CONTAINS(`limited_eds`, '"Allones No. 2 Edición Limitada 2019"')) AS ok FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'limited_eds : Allones Extra Edición Limitada 2011', (JSON_CONTAINS(`limited_eds`, '"Allones Extra Edición Limitada 2011"')) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1837 (habanos.com), 1845 (Wikipédia) — La Havane' AS BINARY)) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Fabrique mère Partagás (San Carlos 806, Centro Habana, ancienne fabrique El Rey del Mundo) selon la presse du métier ; habanos.com ne nomme pas de fabrique mère' AS BINARY)) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Ramón Allones est, dit habanos.com, l''une des plus anciennes marques encore produites : la maison la dit fondée en 1837 et première à présenter ses cigares dans des boîtes décorées d''étiquettes et de l''emblème de la marque. Wikipédia donne une autre version : marque créée à Cuba par les frères Ramón et Antonio Allones, en 1845, et « supposedly » première à utiliser des lithographies en couleurs pour ses boîtes, plusieurs rivales revendiquant aussi cette innovation. Selon Wikipédia, la marque changea plusieurs fois de mains avant de passer à la famille Cifuentes.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ramón Allones est l''une des plus anciennes marques encore produites, et son fondateur a laissé au cigare une invention qu''on ne remarque plus tant elle va de soi : la boîte de bois habillée d''une étiquette imprimée en couleurs. Ramón Allones, immigré galicien installé à La Havane, fut le premier à décorer ses caisses de lithographies dorées vers 1845 — une manière de signer sa production à une époque où le cigare se vendait en vrac. Toute la présentation moderne du havane en découle.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Ramón Allones is, says habanos.com, one of the oldest brands still in production: the house says it was founded in 1837 and was the first to present its cigars in boxes decorated with labels and the brand''s emblem. Wikipedia gives another version: a brand created in Cuba by the brothers Ramón and Antonio Allones, in 1845, and “supposedly” the first to use colour lithographs for its boxes, with several rivals also claiming this innovation. According to Wikipedia, the brand changed hands several times before passing to the Cifuentes family.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ramón Allones is one of the oldest brands still in production, and its founder left the cigar an invention so self-evident that nobody notices it any more: the wooden box dressed with a colour-printed label. Ramón Allones, a Galician immigrant settled in Havana, was the first to decorate his crates with gilded lithographs around 1845 — a way of signing his output at a time when cigars were sold loose. The whole modern presentation of the Havana descends from it.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Ramón Allones es, dice habanos.com, una de las marcas más antiguas que aún se producen: la casa la dice fundada en 1837 y la primera en presentar sus puros en cajas decoradas con etiquetas y con el emblema de la marca. Wikipedia da otra versión: marca creada en Cuba por los hermanos Ramón y Antonio Allones, en 1845, y «supuestamente» la primera en usar litografías en color para sus cajas, pues varias rivales reclaman también esa innovación. Según Wikipedia, la marca cambió varias veces de manos antes de pasar a la familia Cifuentes.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ramón Allones es una de las marcas más antiguas aún en producción, y su fundador legó al cigarro una invención que ya nadie advierte de tan evidente: la caja de madera vestida con una etiqueta impresa en color. Ramón Allones, inmigrante gallego instalado en La Habana, fue el primero en decorar sus cajones con litografías doradas hacia 1845 — una manera de firmar su producción cuando el cigarro se vendía a granel. Toda la presentación moderna del habano desciende de ahí.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Ramón Allones ist, so habanos.com, eine der ältesten noch produzierten Marken: Das Haus nennt sie 1837 gegründet und als erste, die ihre Zigarren in Kisten mit Etiketten und dem Emblem der Marke präsentierte. Wikipedia gibt eine andere Version: eine in Kuba von den Brüdern Ramón und Antonio Allones im Jahr 1845 geschaffene Marke, die „angeblich“ als erste farbige Lithografien für ihre Kisten verwendete, wobei mehrere Rivalen diese Neuerung ebenfalls für sich beanspruchen. Laut Wikipedia wechselte die Marke mehrmals den Besitzer, bevor sie an die Familie Cifuentes ging.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ramón Allones ist eine der ältesten noch produzierten Marken, und ihr Gründer hinterließ der Zigarre eine Erfindung, die so selbstverständlich geworden ist, dass sie niemand mehr bemerkt: die Holzkiste mit farbig gedrucktem Etikett. Ramón Allones, ein in Havanna ansässiger galicischer Einwanderer, war um 1845 der Erste, der seine Kisten mit goldenen Lithografien schmückte — eine Art, seine Erzeugnisse zu signieren, als Zigarren noch lose verkauft wurden. Die gesamte moderne Aufmachung der Havanna geht darauf zurück.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('据 habanos.com，Ramón Allones 是仍在生产的老牌之一：该厂自称它创立于1837年，并首家把雪茄装进饰有标签和品牌徽记的盒子里。维基百科给出另一种说法：该品牌由 Ramón 与 Antonio Allones 兄弟在古巴创立，时间为1845年，并且据称是首个用彩色石版画装饰盒子的品牌，另有多家对手也声称拥有这项创新。据维基百科，该品牌几经易手，之后才传到 Cifuentes 家族手中。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('拉蒙·阿隆内斯是至今仍在生产的最古老品牌之一，而它的创始人给雪茄留下了一项如今理所当然到无人留意的发明：贴着彩印标签的木盒。这位定居哈瓦那的加利西亚移民，约在1845年率先以烫金石版画装饰自己的木箱——在雪茄尚且散卖的年代，这是为自己产品署名的一种方式。哈瓦那雪茄如今的全部呈现方式，皆源于此。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تقول habanos.com إن Ramón Allones من العلامات الضاربة في القدم التي ما زالت تُنتَج: فالدار تقول إنها تأسّست عام 1837 وإنها أول من قدّم سيجارها في علب مزيّنة بملصقات وبشعار العلامة. وتعطي ويكيبيديا رواية أخرى: علامة أنشأها في كوبا الأخوان Ramón وAntonio Allones عام 1845، و«يُزعم» أنها أول من استخدم مطبوعات حجرية ملوّنة لعلبها، مع أن عدة منافسات تدّعي هذا الابتكار أيضاً. ووفق ويكيبيديا، تداولت الأيدي العلامة مرات عدة قبل أن تنتقل إلى عائلة Cifuentes.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('«رامون أيونيس» من أقدم العلامات التي لا تزال تُنتَج، وقد ترك مؤسّسها للسيجار اختراعاً صار بديهياً إلى حدّ أن أحداً لم يعد يلاحظه: الصندوق الخشبي المكسوّ بملصق مطبوع بالألوان. فرامون أيونيس، المهاجر الغاليسي المقيم في هافانا، كان أول من زيّن صناديقه بمطبوعات حجرية مذهّبة نحو 1845 — طريقةً لتوقيع إنتاجه في زمن كان السيجار يُباع فيه سائباً. ومن هذا انحدر كل عرض الهافانا الحديث.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Selon Wikipédia, la firme Cifuentes, Pego y Cía en acquiert les droits en 1927. Habanos la classe en force corsée, au goût intense et complexe ; chaque cigare est roulé entièrement à la main en tripe longue (tripa larga), avec des feuilles de capa, de sous-cape et de tripe de la Vuelta Abajo.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La marque a traversé le XXe siècle sans jamais chercher le premier rang commercial, et c''est ce qui explique sa réputation actuelle. Son assemblage, resté franc et corsé, s''adresse à des fumeurs qui savent ce qu''ils cherchent : une matière dense, des notes de cuir, de cacao amer et de bois brûlé, une force soutenue du premier au dernier tiers.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('According to Wikipedia, the firm Cifuentes, Pego y Cía acquired the rights in 1927. Habanos classes it as full-bodied, with an intense and complex taste; every cigar is rolled entirely by hand in long filler (tripa larga), with wrapper, binder and filler leaves from the Vuelta Abajo.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The brand crossed the twentieth century without ever seeking commercial pre-eminence, and that is what explains its present reputation. Its blend, still frank and full-bodied, addresses smokers who know what they are looking for: dense matter, notes of leather, bitter cocoa and burnt wood, a sustained strength from the first third to the last.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Según Wikipedia, la firma Cifuentes, Pego y Cía adquiere los derechos en 1927. Habanos la clasifica como fuerte, de sabor intenso y complejo; cada puro se lía enteramente a mano con tripa larga, con hojas de capa, de capote y de tripa de la Vuelta Abajo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La marca atravesó el siglo XX sin buscar nunca el primer puesto comercial, y eso explica su reputación actual. Su liga, que sigue siendo franca y fuerte, se dirige a fumadores que saben lo que buscan: materia densa, notas de cuero, cacao amargo y madera quemada, una fuerza sostenida del primer al último tercio.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Laut Wikipedia erwirbt die Firma Cifuentes, Pego y Cía 1927 die Rechte. Habanos stuft sie als kräftig ein, mit intensivem und komplexem Geschmack; jede Zigarre wird vollständig von Hand in Longfiller (tripa larga) gerollt, mit Deckblatt-, Umblatt- und Einlageblättern der Vuelta Abajo.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Marke durchquerte das 20. Jahrhundert, ohne je den ersten kommerziellen Rang anzustreben, und das erklärt ihren heutigen Ruf. Ihr Blend, offen und kräftig geblieben, wendet sich an Raucher, die wissen, was sie suchen: dichte Substanz, Noten von Leder, bitterem Kakao und verbranntem Holz, eine anhaltende Kraft vom ersten bis zum letzten Drittel.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('据维基百科，Cifuentes, Pego y Cía 公司于1927年取得其权利。Habanos 将其归为浓郁型，口味浓烈而复杂；每支雪茄全部手工卷制，使用长茄芯（tripa larga），茄衣、茄套与茄芯的烟叶均来自 Vuelta Abajo。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('这个品牌穿越了整个二十世纪，却从未追逐商业上的头把交椅，而这正解释了它今日的声誉。它的配方依旧直率而浓郁，面向的是知道自己要什么的烟客：厚实的物质感，皮革、苦可可与焦木的气息，从第一段到最后一段力度不减。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('وفق ويكيبيديا، اشترت شركة Cifuentes, Pego y Cía حقوقها عام 1927. وتصنّفها Habanos قويّة، بطعم مكثّف ومعقّد؛ ويُلفّ كل سيجار بالكامل يدويًّا بحشوة طويلة (tripa larga)، بأوراق الغلاف والغلاف الداخلي والحشوة من Vuelta Abajo.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('عبرت العلامة القرن العشرين دون أن تسعى يوماً إلى الصدارة التجارية، وهذا ما يفسّر سمعتها الحالية. فخلطتها، التي بقيت صريحة وقوية، تخاطب مدخّنين يعرفون ما يبحثون عنه: مادة كثيفة، ونفحات جلد وكاكاو مرّ وخشب محروق، وقوّة مستمرّة من الثلث الأول إلى الأخير.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('L''Allones Specially Selected est, avec Gigantes, l''une des deux vitolas que habanos.com met en avant ; Wikipédia en donne le format : Robusto, 4 7/8 pouces sur cepo 50 (124 mm). Selon la presse du métier, c''est la vitola la plus connue de la gamme.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Le Specially Selected, un Robusto, est le cigare qui porte la marque depuis les années 1970. Il est régulièrement cité parmi les havanes que les connaisseurs conseillent en premier à qui veut comprendre ce qu''apporte le vieillissement : sorti de boîte il est brutal, à cinq ans il devient une des expressions les plus rondes du profil cubain corsé.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The Allones Specially Selected is, with Gigantes, one of the two vitolas that habanos.com puts forward; Wikipedia gives its size: Robusto, 4 7/8 inches on cepo 50 (124 mm). According to the trade press, it is the best-known vitola in the range.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The Specially Selected, a Robusto, is the cigar that has carried the brand since the 1970s. It is regularly cited among the Havanas connoisseurs recommend first to anyone who wants to understand what ageing brings: straight from the box it is brutal, at five years it becomes one of the roundest expressions of the full-bodied Cuban profile.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('El Allones Specially Selected es, junto con Gigantes, una de las dos vitolas que destaca habanos.com; Wikipedia da su formato: Robusto, 4 7/8 pulgadas de cepo 50 (124 mm). Según la prensa del oficio, es la vitola más conocida de la gama.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('El Specially Selected, un Robusto, es el cigarro que lleva la marca desde los años setenta. Se le cita con regularidad entre los habanos que los conocedores recomiendan primero a quien quiere entender lo que aporta el envejecimiento: recién salido de la caja es brutal; a los cinco años se convierte en una de las expresiones más redondas del perfil cubano fuerte.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Die Allones Specially Selected ist zusammen mit Gigantes eine der beiden Vitolas, die habanos.com hervorhebt; Wikipedia nennt ihr Format: Robusto, 4 7/8 Zoll bei Cepo 50 (124 mm). Laut der Fachpresse ist sie die bekannteste Vitola der Serie.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
