UNION ALL SELECT 'Ramón Allones', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('أمّا «سبيشلي سيليكتد»، وهو روبوستو، فهو السيجار الذي يحمل العلامة منذ السبعينيات. ويُذكر بانتظام بين الهافانات التي ينصح بها الخبراء أولاً لمن يريد أن يفهم ما يفعله التعتيق: خارجاً من الصندوق يكون قاسياً، وعند خمس سنوات يصير من أكثر تعبيرات الطابع الكوبي القويّ استدارة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La marque a porté des éditions régionales (habanos.com) : Selección Suprema pour l''Italie et Belicoso pour le Royaume-Uni en 2005 (Wikipédia), puis, selon la presse du métier, le Mexique (2021), le Royaume-Uni (Private Stock 230, 2022) et les Pays-Bas (2022). L''Allones No. 2, présentée au Festival del Habano de février 2019, est sa troisième Edición Limitada (Cigar Coop).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
