UNION ALL SELECT 'Ramón Allones', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('The brand has carried regional editions (habanos.com): Selección Suprema for Italy and Belicoso for the United Kingdom in 2005 (Wikipedia), then, according to the trade press, Mexico (2021), the United Kingdom (Private Stock 230, 2022) and the Netherlands (2022). The Allones No. 2, presented at the Festival del Habano of February 2019, is its third Edición Limitada (Cigar Coop).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
