UNION ALL SELECT 'Ramón Allones', 'ar', 'celebrities 0', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities_ar`, '$[0].anecdote')) AS BINARY) = CAST('وفق ويكيبيديا، أنشأ العلامة في كوبا الأخوان Ramón وAntonio Allones، دون صلة بـ Antonio Allones صاحب El Rey del Mundo. تؤرّخ Habanos العلامة بعام 1837 وتقول إنها أول من قدّم سيجارها في علب مزيّنة بملصقات وبشعارها؛ أما ويكيبيديا، التي تؤرّخ الإنشاء بعام 1845، فتقول فقط إنها يُفترض أن تكون أول من استخدم مطبوعات حجرية ملوّنة، فيما تدّعي علامات أخرى الابتكار نفسه.' AS BINARY)) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'ar', 'celebrities (nombre)', (JSON_LENGTH(`celebrities_ar`) = 1) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'source (citation retirée)', (LOCATE(CAST('cubancigarwebsite.com « Tobacco and Cigar Production » (Partagás mère de Ramón Allones) ; ' AS BINARY), CAST(`source` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Ramón Allones', 'fr', 'source', (LOCATE(CAST('habanos.com « Partagás Brand » (sans date : fabrique d''Indus' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ramón Allones'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Habanos ne nomme pas de fabrique mère ; Wikipédia dit La Havane, ancienne fabrique H. Upmann ; Francisco Donatien (Pinar del Río) : aucune page lue ne le confirme' AS BINARY)) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Vegas Robaina porte le nom d''Alejandro Robaina, planteur de la Vuelta Abajo, et vient, dit habanos.com, d''un hommage aux planteurs de tabac cubains à travers sa figure. Habanos écrit que sa famille cultive du tabac depuis 1845 à Cuchillas de Barbacoa, dans le district de San Luis ; la presse du métier parle en 2010 d''une ferme familiale depuis le milieu des années 1800, d''environ 40 acres, presque entièrement consacrée à la capa.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina est la seule marque de cigares cubains à porter le nom d''un veguero — un cultivateur — plutôt qu''un fabricant, un personnage historique, ou un lieu. Alejandro Robaina, né en 1919 dans la région de Vuelta Abajo, hérita des terres familiales de San Luis et les cultiva avec une obstination méthodique pendant plus de soixante ans.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Vegas Robaina bears the name of Alejandro Robaina, a Vuelta Abajo grower, and comes, says habanos.com, from a tribute to Cuban tobacco growers through his figure. Habanos writes that his family has grown tobacco since 1845 at Cuchillas de Barbacoa, in the San Luis district; the trade press speaks in 2010 of a family farm since the mid-1800s, of about 40 acres, almost entirely devoted to wrapper.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina is the only Cuban cigar brand to bear the name of a veguero — a tobacco grower — rather than a manufacturer, a historical figure, or a place. Alejandro Robaina, born in 1919 in the Vuelta Abajo region, inherited the family lands of San Luis and cultivated them with methodical obstinacy for more than sixty years.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Vegas Robaina lleva el nombre de Alejandro Robaina, plantador de la Vuelta Abajo, y viene, dice habanos.com, de un homenaje a los plantadores de tabaco cubanos a través de su figura. Habanos escribe que su familia cultiva tabaco desde 1845 en Cuchillas de Barbacoa, en el distrito de San Luis; la prensa del oficio habla en 2010 de una finca familiar desde mediados de los años 1800, de unos 40 acres, casi enteramente dedicada a la capa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina es la única marca de puros cubanos que lleva el nombre de un veguero —un cultivador— y no el de un fabricante, un personaje histórico o un lugar. Alejandro Robaina, nacido en 1919 en la comarca de Vuelta Abajo, heredó las tierras familiares de San Luis y las cultivó con una obstinación metódica durante más de sesenta años.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Vegas Robaina trägt den Namen von Alejandro Robaina, einem Pflanzer der Vuelta Abajo, und geht, so habanos.com, auf eine Hommage an die kubanischen Tabakpflanzer durch seine Person zurück. Habanos schreibt, dass seine Familie seit 1845 in Cuchillas de Barbacoa im Distrikt San Luis Tabak anbaut; die Fachpresse spricht 2010 von einem Familienbetrieb seit Mitte der 1800er Jahre mit etwa 40 Acres, fast ganz dem Deckblatt gewidmet.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina ist die einzige kubanische Zigarrenmarke, die den Namen eines Veguero — eines Pflanzers — trägt und nicht den eines Fabrikanten, einer historischen Gestalt oder eines Ortes. Alejandro Robaina, 1919 in der Gegend der Vuelta Abajo geboren, erbte die Familienländereien von San Luis und bebaute sie über sechzig Jahre lang mit methodischer Hartnäckigkeit.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Vegas Robaina 以 Alejandro Robaina 之名命名，他是 Vuelta Abajo 的烟农；据 habanos.com，这个品牌源于借他的形象向古巴烟农致敬。Habanos 写道，他的家族自1845年起在 San Luis 区的 Cuchillas de Barbacoa 种植烟草；行业媒体在2010年提到一座自19世纪中叶起的家族农场，约40英亩，几乎全部用于种植茄衣烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina 是唯一一个以 veguero（烟农）之名命名的古巴雪茄品牌，而非取自制造商、历史人物或地名。Alejandro Robaina 1919 年生于 Vuelta Abajo 地区，继承了 San Luis 的家族土地，以一种有条不紊的执拗耕作了六十余年。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تحمل Vegas Robaina اسم Alejandro Robaina، مزارع من Vuelta Abajo، وهي، بحسب habanos.com، مستمدّة من تكريم لمزارعي التبغ الكوبيين من خلال شخصه. وتكتب Habanos أن عائلته تزرع التبغ منذ 1845 في Cuchillas de Barbacoa بمقاطعة San Luis؛ وتتحدث الصحافة المتخصصة عام 2010 عن مزرعة عائلية منذ منتصف القرن التاسع عشر، مساحتها نحو 40 أكرًا، مخصّصة تقريبًا كلها لأوراق الغلاف.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina هي العلامة الكوبية الوحيدة التي تحمل اسم «فيغيرو» — أي مزارع تبغ — لا اسم صانع أو شخصية تاريخية أو مكان. فقد ورث Alejandro Robaina، المولود عام 1919 في منطقة Vuelta Abajo، أراضي العائلة في San Luis وزرعها بعناد منهجي أكثر من ستين عاماً.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipédia écrit que, chaque année, 80 % de sa récolte était jugée apte à servir de capa, contre environ 35 % dans d''autres plantations. À sa mort, la presse du métier le décrivait comme un ambassadeur mondial officieux du cigare cubain. Son petit-fils Hiroshi, 33 ans, avait repris l''exploitation environ trois ans avant la mort de son grand-père (presse du métier, 2010).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''histoire de Don Alejandro est celle d''une réputation bâtie feuille par feuille, sans communication, sur la seule qualité du tabac. Ses capes colorado maduro — sombres, huileuses, d''une régularité de texture remarquable — étaient achetés à prix premium par les plus grandes manufactures de La Havane depuis les années 1950. Cohiba, Montecristo, Partagás commandaient du tabac Robaina sans que le public en sût rien.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipedia writes that, each year, 80% of his harvest was judged fit to serve as wrapper, against about 35% on other plantations. At his death, the trade press described him as an unofficial worldwide ambassador for the Cuban cigar. His grandson Hiroshi, 33, had taken over the farm about three years before his grandfather''s death (trade press, 2010).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The story of Don Alejandro is one of a reputation built leaf by leaf, without any communication strategy, on the sole quality of the tobacco. His colorado maduro wrappers — dark, oily, of remarkable textural consistency — were purchased at premium prices by the greatest Havana manufacturers since the 1950s. Cohiba, Montecristo, Partagás all sourced Robaina tobacco without the public knowing anything about it.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipedia escribe que, cada año, el 80 % de su cosecha se consideraba apta para servir de capa, frente a cerca del 35 % en otras plantaciones. A su muerte, la prensa del oficio lo describía como un embajador mundial extraoficial del puro cubano. Su nieto Hiroshi, de 33 años, había asumido la explotación unos tres años antes de la muerte de su abuelo (prensa del oficio, 2010).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La historia de Don Alejandro es la de una reputación construida hoja a hoja, sin comunicación alguna, sobre la sola calidad del tabaco. Sus capas colorado maduro —oscuras, aceitosas, de una regularidad de textura notable— se las compraban a precio premium las mayores manufacturas de La Habana desde los años cincuenta. Cohiba, Montecristo y Partagás encargaban tabaco Robaina sin que el público lo supiera.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipedia schreibt, dass jedes Jahr 80 % seiner Ernte als tauglich für das Deckblatt galten, gegenüber etwa 35 % auf anderen Plantagen. Bei seinem Tod beschrieb ihn die Fachpresse als inoffiziellen Weltbotschafter der kubanischen Zigarre. Sein Enkel Hiroshi, 33 Jahre alt, hatte den Betrieb etwa drei Jahre vor dem Tod seines Großvaters übernommen (Fachpresse, 2010).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Geschichte von Don Alejandro ist die eines Rufs, der Blatt für Blatt entstand, ohne jede Werbung, allein aus der Güte des Tabaks. Seine Colorado-Maduro-Deckblätter — dunkel, ölig, von bemerkenswert gleichmäßiger Textur — wurden seit den 1950er Jahren von den größten Manufakturen Havannas zu Spitzenpreisen gekauft. Cohiba, Montecristo und Partagás bestellten Robaina-Tabak, ohne dass die Öffentlichkeit davon wusste.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('维基百科写道，他每年的收成中有80%被认为适合用作茄衣，而其他种植园约为35%。他去世时，行业媒体称他是古巴雪茄的非官方全球大使。他的孙子 Hiroshi 当年33岁，大约在祖父去世前三年接管了农场（行业媒体，2010年）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Don Alejandro 的故事，是一份不靠任何宣传、单凭烟叶品质、一片叶子一片叶子累积起来的声誉。他的 colorado maduro 茄衣——深色、油润、质地齐整得出奇——自 1950 年代起便被哈瓦那最大的几家工厂以高价收购。Cohiba、Montecristo、Partagás 都在订购 Robaina 的烟叶，而公众对此一无所知。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تكتب ويكيبيديا أن 80% من محصوله كل سنة كان يُعدّ صالحًا لأوراق الغلاف، مقابل نحو 35% في مزارع أخرى. وعند وفاته وصفته الصحافة المتخصصة بأنه سفير عالمي غير رسمي للسيجار الكوبي. وكان حفيده Hiroshi، البالغ 33 عامًا، قد تسلّم المزرعة قبل وفاة جدّه بنحو ثلاث سنوات (الصحافة المتخصصة، 2010).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('قصة Don Alejandro هي قصة سمعة بُنيت ورقةً ورقة، بلا أي دعاية، على جودة التبغ وحدها. فأغلفته من نوع colorado maduro — داكنة، زيتية، وذات انتظام لافت في النسيج — كانت كبرى مصانع هافانا تشتريها بأسعار عالية منذ الخمسينيات. وكانت Cohiba وMontecristo وPartagás تطلب تبغ Robaina دون أن يعلم الجمهور شيئاً.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos dit la marque créée en 1997 ; Wikipédia précise que Habanos S.A. lançait alors une ligne portant le nom de ses terres. Selon la presse du métier, Alejandro Robaina disait que la marque créée en son honneur ne contenait pas de son tabac. Il mourut le 17 avril 2010, à 91 ans, chez lui à San Luis, après un long cancer (presse du métier).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('En 1997, Habanos S.A. fit le choix radicalement inhabituel de créer une marque portant son nom — reconnaissant publiquement ce que le commerce cubain savait depuis des décennies. Don Alejandro avait 78 ans quand la marque fut lancée. Il mourut en 2010 à 91 ans, entouré de ses plantations.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos says the brand was created in 1997; Wikipedia adds that Habanos S.A. was then launching a line named after his lands. According to the trade press, Alejandro Robaina said that the brand created in his honour did not contain his tobacco. He died on 17 April 2010, aged 91, at home in San Luis, after a long-standing cancer (trade press).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('In 1997, Habanos S.A. made the radically unusual choice to create a brand bearing his name — publicly acknowledging what Cuban commerce had known for decades. Don Alejandro was 78 years old when the brand launched. He died in 2010 at age 91, surrounded by his plantations.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos dice que la marca se creó en 1997; Wikipedia precisa que Habanos S.A. lanzaba entonces una línea con el nombre de sus tierras. Según la prensa del oficio, Alejandro Robaina decía que la marca creada en su honor no contenía su tabaco. Murió el 17 de abril de 2010, a los 91 años, en su casa de San Luis, tras un largo cáncer (prensa del oficio).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('En 1997, Habanos S.A. tomó la decisión radicalmente insólita de crear una marca con su nombre, reconociendo en público lo que el comercio cubano sabía desde hacía décadas. Don Alejandro tenía 78 años cuando se lanzó la marca. Murió en 2010, a los 91, rodeado de sus plantaciones.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos zufolge wurde die Marke 1997 geschaffen; Wikipedia präzisiert, dass Habanos S.A. damals eine Linie mit dem Namen seiner Ländereien auflegte. Laut der Fachpresse sagte Alejandro Robaina, die zu seinen Ehren geschaffene Marke enthalte nichts von seinem Tabak. Er starb am 17. April 2010 im Alter von 91 Jahren zu Hause in San Luis nach langer Krebserkrankung (Fachpresse).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('1997 traf Habanos S.A. die ganz und gar ungewöhnliche Entscheidung, eine Marke unter seinem Namen zu schaffen — und erkannte damit öffentlich an, was der kubanische Handel seit Jahrzehnten wusste. Don Alejandro war 78 Jahre alt, als die Marke eingeführt wurde. Er starb 2010 mit 91 Jahren, inmitten seiner Pflanzungen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos 称该品牌创建于1997年；维基百科补充说，Habanos S.A. 当时推出了一条以他的土地命名的产品线。据行业媒体，Alejandro Robaina 曾说，以他之名创建的品牌里并没有他的烟叶。他于2010年4月17日在 San Luis 的家中去世，享年91岁，此前长期患癌（行业媒体）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('1997 年，Habanos S.A. 做出了一个极不寻常的决定：以他的名字创立一个品牌，等于公开承认古巴烟草业早已知晓数十年的事实。品牌推出时，Don Alejandro 已 78 岁。2010 年他在自己的烟田环绕中辞世，享年 91 岁。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تقول Habanos إن العلامة أُنشئت عام 1997؛ وتوضح ويكيبيديا أن Habanos S.A. كانت تطلق حينها خطًّا يحمل اسم أراضيه. وبحسب الصحافة المتخصصة كان Alejandro Robaina يقول إن العلامة المُنشأة تكريمًا له لا تحتوي على تبغه. وتوفي في 17 أبريل 2010 عن 91 عامًا في بيته بـ San Luis بعد سرطان طويل (الصحافة المتخصصة).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وفي 1997 اتخذت Habanos S.A. قراراً غير مألوف على الإطلاق: إنشاء علامة تحمل اسمه، اعترافاً علنياً بما كانت تجارة التبغ الكوبية تعرفه منذ عقود. كان Don Alejandro في الثامنة والسبعين يوم أُطلقت العلامة، وتوفّي عام 2010 عن 91 عاماً بين مزارعه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Habanos écrit que les feuilles viennent de la Vuelta Abajo, que chaque cigare est roulé entièrement à la main en tripe longue, en force moyenne à corsée, et que la marque compte cinq vitolas. Wikipédia en donne les formats : Único (pirámide, 6 1/8 pouces sur cepo 52), Famoso (Hermoso No. 4, 5 sur 48), Familiar (corona, 5 5/8 sur 42), Don Alejandro (prominente, 7 5/8 sur 49) et Clásico (cervantes, 6 1/2 sur 42, abandonnée). En juillet 2003, habanos.com présentait un coffret de 100 Habanos aux formats Don Alejandro, Clásicos, Famosos et Únicos, plus 20 Gordito (141 mm, cepo 50), vendu par le réseau La Casa del Habano. La page de marque de habanos.com ne donne ni les noms ni les dimensions des cinq vitolas.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
