UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Habanos writes that the leaves come from the Vuelta Abajo, that every cigar is rolled entirely by hand in long filler, in medium to full-bodied strength, and that the brand has five vitolas. Wikipedia gives their sizes: Único (pirámide, 6 1/8 inches on cepo 52), Famoso (Hermoso No. 4, 5 on 48), Familiar (corona, 5 5/8 on 42), Don Alejandro (prominente, 7 5/8 on 49) and Clásico (cervantes, 6 1/2 on 42, discontinued). In July 2003, habanos.com presented a set of 100 Habanos in the Don Alejandro, Clásicos, Famosos and Únicos sizes, plus 20 Gordito (141 mm, cepo 50), sold through the La Casa del Habano network. The brand page on habanos.com gives neither the names nor the dimensions of the five vitolas.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
