UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Habanos escribe que las hojas proceden de la Vuelta Abajo, que cada puro se lía enteramente a mano con tripa larga, de fuerza media a fuerte, y que la marca cuenta con cinco vitolas. Wikipedia da sus formatos: Único (pirámide, 6 1/8 pulgadas de cepo 52), Famoso (Hermoso No. 4, 5 de 48), Familiar (corona, 5 5/8 de 42), Don Alejandro (prominente, 7 5/8 de 49) y Clásico (cervantes, 6 1/2 de 42, abandonada). En julio de 2003, habanos.com presentaba un cofre de 100 Habanos en los formatos Don Alejandro, Clásicos, Famosos y Únicos, más 20 Gordito (141 mm, cepo 50), vendido por la red La Casa del Habano. La página de marca de habanos.com no da ni los nombres ni las dimensiones de las cinco vitolas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
