UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina wird in äußerst geringen Mengen hergestellt. Die Manufaktur verwendet ausschließlich Blätter aus den Ländereien der Familie Robaina in San Luis — eine geografische Beschränkung, die jede nennenswerte Ausweitung der Produktion ausschließt. Die Don Alejandro (Gran Corona 55×180 mm) gehört zu den begehrtesten und außerhalb Kubas am schwersten erhältlichen kubanischen Formaten. Der Enkel Hiroshi Robaina führt die Tradition mit derselben Strenge fort.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Habanos 写道，烟叶来自 Vuelta Abajo，每支雪茄全部手工卷制，使用长茄芯，力度中等至浓郁，该品牌共有五款 vitola。维基百科给出了它们的规格：Único（pirámide，6 1/8英寸，cepo 52）、Famoso（Hermoso No. 4，5英寸，cepo 48）、Familiar（corona，5 5/8英寸，cepo 42）、Don Alejandro（prominente，7 5/8英寸，cepo 49）和 Clásico（cervantes，6 1/2英寸，cepo 42，已停产）。2003年7月，habanos.com 推出过一款100支 Habanos 的套盒，含 Don Alejandro、Clásicos、Famosos 和 Únicos 规格，另加20支 Gordito（141毫米，cepo 50），通过 La Casa del Habano 网络销售。habanos.com 的品牌页面既没有给出这五款 vitola 的名称，也没有给出尺寸。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Vegas Robaina 的产量极其有限。工厂只使用 San Luis 的 Robaina 家族地产所出的烟叶——这一地理限制排除了任何显著扩产的可能。Don Alejandro（Gran Corona 55×180mm）是最受追捧、在古巴境外也最难寻得的古巴规格之一。孙子 Hiroshi Robaina 以同样的严谨延续着这一传统。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('تكتب Habanos أن الأوراق تأتي من Vuelta Abajo، وأن كل سيجار يُلفّ بالكامل يدويًّا بحشوة طويلة، بقوّة متوسطة إلى قويّة، وأن للعلامة خمسة مقاسات vitola. وتذكر ويكيبيديا أبعادها: Único (pirámide، 6 1/8 بوصة بمقياس cepo 52)، وFamoso (Hermoso No. 4، 5 على 48)، وFamiliar (corona، 5 5/8 على 42)، وDon Alejandro (prominente، 7 5/8 على 49)، وClásico (cervantes، 6 1/2 على 42، متروك). وفي يوليو 2003 عرضت habanos.com علبة من 100 Habanos بمقاسات Don Alejandro وClásicos وFamosos وÚnicos، إضافة إلى 20 Gordito (141 مم، cepo 50)، تُباع عبر شبكة La Casa del Habano. ولا تذكر صفحة العلامة في habanos.com أسماء المقاسات الخمسة ولا أبعادها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('تُنتج Vegas Robaina بكميات محدودة للغاية. فالمصنع لا يستخدم إلا أوراقاً من أملاك عائلة Robaina في San Luis — قيد جغرافي يمنع أي زيادة معتبرة في الإنتاج. و Don Alejandro (طراز Gran Corona بقياس 55×180 مم) من أكثر الأطرزة الكوبية طلباً وأصعبها توفّراً خارج كوبا. أما الحفيد Hiroshi Robaina فيواصل التقليد بالصرامة نفسها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme aucune fabrique mère pour Vegas Robaina ; la presse du métier, qui décrit la fabrique Francisco Donatién de Pinar del Río (environ 90 % de Trinidad, un peu de Romeo y Julieta), ne cite pas Vegas Robaina. En octobre 2026, habanos.com la range parmi ses 27 marques, dans le groupe des treize « autres » marques, hors des six globales, des cinq de valeur et des trois de volume. La page officielle fait remonter la vega familiale de Cuchillas de Barbacoa, dans le district de San Luis, à 1845, et la marque à 1997, en hommage à Alejandro Robaina et, à travers lui, à tous les planteurs ; cinq vitolas en tripe longue, en force moyenne à corsée. Wikipédia, de son côté, écrit que les cigares sont roulés à La Havane, dans l''ancienne fabrique H. Upmann.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Francisco Donatien, à Pinar del Río — un bâtiment de 1868, fabrique de cigares depuis 1961, relevée à la fin des années 1990. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle fait remonter la vega familiale de Cuchillas de Barbacoa, dans le district de San Luis, à 1845, et la marque à 1997, en hommage à Alejandro Robaina et, à travers lui, à tous les planteurs ; cinq vitoles en tripe longue. Sa fabrique mère est à Pinar del Río même.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos names no mother factory for Vegas Robaina; the trade press, which describes the Francisco Donatién factory of Pinar del Río (about 90% of Trinidad, a little Romeo y Julieta), does not mention Vegas Robaina. In October 2026, habanos.com places it among its 27 brands, in the group of thirteen “other” brands, outside the six global ones, the five value ones and the three volume ones. The official page traces the family vega at Cuchillas de Barbacoa, in the San Luis district, to 1845, and the brand to 1997, in homage to Alejandro Robaina and, through him, to all growers; five vitolas in long filler, in medium to full-bodied strength. Wikipedia, for its part, writes that the cigars are rolled in Havana, in the former H. Upmann factory.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Francisco Donatien, in Pinar del Río — an 1868 building, a cigar factory since 1961, upgraded in the late 1990s. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page traces the family vega at Cuchillas de Barbacoa, in the San Luis district, to 1845, and the brand to 1997, in homage to Alejandro Robaina and, through him, to all growers; five sizes in long filler. Its mother factory is in Pinar del Río itself.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra ninguna fábrica madre para Vegas Robaina; la prensa del oficio, que describe la fábrica Francisco Donatién de Pinar del Río (cerca del 90 % de Trinidad, un poco de Romeo y Julieta), no cita Vegas Robaina. En octubre de 2026, habanos.com la clasifica entre sus 27 marcas, en el grupo de las trece «otras» marcas, fuera de las seis globales, las cinco de valor y las tres de volumen. La página oficial remonta la vega familiar de Cuchillas de Barbacoa, en el distrito de San Luis, a 1845, y la marca a 1997, en homenaje a Alejandro Robaina y, a través de él, a todos los plantadores; cinco vitolas con tripa larga, de fuerza media a fuerte. Wikipedia, por su parte, escribe que los puros se lían en La Habana, en la antigua fábrica H. Upmann.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Francisco Donatien, en Pinar del Río — un edificio de 1868, fábrica de puros desde 1961, renovada a finales de los años noventa. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial remonta la vega familiar de Cuchillas de Barbacoa, en el distrito de San Luis, a 1845, y la marca a 1997, en homenaje a Alejandro Robaina y, a través de él, a todos los vegueros; cinco vitolas con tripa larga. Su fábrica madre está en el propio Pinar del Río.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt für Vegas Robaina keine Mutterfabrik; die Fachpresse, die die Fabrik Francisco Donatién in Pinar del Río beschreibt (etwa 90 % von Trinidad, ein wenig Romeo y Julieta), nennt Vegas Robaina nicht. Im Oktober 2026 führt habanos.com sie unter ihren 27 Marken, in der Gruppe der dreizehn „anderen“ Marken, außerhalb der sechs globalen, der fünf Wertmarken und der drei Volumenmarken. Die offizielle Seite führt die Familien-Vega in Cuchillas de Barbacoa, im Distrikt San Luis, auf 1845 zurück und die Marke auf 1997, zu Ehren Alejandro Robainas und durch ihn aller Pflanzer; fünf Vitolas in Longfiller, in mittlerer bis kräftiger Stärke. Wikipedia schreibt seinerseits, die Zigarren würden in Havanna in der früheren Fabrik H. Upmann gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Francisco Donatien in Pinar del Río — ein Gebäude von 1868, Zigarrenfabrik seit 1961, Ende der 1990er Jahre aufgewertet. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite führt die Familien-Vega in Cuchillas de Barbacoa, im Distrikt San Luis, auf 1845 zurück und die Marke auf 1997, zu Ehren Alejandro Robainas und durch ihn aller Pflanzer; fünf Formate in Longfiller. Ihre Mutterfabrik liegt in Pinar del Río selbst.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有为 Vegas Robaina 指明任何母厂；行业媒体描述了 Pinar del Río 的 Francisco Donatién 厂（约90%的 Trinidad，少量 Romeo y Julieta），却没有提到 Vegas Robaina。2026年10月，habanos.com 把它列在27个品牌之中，归入十三个“其他”品牌一组，不在六个全球品牌、五个价值品牌和三个销量品牌之内。官方页面把家族在 San Luis 区 Cuchillas de Barbacoa 的烟田追溯到1845年，把品牌定在1997年，以纪念 Alejandro Robaina 并借他致敬所有种植者；五款 vitola 皆为长茄芯，力度中等至浓郁。维基百科则写道，雪茄在哈瓦那卷制，就在原 H. Upmann 厂。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是比那尔德里奥的 Francisco Donatien 厂——1868年的建筑，1961年起做雪茄，1990年代末升级。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把家族在圣路易斯区库奇亚斯-德巴尔瓦科亚的烟田追溯到1845年，把品牌定在1997年，以纪念亚历杭德罗·罗瓦伊纳并借他致敬所有种植者；五款规格皆为长茄芯。它的母厂就在比那尔德里奥。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي Habanos أي مصنع أمّ لـ Vegas Robaina؛ والصحافة المتخصصة، التي تصف مصنع Francisco Donatién في Pinar del Río (نحو 90% من Trinidad وقدر يسير من Romeo y Julieta)، لا تذكر Vegas Robaina. في أكتوبر 2026 تصنّفها habanos.com ضمن علاماتها الـ27، في مجموعة العلامات «الأخرى» الثلاث عشرة، خارج العلامات العالمية الستّ وعلامات القيمة الخمس وعلامات الحجم الثلاث. تعيد الصفحة الرسمية مزرعة العائلة في Cuchillas de Barbacoa، بمقاطعة San Luis، إلى 1845، والعلامة إلى 1997 تكريمًا لـ Alejandro Robaina ومن خلاله لكلّ المزارعين؛ خمسة مقاسات vitola بحشوة طويلة، بقوّة متوسطة إلى قويّة. وتكتب ويكيبيديا من جهتها أن السيجار يُلفّ في هافانا، في مصنع H. Upmann السابق.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
UNION ALL SELECT 'Vegas Robaina', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Francisco Donatien في بينار ديل ريو — مبنى من 1868، مصنع سيجار منذ 1961، جُدّد في أواخر التسعينيات. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تعيد الصفحة الرسمية مزرعة العائلة في كوتشيّاس دي بارباكوا، بمقاطعة سان لويس، إلى 1845، والعلامة إلى 1997 تكريمًا لأليخاندرو روباينا ومن خلاله لكلّ المزارعين؛ خمسة قياسات بحشوة طويلة. ومصنعها الأمّ في بينار ديل ريو نفسها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas Robaina'
