UNION ALL SELECT 'Vegueros', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('A veguero is a tobacco grower — the one who works a vega, the plot. The brand, launched in 1997, was created in Pinar del Río itself, in the province that supplies most of the country''s leaves, and conceived first of all for those who live there: a working cigar, honest, without staging.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
