UNION ALL SELECT 'Vegueros', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ein Veguero ist ein Tabakpflanzer — jener, der eine Vega bewirtschaftet, die Parzelle. Die 1997 lancierte Marke entstand in Pinar del Río selbst, in der Provinz, die den Großteil der Blätter des Landes liefert, und war zuallererst für jene gedacht, die dort leben: eine Arbeitszigarre, ehrlich, ohne Inszenierung.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
