UNION ALL SELECT 'Vegueros', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('الـ«ڤيغيرو» مزارع تبغ — ذاك الذي يعمل في «ڤيغا»، أي القطعة. أُطلقت العلامة سنة 1997، وأُنشئت في بينار ديل ريو نفسها، في المقاطعة التي تمدّ البلاد بمعظم أوراقها، وصُمّمت أولاً لمن يعيشون هناك: سيجار عملٍ، صادق، بلا إخراج مسرحي.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le nom de la marque désigne les vegueros, ces planteurs que la maison dit honorer. La gamme actuelle se vend en boîtes métalliques de seize, selon habanos.com ; la presse du métier décrit en 2014 des boîtes verticales de seize ou des paquets de cinq, et en 2019 des boîtes métalliques carrées.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
