UNION ALL SELECT 'Vegueros', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The brand''s name designates the vegueros, those growers whom the house says it honours. The current range is sold in metal tins of sixteen, according to habanos.com; the trade press describes, in 2014, upright boxes of sixteen or packs of five, and in 2019 square metal tins.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('That is what makes it a case apart in the portfolio. Where the other brands tell of drawing rooms and dynasties, Vegueros speaks of the field. The presentation follows: round metal tins, sober, designed for carrying rather than for the display case.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('El nombre de la marca designa a los vegueros, esos cultivadores a quienes la casa dice honrar. La gama actual se vende en latas metálicas de dieciséis, según habanos.com; la prensa del oficio describe en 2014 cajas verticales de dieciséis o paquetes de cinco, y en 2019 latas metálicas cuadradas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Eso la convierte en un caso aparte en el portafolio. Allí donde las otras marcas cuentan salones y dinastías, Vegueros habla de campo. La presentación lo sigue: latas metálicas redondas, sobrias, concebidas para el transporte antes que para la vitrina.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Der Name der Marke bezeichnet die Vegueros, jene Pflanzer, die das Haus nach eigener Aussage ehrt. Die aktuelle Palette wird laut habanos.com in Metalldosen zu sechzehn verkauft; die Fachpresse beschreibt 2014 stehende Kisten zu sechzehn oder Fünferpackungen und 2019 quadratische Metalldosen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das macht sie zu einem Sonderfall im Sortiment. Wo die anderen Marken von Salons und Dynastien erzählen, spricht Vegueros vom Feld. Die Aufmachung folgt: runde Blechdosen, nüchtern, für den Transport gedacht und nicht für die Vitrine.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('品牌名指的是 vegueros，即品牌方称所致敬的那些种植者。现行系列据 habanos.com 以十六支金属盒装出售；行业媒体在2014年描述过十六支的竖式盒或五支一包，2019年则描述过方形金属盒。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('这让它在整个产品序列中成为一个特例。当别的品牌讲述沙龙与家族王朝时，维格罗斯谈的是田地。呈现方式也随之而来：素净的圆形金属罐，为携带而非为橱窗而设计。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegueros'
UNION ALL SELECT 'Vegueros', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يدلّ اسم العلامة على الـ«ڤيغيروس»، أولئك المزارعين الذين تقول الدار إنها تكرّمهم. وتُباع المجموعة الحالية في علب معدنية من ستّ عشرة، بحسب habanos.com؛ وتصف الصحافة المتخصّصة سنة 2014 علبًا عمودية من ستّ عشرة أو عبوات من خمس قطع، وسنة 2019 علبًا معدنية مربّعة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
