UNION ALL SELECT 'Vegueros', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Selon la presse du métier, la gamme a été entièrement refondue : présentée au Festival del Habano de 2013, elle n''est arrivée en boutique qu''en 2014, avec une nouvelle présentation, trois formats courts (Mañanitas, Entretiempos, Tapados) et un assemblage revu pour un corps moyen. Le Centrofinos (50 x 130 mm) a été présenté au Festival del Habano de 2018 selon la presse du métier, et annoncé par habanos.com le 25 mars 2019. Habanos décrit la force comme moyenne à corsée ; capes, liants et tripes viennent de la Vuelta Abajo, dans la région de Pinar del Río, et les cigares sont entièrement roulés à la main en tripa larga.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegueros'
