UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('En octubre de 2026, habanos.com clasifica José L. Piedra, con Quintero y Vegueros, entre las tres marcas llamadas de volumen de su portafolio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('José L. Piedra ocupa un lugar que el resto del portafolio deja vacío: el del cigarro cubano de todos los días, vendido al precio de una cajetilla de cigarrillos, y asumido como tal.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Im Oktober 2026 führt habanos.com José L. Piedra zusammen mit Quintero und Vegueros unter den drei sogenannten Volumenmarken seines Portfolios.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('José L. Piedra besetzt einen Platz, den der Rest des Sortiments leer lässt: den der kubanischen Alltagszigarre, verkauft zum Preis einer Schachtel Zigaretten, und dazu bekennt sie sich.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('2026年10月，habanos.com 把 José L. Piedra 与 Quintero、Vegueros 一起列为其品牌组合中的三个所谓量产品牌。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('何塞·L. 皮埃德拉占据着整个产品序列留空的一个位置：古巴人的日常雪茄，售价相当于一包香烟，而且坦然如此。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('في أكتوبر 2026 تصنّف habanos.com علامة José L. Piedra، مع Quintero وVegueros، ضمن ثلاث علامات تسمّيها علامات الحجم في محفظتها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تشغل «خوسيه ل. بييدرا» موقعاً تتركه بقية المحفظة فارغاً: موقع السيجار الكوبي اليومي، الذي يُباع بثمن علبة سجائر، ويعترف بذلك.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos rattache la marque à la famille Piedra, venue des Asturies dans les années 1880 et installée près de Santa Clara, au cœur de la région de Remedios, où le tabac se cultive depuis le XVIe siècle. Selon habanos.com, les sept formats sont faits de tabacs de Remedios, entièrement à la main en tripe courte (tripa corta). La maison présente une image plus moderne ; le Petit Caballeros l''adopte déjà, en paquet de douze et en présentoir de quinze étuis de trois cigares.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La marque vient de la région de Villa Clara, dans le centre de l''île, et non de la Vuelta Abajo. Ses feuilles sont plus rustiques, son roulage est différent — la tripe est faite de feuilles entières mais l''exécution reste volontairement simple —, et la présentation se limite souvent à des paquets de cinq ou à des boîtes sans habillage.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos links the brand to the Piedra family, who came from Asturias in the 1880s and settled near Santa Clara, in the heart of the Remedios region, where tobacco has been grown since the sixteenth century. According to habanos.com, the seven formats are made of Remedios tobaccos, entirely by hand in short filler (tripa corta). The house presents a more modern image; the Petit Caballeros already adopts it, in a pack of twelve and in a display of fifteen sleeves of three cigars.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The brand comes from the Villa Clara region, in the centre of the island, and not from the Vuelta Abajo. Its leaves are more rustic, its rolling different — the filler is made of whole leaves but the execution stays deliberately simple — and the presentation often amounts to packs of five or boxes without dressing.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos vincula la marca con la familia Piedra, llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, en el corazón de la región de Remedios, donde el tabaco se cultiva desde el siglo XVI. Según habanos.com, los siete formatos están hechos con tabacos de Remedios, enteramente a mano en tripa corta. La casa presenta una imagen más moderna; el Petit Caballeros ya la adopta, en paquete de doce y en expositor de quince estuches de tres puros.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La marca viene de la región de Villa Clara, en el centro de la isla, y no de la Vuelta Abajo. Sus hojas son más rústicas, su liado distinto — la tripa se hace de hojas enteras pero la ejecución sigue siendo deliberadamente simple — y la presentación se limita a menudo a paquetes de cinco o a cajas sin adorno.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos verbindet die Marke mit der Familie Piedra, die in den 1880er Jahren aus Asturien kam und sich bei Santa Clara niederließ, im Herzen der Region Remedios, wo seit dem 16. Jahrhundert Tabak angebaut wird. Laut habanos.com bestehen die sieben Formate aus Remedios-Tabaken, vollständig von Hand gerollt, mit kurzer Einlage (tripa corta). Das Haus zeigt ein moderneres Bild; das Petit Caballeros übernimmt es bereits, in einer Packung zu zwölf und in einem Aufsteller mit fünfzehn Etuis zu je drei Zigarren.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Marke stammt aus der Region Villa Clara im Zentrum der Insel und nicht aus der Vuelta Abajo. Ihre Blätter sind rustikaler, ihre Rollart anders — die Einlage besteht aus ganzen Blättern, doch die Ausführung bleibt bewusst einfach —, und die Aufmachung beschränkt sich oft auf Fünferpackungen oder Kisten ohne Ausstattung.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos 把该品牌与皮耶德拉家族联系起来：该家族1880年代从阿斯图里亚斯而来，定居在圣克拉拉附近，位于雷梅迪奥斯地区的中心，那里自十六世纪起种植烟草。据 habanos.com，七个尺寸均以雷梅迪奥斯烟叶制成，全部手工卷制，采用短茄芯（tripa corta）。品牌方展示出更现代的形象；Petit Caballeros 已采用这一形象，为十二支一包，以及陈列架上十五个三支装的小盒。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('这个品牌来自岛屿中部的比亚克拉拉地区，而不是阿巴霍谷。它的烟叶更粗犷，卷法也不同——茄芯用的是整叶，但工序刻意保持简单——包装往往只是五支一包，或是不加装饰的盒子。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تربط Habanos العلامة بعائلة بييدرا، التي جاءت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، في قلب منطقة ريميديوس، حيث يُزرع التبغ منذ القرن السادس عشر. بحسب habanos.com، المقاسات السبعة مصنوعة من تبغ ريميديوس، ملفوفة يدويًا بالكامل بحشوة قصيرة (tripa corta). وتقدّم الدار صورة أحدث؛ ويعتمدها Petit Caballeros بالفعل، في عبوة من اثنتي عشرة قطعة وفي حامل عرض من خمسة عشر علبة صغيرة من ثلاث سيجارات.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('تأتي العلامة من منطقة ڤيّا كلارا، وسط الجزيرة، لا من ڤويلتا أباخو. أوراقها أخشن، ولفّها مختلف — الحشوة من أوراق كاملة لكن التنفيذ يبقى بسيطاً عن قصد — ويقتصر العرض غالباً على عبوات من خمس قطع أو صناديق بلا زينة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos donne la force comme moyenne à corsée.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Le profil s''en ressent, et c''est là tout l''intérêt : terreux, franc, un peu sauvage, avec une force médium qui ne cherche aucune finesse. Ceux qui l''aiment y trouvent une authenticité que les grands assemblages, très travaillés, ont perdue ; ceux qui ne l''aiment pas lui reprochent exactement la même chose.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos gives the strength as medium to full.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The profile shows it, and that is the whole point: earthy, frank, a little wild, with a medium strength that seeks no finesse. Those who love it find an authenticity that the great, highly worked blends have lost; those who do not love it reproach it for exactly the same thing.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos da la fuerza como media a fuerte.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('El perfil lo refleja, y ahí está todo el interés: terroso, franco, un poco salvaje, con una fuerza media que no busca ninguna finura. Quienes lo aman encuentran en él una autenticidad que las grandes ligas, muy trabajadas, han perdido; quienes no lo aman le reprochan exactamente lo mismo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos gibt die Stärke als mittel bis kräftig an.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Das Profil zeigt es, und darin liegt der ganze Reiz: erdig, offen, ein wenig wild, mit mittlerer Kraft, die keine Finesse sucht. Wer sie liebt, findet eine Echtheit, die den großen, stark bearbeiteten Blends abhandengekommen ist; wer sie nicht liebt, wirft ihr genau dasselbe vor.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
