UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('风格也随之而来，而这正是关键所在：带土味、直率、有点野，中等力度，不追求任何细腻。喜欢它的人在其中找到了那些精雕细琢的大配方已经失去的真实；不喜欢它的人，指责的恰恰是同一件事。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
