UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('ويظهر ذلك في الطابع، وفيه تكمن الفائدة كلّها: ترابي، صريح، متوحّش قليلاً، بقوّة متوسطة لا تبحث عن أي رهافة. من يحبّونه يجدون فيه أصالةً فقدتها الخلطات الكبرى شديدة الصنعة؛ ومن لا يحبّونه يعيبون عليه الشيء نفسه تماماً.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Des détaillants datent la marque des années 1880, la disent retirée au début des années 1990 puis relancée en 1996 (Puroexpress, Cigar Keep) ; habanos.com ne donne aucune de ces dates.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
