UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Minoristas fechan la marca en los años 1880, la dicen retirada a comienzos de los años 1990 y luego relanzada en 1996 (Puroexpress, Cigar Keep); habanos.com no da ninguna de estas fechas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
