UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos.com ne nomme aucune fabrique pour la marque ; un détaillant (Puroexpress) place la production à Santa Clara. En octobre 2026, habanos.com range José L. Piedra, Quintero et Vegueros parmi les trois marques de volume de ses vingt-sept marques ; la presse du métier annonçait ce groupe le 1er août 2019, pour un portefeuille alors de vingt et une marques. La page officielle dit la famille Piedra arrivée des Asturies dans les années 1880 et installée près de Santa Clara, et la marque fondée par la deuxième génération, José Lamadrid Piedra. Toute la gamme est en tripe courte roulée main, avec le seul tabac de Remedios.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est une fabrique provinciale de Holguín, dans l''est de l''île — loin de la Vuelta Abajo, dont elle n''utilise pas le tabac. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle dit la famille Piedra arrivée des Asturies dans les années 1880 et installée près de Santa Clara, et la marque fondée par la deuxième génération, José Lamadrid Piedra. Toute la gamme est en tripe courte roulée main, avec le seul tabac de Remedios.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos.com names no factory for the brand; a retailer (Puroexpress) places production in Santa Clara. In October 2026, habanos.com lists José L. Piedra, Quintero and Vegueros among the three volume brands of its twenty-seven brands; the trade press announced this group on 1 August 2019, for a portfolio then of twenty-one brands. The official page has the Piedra family arriving from Asturias in the 1880s and settling near Santa Clara, and the brand founded by the second generation, José Lamadrid Piedra. The whole range is hand-rolled short filler, with Remedios tobacco only.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is a provincial factory in Holguín, in the east of the island — far from the Vuelta Abajo, whose tobacco it does not use. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page has the Piedra family arriving from Asturias in the 1880s and settling near Santa Clara, and the brand founded by the second generation, José Lamadrid Piedra. The whole range is hand-rolled short filler, with Remedios tobacco only.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos.com no nombra ninguna fábrica para la marca; un minorista (Puroexpress) sitúa la producción en Santa Clara. En octubre de 2026, habanos.com clasifica José L. Piedra, Quintero y Vegueros entre las tres marcas de volumen de sus veintisiete marcas; la prensa del oficio anunciaba este grupo el 1 de agosto de 2019, para un portafolio entonces de veintiuna marcas. La página oficial dice la familia Piedra llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, y la marca fundada por la segunda generación, José Lamadrid Piedra. Toda la gama es tripa corta liada a mano, solo con tabaco de Remedios.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es una fábrica provincial de Holguín, en el este de la isla — lejos de la Vuelta Abajo, cuyo tabaco no usa. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial dice la familia Piedra llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, y la marca fundada por la segunda generación, José Lamadrid Piedra. Toda la gama es tripa corta liada a mano, solo con tabaco de Remedios.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos.com nennt für die Marke keine Fabrik; ein Händler (Puroexpress) verortet die Produktion in Santa Clara. Im Oktober 2026 führt habanos.com José L. Piedra, Quintero und Vegueros unter den drei Volumenmarken seiner siebenundzwanzig Marken; die Fachpresse kündigte diese Gruppe am 1. August 2019 an, bei einem Portfolio von damals einundzwanzig Marken. Die offizielle Seite lässt die Familie Piedra in den 1880er Jahren aus Asturien kommen und sich bei Santa Clara niederlassen, die Marke gegründet von der zweiten Generation, José Lamadrid Piedra. Die ganze Palette ist handgerollter Shortfiller, allein mit Remedios-Tabak.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist eine Provinzfabrik in Holguín im Osten der Insel — fern der Vuelta Abajo, deren Tabak sie nicht verwendet. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite lässt die Familie Piedra in den 1880er Jahren aus Asturien kommen und sich bei Santa Clara niederlassen, die Marke gegründet von der zweiten Generation, José Lamadrid Piedra. Die ganze Palette ist handgerollter Shortfiller, allein mit Remedios-Tabak.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。habanos.com 没有为该品牌点出任何工厂；一家零售商（Puroexpress）把生产定在圣克拉拉。2026年10月，habanos.com 把 José L. Piedra、Quintero 与 Vegueros 列为其二十七个品牌中的三个量产品牌；行业媒体于2019年8月1日宣布了这一组合，当时的品牌组合为二十一个品牌。官方页面说皮耶德拉家族1880年代从阿斯图里亚斯来到古巴，定居在圣克拉拉附近，品牌由第二代何塞·拉马德里德·皮耶德拉创立。全系列为手工短茄芯，只用雷梅迪奥斯烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是岛东部奥尔金的一家省属工厂——远离下维尔塔，也不用那里的烟叶。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面说皮耶德拉家族1880年代从阿斯图里亚斯来到古巴，定居在圣克拉拉附近，品牌由第二代何塞·拉马德里德·皮耶德拉创立。全系列为手工短茄芯，只用雷梅迪奥斯烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي habanos.com أي مصنع للعلامة؛ ويضع أحد تجّار التجزئة (Puroexpress) الإنتاج في سانتا كلارا. في أكتوبر 2026 تصنّف habanos.com علامات José L. Piedra وQuintero وVegueros ضمن علامات الحجم الثلاث من علاماتها السبع والعشرين؛ وأعلنت الصحافة المتخصّصة هذه المجموعة في 1 أغسطس 2019، لمحفظة كانت حينها من إحدى وعشرين علامة. تقول الصفحة الرسمية إنّ عائلة بييدرا وصلت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، وإنّ العلامة أسّسها الجيل الثاني، خوسيه لامادريد بييدرا. والمجموعة كلّها حشوة قصيرة ملفوفة يدويًّا بتبغ ريميديوس وحده.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'José L. Piedra'
UNION ALL SELECT 'José L. Piedra', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ مصنع إقليمي في هولغين شرق الجزيرة — بعيدًا عن فويلتا أباخو التي لا تستعمل تبغها. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. تقول الصفحة الرسمية إنّ عائلة بييدرا وصلت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، وإنّ العلامة أسّسها الجيل الثاني، خوسيه لامادريد بييدرا. والمجموعة كلّها حشوة قصيرة ملفوفة يدويًّا بتبغ ريميديوس وحده.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'José L. Piedra'
