UNION ALL SELECT 'Quintero', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Habanos ne nomme aucune fabrique mère pour Quintero ; marque née à Cienfuegos (habanos.com) ; tripe courte, totalmente a mano, tabac de Vuelta Abajo' AS BINARY)) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Quintero est l''une des rares marques de Habanos qui ne soient pas nées à La Havane. Son fondateur, Agustín Quintero, s''est installé à Cienfuegos, la perle du Sud, dit habanos.com, qui ne date pas la marque. Selon Wikipédia, elle naît en 1924 sous le nom de Quintero y Hermanos, quand Agustín et quatre frères ouvrent une petite fabrique à Cienfuegos ; un détaillant britannique donne aussi 1924, avec un « believed ».' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Quintero est le secret le mieux gardé du portefeuille Habanos. Fondée en 1924 à Cienfuegos par Agustín Quintero Benítez, la manufacture produisit pendant des décennies des cigares destinés presque exclusivement au marché espagnol — pays qui noua avec Quintero une relation de fidélité comparable à celle des Britanniques avec Romeo y Julieta.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Quintero is one of the few Habanos brands not born in Havana. Its founder, Agustín Quintero, settled in Cienfuegos, the pearl of the South, says habanos.com, which does not date the brand. According to Wikipedia, it began in 1924 as Quintero y Hermanos, when Agustín and four brothers opened a small factory in Cienfuegos; a British retailer also gives 1924, with a “believed”.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Quintero is the best-kept secret of the Habanos portfolio. Founded in 1924 in Cienfuegos by Agustín Quintero Benítez, the manufacture produced for decades cigars destined almost exclusively for the Spanish market — a country that developed with Quintero a relationship of fidelity comparable to the British relationship with Romeo y Julieta.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Quintero es una de las pocas marcas de Habanos que no nacieron en La Habana. Su fundador, Agustín Quintero, se instaló en Cienfuegos, la perla del Sur, dice habanos.com, que no fecha la marca. Según Wikipedia, nace en 1924 con el nombre de Quintero y Hermanos, cuando Agustín y cuatro hermanos abren una pequeña fábrica en Cienfuegos; un minorista británico da también 1924, con un «believed».' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Quintero es el secreto mejor guardado del catálogo de Habanos. Fundada en 1924 en Cienfuegos por Agustín Quintero Benítez, la manufactura produjo durante décadas puros destinados casi en exclusiva al mercado español, país que trabó con Quintero una relación de fidelidad comparable a la de los británicos con Romeo y Julieta.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Quintero ist eine der wenigen Habanos-Marken, die nicht in Havanna entstanden sind. Ihr Gründer Agustín Quintero ließ sich in Cienfuegos nieder, der Perle des Südens, sagt habanos.com, das die Marke nicht datiert. Laut Wikipedia entsteht sie 1924 unter dem Namen Quintero y Hermanos, als Agustín und vier Brüder in Cienfuegos eine kleine Fabrik eröffnen; ein britischer Händler nennt ebenfalls 1924, mit einem „believed“.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Quintero ist das bestgehütete Geheimnis des Habanos-Portfolios. 1924 in Cienfuegos von Agustín Quintero Benítez gegründet, stellte die Manufaktur jahrzehntelang Zigarren her, die fast ausschließlich für den spanischen Markt bestimmt waren — ein Land, das zu Quintero eine Treuebeziehung entwickelte, vergleichbar mit jener der Briten zu Romeo y Julieta.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Quintero 是 Habanos 少数并非诞生于哈瓦那的品牌之一。据 habanos.com 说，其创始人 Agustín Quintero 在南方的明珠 Cienfuegos 定居，该网站没有给品牌标注年份。据维基百科，它于1924年以 Quintero y Hermanos 之名诞生，当时 Agustín 与四位兄弟在 Cienfuegos 开了一家小工厂；一家英国零售商也给出1924年，并附有“believed”（据信）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Quintero 是 Habanos 旗下守得最严的秘密。1924 年由 Agustín Quintero Benítez 在 Cienfuegos 创立，这家工厂数十年间生产的雪茄几乎全部销往西班牙——西班牙与 Quintero 结下的忠诚，堪比英国人之于 Romeo y Julieta。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Quintero من العلامات القليلة في Habanos التي لم تولد في هافانا. استقرّ مؤسسها Agustín Quintero في Cienfuegos، لؤلؤة الجنوب، بحسب habanos.com الذي لا يؤرّخ العلامة. وبحسب ويكيبيديا، وُلدت عام 1924 باسم Quintero y Hermanos، حين افتتح Agustín وأربعة إخوة مصنعًا صغيرًا في Cienfuegos؛ ويذكر تاجر تجزئة بريطاني 1924 أيضًا، مع عبارة «believed».' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Quintero هي السرّ الأشدّ حفظاً في محفظة Habanos. تأسّست عام 1924 في Cienfuegos على يد Agustín Quintero Benítez، وظلّ المصنع عقوداً ينتج سيجاراً موجّهاً شبه حصرياً إلى السوق الإسبانية — وهي بلد نسج مع Quintero علاقة وفاء تشبه علاقة البريطانيين بـ Romeo y Julieta.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Côté tabac, habanos.com écrit que tout le mélange de la marque vient de la zone de Vuelta Abajo, que la force est moyenne et que les cigares sont roulés totalement à la main, en tripe courte. Un reportage de la presse du métier (avril 2012) donne pour la cape les zones de Vuelta Abajo et de Semi Vuelta, à Pinar del Río, et un détaillant britannique cite les mêmes deux zones. La maison présente la marque comme une voie d''accès à la saveur du Habano, en force moyenne et à prix abordable.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''originalité de Quintero tient à sa provenance régionale. Contrairement aux grandes marques havanaises qui s''approvisionnent exclusivement en Vuelta Abajo occidental, Quintero utilisait historiquement des tabacs de Vuelta Arriba — les provinces orientales de Cuba — plus légères, plus herbacées, avec une signature aromatique distinctement différente du terroir occidental. Cette particularité créa un profil unique : cubain indéniablement, mais avec une légèreté et une herbosité que les amateurs de Partagás trouvaient déconcertantes, et que les amateurs de Quintero trouvaient irremplaçables.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('As for the tobacco, habanos.com writes that the whole blend of the brand comes from the Vuelta Abajo zone, that the strength is medium and that the cigars are entirely hand-rolled, with short filler. A trade-press report (April 2012) gives the Vuelta Abajo and Semi Vuelta zones, in Pinar del Río, for the wrapper, and a British retailer names the same two zones. The house presents the brand as a way into the flavour of the Habano, at medium strength and an affordable price.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Quintero''s originality lies in its regional provenance. Unlike the great Havana brands that source exclusively from western Vuelta Abajo, Quintero historically used tobaccos from Vuelta Arriba — the eastern provinces of Cuba — lighter, more herbaceous, with an aromatic signature distinctly different from the western terroir. This particularity created a unique profile: unmistakably Cuban, but with a lightness and herbaceousness that Partagás fans found disconcerting, and that Quintero enthusiasts found irreplaceable.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('En cuanto al tabaco, habanos.com escribe que toda la liga de la marca procede de la zona de Vuelta Abajo, que la fuerza es media y que los puros se lían totalmente a mano, con tripa corta. Un reportaje de la prensa del oficio (abril de 2012) da para la capa las zonas de Vuelta Abajo y de Semi Vuelta, en Pinar del Río, y un minorista británico cita las mismas dos zonas. La casa presenta la marca como una vía de acceso al sabor del Habano, de fuerza media y a precio asequible.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La originalidad de Quintero está en su procedencia regional. A diferencia de las grandes marcas habaneras, que se abastecen en exclusiva en la Vuelta Abajo occidental, Quintero empleaba históricamente tabacos de la Vuelta Arriba —las provincias orientales de Cuba—, más ligeros, más herbáceos, con una firma aromática claramente distinta del terruño occidental. Esa particularidad creó un perfil único: cubano sin discusión, pero con una ligereza y un carácter herbáceo que a los aficionados a Partagás desconcertaban y que a los de Quintero les resultaban insustituibles.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Zum Tabak schreibt habanos.com, die gesamte Mischung der Marke stamme aus der Zone Vuelta Abajo, die Stärke sei mittel und die Zigarren würden vollständig von Hand gerollt, mit kurzer Einlage. Eine Reportage der Fachpresse (April 2012) nennt für das Deckblatt die Zonen Vuelta Abajo und Semi Vuelta in Pinar del Río, und ein britischer Händler nennt dieselben beiden Zonen. Das Haus präsentiert die Marke als Einstieg in den Geschmack des Habano, in mittlerer Stärke und zu erschwinglichem Preis.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Quinteros Eigenart liegt in ihrer regionalen Herkunft. Anders als die großen Havanna-Marken, die sich ausschließlich in der westlichen Vuelta Abajo eindecken, verwendete Quintero traditionell Tabake aus der Vuelta Arriba — den östlichen Provinzen Kubas —, leichter, krautiger, mit einer Aromatik, die sich deutlich vom westlichen Terroir unterscheidet. Daraus entstand ein einzigartiges Profil: unbestreitbar kubanisch, doch mit einer Leichtigkeit und Krautigkeit, die Partagás-Liebhaber befremdlich und Quintero-Liebhaber unersetzlich fanden.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('烟叶方面，habanos.com 写道，该品牌的全部配方来自 Vuelta Abajo 产区，力度为中等，雪茄全部手工卷制，使用短茄芯。行业媒体的一篇报道（2012年4月）给出的茄衣产区是 Pinar del Río 的 Vuelta Abajo 与 Semi Vuelta，一家英国零售商也列出同样这两个产区。品牌方把这个品牌介绍为通向 Habano 风味的入门之路，力度中等，价格亲民。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Quintero 的独特之处在于其烟叶的产区来源。哈瓦那各大品牌一概只取西部 Vuelta Abajo 的烟叶，Quintero 历来却使用 Vuelta Arriba——古巴东部各省——的烟叶：更轻盈、更草本，香气签名与西部风土截然不同。由此形成了独一无二的风格：无可置疑的古巴味，却带着一种轻盈与草本气，让 Partagás 的拥趸感到不解，也让 Quintero 的拥趸觉得无可替代。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('من جهة التبغ، تكتب habanos.com إنّ خلطة العلامة كلّها من منطقة Vuelta Abajo، وإنّ القوة متوسطة، وإنّ السيجار يُلفّ كلّه يدويًّا بحشوة قصيرة. ويذكر تقرير للصحافة المتخصّصة (أبريل 2012) لغلاف السيجار منطقتي Vuelta Abajo وSemi Vuelta في Pinar del Río، ويذكر تاجر تجزئة بريطاني المنطقتين نفسيهما. وتقدّم الدار العلامة بوصفها مدخلاً إلى نكهة الـ Habano، بقوة متوسطة وسعر في المتناول.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('تنبع خصوصية Quintero من منشأ تبغها الإقليمي. فخلافاً لكبريات علامات هافانا التي تتزوّد حصراً من Vuelta Abajo الغربية، درجت Quintero تاريخياً على استخدام تبغ Vuelta Arriba — أي المقاطعات الشرقية من كوبا — وهو أخفّ وأكثر عشبية، ببصمة عطرية تختلف بوضوح عن الأرض الغربية. وقد أنشأ ذلك طابعاً فريداً: كوبياً بلا جدال، لكن بخفّة ونفَس عشبي كان هواة Partagás يجدونهما محيّرين، وهواة Quintero يجدونهما بلا بديل.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Selon Wikipédia, la marque devint surtout un cigare de machine après la nationalisation du début des années 1960, et Habanos S.A. abandonna en 2002 les cigares de machine au profit de versions faites main ; un détaillant britannique écrit pourtant que la gamme compte encore des formats faits à la machine ou finis à la main, alors que la page de la maison les dit tous roulés totalement à la main : les versions divergent. Un détaillant britannique la dit grande marque d''exportation dans les années 1940, particulièrement appréciée sur le marché espagnol, et toujours populaire auprès des amateurs espagnols.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Après la nationalisation, Quintero rejoignit Habanos S.A. mais conserva sa distribution prioritaire vers l''Espagne. La marque reste pratiquement inconnue hors de la péninsule ibérique et des cercles de connaisseurs très informés — une situation qui convient parfaitement aux aficionados qui la découvrent et réalisent qu''ils ont accès à des cigares cubains exceptionnels à des prix dérisoires par rapport à leur qualité réelle.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('According to Wikipedia, the brand became mainly a machine-made cigar after the nationalisation of the early 1960s, and Habanos S.A. abandoned machine-made cigars in 2002 in favour of hand-made versions; a British retailer nevertheless writes that the range still includes sizes that are machine-made or hand-finished, whereas the house''s page says they are all entirely hand-rolled: the accounts diverge. A British retailer calls it a major export brand in the 1940s, particularly appreciated in the Spanish market, and still popular with Spanish enthusiasts.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('After nationalization, Quintero joined Habanos S.A. but retained its priority distribution to Spain. The brand remains virtually unknown outside the Iberian Peninsula and the circles of very well-informed connoisseurs — a situation that perfectly suits the aficionados who discover it and realize they have access to exceptional Cuban cigars at prices absurdly low relative to their actual quality.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Según Wikipedia, la marca se convirtió sobre todo en un puro de máquina tras la nacionalización de principios de los años sesenta, y Habanos S.A. abandonó en 2002 los puros de máquina en favor de versiones hechas a mano; un minorista británico escribe sin embargo que la gama aún cuenta con formatos hechos a máquina o rematados a mano, mientras que la página de la casa los dice todos liados totalmente a mano: las versiones divergen. Un minorista británico la dice gran marca de exportación en los años cuarenta, especialmente apreciada en el mercado español, y todavía popular entre los aficionados españoles.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Tras la nacionalización, Quintero pasó a Habanos S.A. pero conservó su distribución prioritaria hacia España. La marca sigue siendo prácticamente desconocida fuera de la península ibérica y de los círculos de entendidos muy informados, una situación que conviene de maravilla a los aficionados que la descubren y comprenden que tienen acceso a puros cubanos excepcionales a precios irrisorios frente a su calidad real.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Laut Wikipedia wurde die Marke nach der Verstaatlichung zu Beginn der 1960er Jahre vor allem eine Maschinenzigarre, und Habanos S.A. gab 2002 die Maschinenzigarren zugunsten handgefertigter Versionen auf; ein britischer Händler schreibt dennoch, das Sortiment umfasse noch maschinengefertigte oder handveredelte Formate, während die Seite des Hauses sie alle als vollständig handgerollt bezeichnet: Die Darstellungen weichen voneinander ab. Ein britischer Händler nennt sie eine große Exportmarke der 1940er Jahre, besonders geschätzt auf dem spanischen Markt und bei spanischen Liebhabern noch immer beliebt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Nach der Verstaatlichung kam Quintero zu Habanos S.A., behielt aber den Vorrang der spanischen Distribution. Die Marke ist außerhalb der Iberischen Halbinsel und sehr gut unterrichteter Kennerkreise praktisch unbekannt — ein Zustand, der jenen Aficionados bestens gefällt, die sie entdecken und merken, dass ihnen außergewöhnliche kubanische Zigarren zu Preisen offenstehen, die zu ihrer tatsächlichen Güte in keinem Verhältnis stehen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('据维基百科，该品牌在1960年代初国有化之后主要成了机制雪茄，Habanos S.A. 于2002年放弃机制雪茄，改为手工版本；然而一家英国零售商写道，产品线中仍有机制或手工收尾的规格，而品牌方的页面却称它们全部为完全手工卷制：说法不一。一家英国零售商称它在1940年代是重要的出口品牌，在西班牙市场尤其受欢迎，至今仍受西班牙爱好者喜爱。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('国有化之后，Quintero 归入 Habanos S.A.，但保留了优先供应西班牙的渠道。在伊比利亚半岛与消息极为灵通的行家圈之外，这个品牌几乎无人知晓——而这种状况恰好合了那些发现它的爱好者的心意：他们由此得以用与实际品质完全不相称的低廉价格，享用出色的古巴雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('بحسب ويكيبيديا، صارت العلامة في الغالب سيجار آلة بعد التأميم في مطلع الستينيات، وتخلّت Habanos S.A. عام 2002 عن سيجار الآلة لصالح نسخ مصنوعة يدويًّا؛ ومع ذلك يكتب تاجر تجزئة بريطاني إنّ التشكيلة ما زالت تضمّ مقاسات مصنوعة بالآلة أو مشطّبة يدويًّا، في حين تقول صفحة الدار إنّها كلّها ملفوفة يدويًّا بالكامل: الروايات متباينة. ويصفها تاجر تجزئة بريطاني بأنها علامة تصدير كبيرة في الأربعينيات، محبوبة خصوصًا في السوق الإسبانية، وما زالت رائجة لدى الهواة الإسبان.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('بعد التأميم انضمّت Quintero إلى Habanos S.A. لكنها احتفظت بأولوية التوزيع نحو إسبانيا. وتظل العلامة شبه مجهولة خارج شبه الجزيرة الإيبيرية ودوائر العارفين المطّلعين جداً — وهو وضع يناسب تماماً الهواة الذين يكتشفونها فيدركون أن بين أيديهم سيجاراً كوبياً استثنائياً بأسعار زهيدة قياساً بجودته الحقيقية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Le Favoritos, cinquième format de la gamme, date de 2012 : 4 1/2 pouces (environ 114 mm) sur cepo 50, appelé Concha No. 2 en fabrique, de force moyenne, vendu en paquets de cinq. Des détaillants britanniques listent aussi les formats Petit Quintero, Panetelas et Tubulares, sans cotes lues.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
