UNION ALL SELECT 'Quintero', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El Favoritos, quinto formato de la gama, data de 2012: 4 1/2 pulgadas (unos 114 mm) sobre cepo 50, llamado Concha No. 2 en fábrica, de fuerza media, vendido en paquetes de cinco. Minoristas británicos listan también los formatos Petit Quintero, Panetelas y Tubulares, sin cotas leídas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
