UNION ALL SELECT 'Quintero', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme pas la fabrique mère de Quintero. La marque est née à Cienfuegos (habanos.com) ; Wikipédia place une plus grande fabrique de roulage à La Havane dans les années 1940 ; la fabrique actuelle reste ouverte. En octobre 2026, habanos.com la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros ; la presse du métier annonçait ce classement le 1er août 2019, pour des cigares vendus à des prix plus abordables. La page officielle ne date pas la marque — 1924 vient de l''usage — mais la dit née hors de La Havane, à Cienfuegos, la perle du Sud, et toute roulée à la main en tripe courte, avec du tabac de Vuelta Abajo.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est celle de Cienfuegos, ouverte vers 1925, là où la marque est née — l''une des rares du portefeuille qui ne soit pas havanaise. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle ne date pas la marque — 1924 vient de l''usage — mais la dit née hors de La Havane, à Cienfuegos, la perle du Sud, et toute roulée à la main en tripe courte, avec du tabac de Vuelta Abajo.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos does not name Quintero''s mother factory. The brand was born in Cienfuegos (habanos.com); Wikipedia places a larger rolling factory in Havana in the 1940s; the present factory remains open. In October 2026, habanos.com places it among its three volume brands — José L. Piedra, Quintero, Vegueros; the trade press announced this classification on 1 August 2019, for cigars sold at more affordable prices. The official page does not date the brand — 1924 comes from usage — but says it was born outside Havana, in Cienfuegos, the pearl of the South, and is all hand-rolled short filler, with Vuelta Abajo tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is the Cienfuegos factory, opened around 1925, where the brand was born — one of the few in the portfolio that is not from Havana. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page does not date the brand — 1924 comes from usage — but says it was born outside Havana, in Cienfuegos, the pearl of the South, and is all hand-rolled short filler, with Vuelta Abajo tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra la fábrica madre de Quintero. La marca nació en Cienfuegos (habanos.com); Wikipedia sitúa una fábrica de liado mayor en La Habana en los años cuarenta; la fábrica actual sigue abierta. En octubre de 2026, habanos.com la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros; la prensa del oficio anunciaba esa clasificación el 1 de agosto de 2019, para puros vendidos a precios más asequibles. La página oficial no fecha la marca — 1924 viene del uso — pero la dice nacida fuera de La Habana, en Cienfuegos, la perla del Sur, y toda liada a mano con tripa corta, con tabaco de Vuelta Abajo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es la de Cienfuegos, abierta hacia 1925, donde nació la marca — una de las pocas del portafolio que no es habanera. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial no fecha la marca — 1924 viene del uso — pero la dice nacida fuera de La Habana, en Cienfuegos, la perla del Sur, y toda liada a mano con tripa corta, con tabaco de Vuelta Abajo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt die Mutterfabrik von Quintero nicht. Die Marke entstand in Cienfuegos (habanos.com); Wikipedia verortet in den 1940er Jahren eine größere Rollfabrik in Havanna; die heutige Fabrik bleibt geöffnet. Im Oktober 2026 zählt habanos.com sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros; die Fachpresse kündigte diese Einstufung am 1. August 2019 an, für Zigarren zu erschwinglicheren Preisen. Die offizielle Seite datiert die Marke nicht — 1924 stammt aus dem Gebrauch —, nennt sie aber außerhalb Havannas entstanden, in Cienfuegos, der Perle des Südens, und ganz handgerollten Shortfiller mit Vuelta-Abajo-Tabak.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist die von Cienfuegos, um 1925 eröffnet, wo die Marke entstand — eine der wenigen im Portfolio, die nicht aus Havanna ist. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite datiert die Marke nicht — 1924 stammt aus dem Gebrauch —, nennt sie aber außerhalb Havannas entstanden, in Cienfuegos, der Perle des Südens, und ganz handgerollten Shortfiller mit Vuelta-Abajo-Tabak.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有点名 Quintero 的母厂。品牌诞生于西恩富戈斯（habanos.com）；维基百科把一家规模更大的卷制工厂放在1940年代的哈瓦那；现今的工厂仍在营业。2026年10月，habanos.com 把它列入三个量产品牌——José L. Piedra、Quintero、Vegueros；行业媒体在2019年8月1日预告了这一分类，所涉雪茄的售价更为亲民。官方页面没有给品牌标日期——1924年来自惯例——但说它诞生在哈瓦那之外的西恩富戈斯，南方的明珠，全部为手工短茄芯，用下维尔塔烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是西恩富戈斯厂，约1925年开办，品牌就在那里诞生——是产品组合里少数不属于哈瓦那的品牌之一。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面没有给品牌标日期——1924年来自惯例——但说它诞生在哈瓦那之外的西恩富戈斯，南方的明珠，全部为手工短茄芯，用下维尔塔烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي Habanos المصنع الأمّ لـ Quintero. وُلدت العلامة في سيينفويغوس (habanos.com)؛ وتضع ويكيبيديا مصنع لفّ أوسع في هافانا في الأربعينيات؛ والمصنع الحالي ما زال مفتوحًا. في أكتوبر 2026 تصنّفها habanos.com ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros؛ وكانت الصحافة المتخصّصة قد أعلنت هذا التصنيف في 1 أغسطس 2019، لسيجار يُباع بأسعار أيسر. لا تؤرّخ الصفحة الرسمية العلامة — 1924 من العرف — لكنّها تقول إنّها وُلدت خارج هافانا، في سيينفويغوس لؤلؤة الجنوب، وإنّها كلّها ملفوفة يدويًّا بحشوة قصيرة من تبغ فويلتا أباخو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quintero'
UNION ALL SELECT 'Quintero', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو مصنع سيينفويغوس، المفتوح نحو 1925، حيث وُلدت العلامة — وهي من القلائل في المحفظة التي ليست من هافانا. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. لا تؤرّخ الصفحة الرسمية العلامة — 1924 من العرف — لكنّها تقول إنّها وُلدت خارج هافانا، في سيينفويغوس لؤلؤة الجنوب، وإنّها كلّها ملفوفة يدويًّا بحشوة قصيرة من تبغ فويلتا أباخو.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quintero'
