UNION ALL SELECT 'Diplomáticos', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Habanos ne nomme pas la fabrique ; la presse du métier (2011) cite la fabrique H. Upmann de Belascoaín, Wikipédia la José Martí' AS BINARY)) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Diplomáticos naît en 1966, écrivent la presse du métier (2025) et Wikipédia, comme une alternative moins chère à Montecristo ; Habanos la date seulement des années 1960. Wikipédia lui donne un assemblage un peu plus doux et une cape plus claire pour plaire au consommateur français. Les cinq formats d''origine (n° 1 à 5) reprenaient les cotes des Montecristo n° 1 à 5 ; les n° 6 et 7, ajoutés en 1976 sur les cotes des Montecristo Especial n° 1 et 2, ont été abandonnés au milieu des années 1980.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Diplomáticos est née d''une commande : en 1966, le monopole français du tabac cherchait une marque à son propre usage, moins chère que Montecristo mais bâtie sur le même registre. La Havane lui a fourni exactement cela — une gamme parallèle, aux formats numérotés comme ceux de Montecristo, et à l''assemblage très proche.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Diplomáticos was born in 1966, according to the trade press (2025) and Wikipedia, as a cheaper alternative to Montecristo; Habanos dates it only to the 1960s. Wikipedia gives it a slightly milder blend and a lighter wrapper to please the French consumer. The five original sizes (Nos. 1 to 5) took the dimensions of Montecristo Nos. 1 to 5; Nos. 6 and 7, added in 1976 on the dimensions of Montecristo Especial Nos. 1 and 2, were dropped in the mid-1980s.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Diplomáticos was born of an order: in 1966 the French tobacco monopoly was looking for a brand for its own use, cheaper than Montecristo but built in the same register. Havana supplied exactly that — a parallel range, with formats numbered like Montecristo''s, and a very close blend.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Diplomáticos nace en 1966, escriben la prensa del oficio (2025) y Wikipedia, como una alternativa más barata a Montecristo; Habanos la fecha solo en los años sesenta. Wikipedia le da una liga algo más suave y una capa más clara para agradar al consumidor francés. Los cinco formatos de origen (n.º 1 a 5) reproducían las medidas de los Montecristo n.º 1 a 5; los n.º 6 y 7, añadidos en 1976 sobre las medidas de los Montecristo Especial n.º 1 y 2, se abandonaron a mediados de los años ochenta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Diplomáticos nació de un encargo: en 1966 el monopolio francés del tabaco buscaba una marca para su propio uso, más barata que Montecristo pero construida en el mismo registro. La Habana le proporcionó exactamente eso — una gama paralela, con formatos numerados como los de Montecristo y una liga muy próxima.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Diplomáticos entsteht 1966, schreiben die Fachpresse (2025) und Wikipedia, als günstigere Alternative zu Montecristo; Habanos datiert sie nur auf die 1960er Jahre. Laut Wikipedia hat sie eine etwas mildere Mischung und ein helleres Deckblatt, um dem französischen Verbraucher zu gefallen. Die fünf ursprünglichen Formate (Nr. 1 bis 5) übernahmen die Maße der Montecristo Nr. 1 bis 5; die Nr. 6 und 7, 1976 auf den Maßen der Montecristo Especial Nr. 1 und 2 hinzugefügt, wurden Mitte der 1980er Jahre aufgegeben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Diplomáticos entstand aus einer Bestellung: 1966 suchte das französische Tabakmonopol eine Marke für den eigenen Gebrauch, günstiger als Montecristo, aber im selben Register gebaut. Havanna lieferte genau das — eine Parallelserie mit Formaten, die wie die von Montecristo nummeriert sind, und einem sehr ähnlichen Blend.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Diplomáticos 诞生于1966年，行业媒体（2025）与维基百科都这样写，是作为 Montecristo 的廉价替代品；Habanos 只把它定在1960年代。维基百科称它的配方略温和、茄衣颜色更浅，以迎合法国消费者。原有的五个规格（No. 1至5）沿用 Montecristo No. 1至5 的尺寸；1976年增加的 No. 6 和 No. 7 采用 Montecristo Especial No. 1 和 No. 2 的尺寸，于1980年代中期停产。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('外交官系列诞生于一份订单：1966年，法国烟草专卖机构想要一个供自己使用的品牌，价格低于蒙特克里斯托，却建立在同样的路数之上。哈瓦那提供的正是如此——一条平行产品线，尺寸编号方式与蒙特克里斯托一致，配方也极为接近。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تولد Diplomáticos عام 1966، كما تكتب الصحافة المتخصّصة (2025) وويكيبيديا، بديلاً أرخص من Montecristo؛ ولا تؤرّخها Habanos إلا بالستينيات. وتعطيها ويكيبيديا خلطة ألطف قليلاً وغلافاً أفتح لوناً لإرضاء المستهلك الفرنسي. وكانت المقاسات الخمسة الأصلية (No. 1 إلى 5) تعيد مقاسات Montecristo No. 1 إلى 5؛ أمّا No. 6 وNo. 7، اللذان أُضيفا عام 1976 على مقاسات Montecristo Especial No. 1 وNo. 2، فقد أُسقطا في منتصف الثمانينيات.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('وُلدت «ديبلوماتيكوس» من طلبيّة: ففي 1966 كان احتكار التبغ الفرنسي يبحث عن علامة لاستخدامه الخاص، أرخص من مونتيكريستو لكن مبنيّة على المستوى نفسه. وقدّمت له هافانا ذلك تماماً — تشكيلة موازية، بمقاسات مرقّمة كمقاسات مونتيكريستو، وخلطة شديدة القرب.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La comparaison avec Montecristo fait l''identité de la marque : des formats numérotés comme les siens, à un prix un peu inférieur à celui du format équivalent, dit Wikipédia. La presse du métier écrit qu''elle n''a jamais atteint la réputation de Montecristo.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Ce parallélisme, longtemps tenu pour un secret d''initiés, est devenu l''argument principal de la marque : les amateurs y voient l''occasion d''un profil montecristien à un prix plus doux. La comparaison est un peu injuste — les assemblages ont divergé au fil des décennies — mais elle a fait la réputation de la maison.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The comparison with Montecristo makes the identity of the brand: sizes numbered like its own, at a price a little below that of the equivalent size, says Wikipedia. The trade press writes that it never reached the reputation of Montecristo.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('That parallelism, long treated as an insiders'' secret, has become the brand''s chief argument: enthusiasts see in it the chance of a Montecristo profile at a gentler price. The comparison is a little unfair — the blends have diverged over the decades — but it made the reputation of the house.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La comparación con Montecristo hace la identidad de la marca: formatos numerados como los suyos, a un precio algo inferior al del formato equivalente, dice Wikipedia. La prensa del oficio escribe que nunca alcanzó la reputación de Montecristo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Ese paralelismo, considerado durante mucho tiempo un secreto de iniciados, se ha convertido en el argumento principal de la marca: los aficionados ven en él la ocasión de un perfil montecristiano a un precio más suave. La comparación es algo injusta — las ligas han divergido con las décadas — pero hizo la fama de la casa.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Der Vergleich mit Montecristo prägt die Identität der Marke: wie bei ihr nummerierte Formate zu einem etwas niedrigeren Preis als das entsprechende Format, sagt Wikipedia. Die Fachpresse schreibt, sie habe den Ruf von Montecristo nie erreicht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Diese Parallelität, lange als Insidergeheimnis gehandelt, ist zum Hauptargument der Marke geworden: Liebhaber sehen darin die Gelegenheit zu einem Montecristo-Profil zu sanfterem Preis. Der Vergleich ist etwas unfair — die Blends sind über die Jahrzehnte auseinandergegangen —, doch er hat den Ruf des Hauses begründet.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('与 Montecristo 的比较构成了这个品牌的身份：规格编号方式与其相同，价格比对应规格略低，维基百科如是说。行业媒体写道，它从未达到 Montecristo 的声誉。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('这种平行关系长期被当作内行的秘密，如今却成了这个品牌的主要卖点：爱好者视之为以更温和价格获得蒙特克里斯托风格的机会。这一比较略欠公允——几十年来配方已经分化——但它成就了这家的名声。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تصنع المقارنة بـ Montecristo هوية العلامة: مقاسات مرقّمة مثل مقاساتها، بسعر أدنى قليلاً من سعر المقاس المماثل، كما تقول ويكيبيديا. وتكتب الصحافة المتخصّصة إنّها لم تبلغ قط سمعة Montecristo.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('هذا التوازي، الذي عُدّ طويلاً سرّ العارفين، صار الحجّة الأساسية للعلامة: يرى فيه الهواة فرصةً لطابع مونتيكريستي بسعر ألطف. المقارنة مجحفة قليلاً — إذ تباعدت الخلطات عبر العقود — لكنها صنعت سمعة الدار.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos décrit un Habano de force moyenne à forte, entièrement roulé à la main en tripe longue, avec cape et tripe de la zone de Vuelta Abajo, à Pinar del Río. Wikipédia donne le No. 2, une pirámide, à 6 1/8 pouces sur cepo 52 (156 mm).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Le profil actuel est médium : cacao, café au lait, une pointe de cuir, une régularité de combustion que les fumeurs réguliers apprécient. Le No.2, un Pirámide, en est l''expression la plus recherchée.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos describes a Habano of medium to strong strength, entirely hand-rolled with long filler, with wrapper and filler from the Vuelta Abajo zone, in Pinar del Río. Wikipedia gives the No. 2, a pirámide, at 6 1/8 inches on ring gauge 52 (156 mm).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The present profile is medium: cocoa, café au lait, a touch of leather, an evenness of burn that regular smokers appreciate. The No.2, a Pirámide, is its most sought-after expression.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
