UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme pas de fabrique. Un reportage de la presse du métier (2011) écrit que la fabrique Romeo y Julieta / H. Upmann de Belascoaín a la charge de la marque, mais qu''aucun Diplomáticos n''y était roulé en mai ; Wikipédia la dit faite à la fabrique José Martí, à La Havane. En octobre 2026, habanos.com la range parmi les treize autres marques du portefeuille de vingt-sept, hors des six globales, des cinq de valeur et des trois de volume ; la presse du métier comptait en 2019 vingt et une marques de portefeuille, Diplomáticos dans la catégorie des autres. La page officielle la dit relativement récente, des années 1960, d''une ressemblance marquée avec Montecristo et aux formats désignés par des numéros plutôt que par des noms ; elle ne nomme ni fabrique ni vitola.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est H. Upmann — la José Martí, ainsi nommée depuis 1960 —, qui a changé plusieurs fois d''adresse et occupe depuis 2011 l''ancien bâtiment Romeo y Julieta de Belascoaín, à Centro Habana. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la date des années 1960 et la dit numérotée comme Montecristo, dont elle est née ; elle ne nomme pas sa fabrique, que la presse du métier place chez H. Upmann, comme Montecristo.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos names no factory. A trade-press report (2011) writes that the Romeo y Julieta / H. Upmann factory on Belascoaín is in charge of the brand, but that no Diplomáticos was being rolled there in May; Wikipedia says it is made at the José Martí factory, in Havana. In October 2026 habanos.com places it among the thirteen other brands of the portfolio of twenty-seven, outside the six global brands, the five value brands and the three volume brands; in 2019 the trade press counted twenty-one portfolio brands, Diplomáticos in the category of the others. The official page calls it relatively recent, from the 1960s, strongly resembling Montecristo and with sizes designated by numbers rather than names; it names neither a factory nor a vitola.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is H. Upmann — the José Martí, so named since 1960 —, which has moved several times and has occupied since 2011 the former Romeo y Julieta building on Belascoaín, Centro Habana. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it to the 1960s and says it is numbered like Montecristo, from which it was born; it does not name its factory, which the trade press places at H. Upmann, like Montecristo.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra ninguna fábrica. Un reportaje de la prensa del oficio (2011) escribe que la fábrica Romeo y Julieta / H. Upmann de Belascoaín tiene a su cargo la marca, pero que allí no se liaba ningún Diplomáticos en mayo; Wikipedia la dice hecha en la fábrica José Martí, en La Habana. En octubre de 2026, habanos.com la clasifica entre las otras trece marcas del portafolio de veintisiete, fuera de las seis globales, las cinco de valor y las tres de volumen; la prensa del oficio contaba en 2019 veintiuna marcas de portafolio, con Diplomáticos en la categoría de las otras. La página oficial la dice relativamente reciente, de los años sesenta, de marcado parecido con Montecristo y con formatos designados por números en lugar de nombres; no nombra ni fábrica ni vitola.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es H. Upmann — la José Martí, así llamada desde 1960 —, que cambió varias veces de dirección y ocupa desde 2011 el antiguo edificio Romeo y Julieta de Belascoaín, en Centro Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la fecha en los años sesenta y la dice numerada como Montecristo, de la que nació; no nombra su fábrica, que la prensa del oficio sitúa en H. Upmann, como Montecristo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt keine Fabrik. Eine Reportage der Fachpresse (2011) schreibt, die Fabrik Romeo y Julieta / H. Upmann an der Belascoaín betreue die Marke, doch im Mai sei dort keine Diplomáticos gerollt worden; Wikipedia sagt, sie werde in der Fabrik José Martí in Havanna hergestellt. Im Oktober 2026 zählt habanos.com sie zu den dreizehn übrigen Marken des Portfolios von siebenundzwanzig, außerhalb der sechs globalen, der fünf Wertmarken und der drei Volumenmarken; die Fachpresse zählte 2019 einundzwanzig Portfoliomarken, Diplomáticos in der Kategorie der übrigen. Die offizielle Seite nennt sie relativ jung, aus den 1960er Jahren, mit ausgeprägter Ähnlichkeit zu Montecristo und mit Formaten, die durch Nummern statt durch Namen bezeichnet werden; sie nennt weder Fabrik noch Vitola.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist H. Upmann — die José Martí, so benannt seit 1960 —, die mehrmals umzog und seit 2011 das frühere Romeo-y-Julieta-Gebäude an der Belascoaín in Centro Habana belegt. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie in die 1960er Jahre und nennt sie nummeriert wie Montecristo, aus der sie hervorging; sie nennt ihre Fabrik nicht, die die Fachpresse bei H. Upmann verortet, wie Montecristo.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有点名任何工厂。行业媒体的一篇报道（2011年）写道，贝拉斯科艾因街的 Romeo y Julieta / H. Upmann 厂负责这个品牌，但5月那里并没有卷制任何 Diplomáticos；维基百科说它在哈瓦那的 José Martí 厂制造。2026年10月，habanos.com 把它列入二十七个组合品牌中的其余十三个，不在六个全球品牌、五个价值品牌与三个量产品牌之列；行业媒体2019年统计有二十一个组合品牌，Diplomáticos 在其余品牌一类。官方页面称它相对较新，始于1960年代，与 Montecristo 极为相似，规格以数字而非名称命名；页面既没有点名工厂，也没有点名规格。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是乌普曼——即1960年起得名的 José Martí 厂——几度搬迁，2011年起占用中哈瓦那贝拉斯科艾因街原罗密欧与朱丽叶厂房。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把它定在1960年代，并说它像 Montecristo 一样以数字命名，它正是从后者衍生；页面没有点名工厂，行业媒体把它和 Montecristo 一样放在乌普曼厂。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا تسمّي Habanos أيّ مصنع. ويكتب تقرير للصحافة المتخصّصة (2011) أنّ مصنع Romeo y Julieta / H. Upmann في بيلاسكوين مكلّف بالعلامة، لكن لم يكن يُلفّ فيه أيّ Diplomáticos في مايو؛ وتقول ويكيبيديا إنّها تُصنع في مصنع خوسيه مارتي في هافانا. في أكتوبر 2026 تصنّفها habanos.com ضمن العلامات الثلاث عشرة الأخرى من محفظة السبع والعشرين، خارج العلامات العالمية الست وعلامات القيمة الخمس وعلامات الحجم الثلاث؛ وكانت الصحافة المتخصّصة تحصي عام 2019 إحدى وعشرين علامة في المحفظة، وDiplomáticos في فئة الأخرى. تصفها الصفحة الرسمية بأنها حديثة نسبياً، من الستينيات، شديدة الشبه بـ Montecristo ومقاساتها تُسمّى بأرقام لا بأسماء؛ ولا تسمّي مصنعاً ولا مقاساً.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Diplomáticos'
UNION ALL SELECT 'Diplomáticos', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو H. Upmann — مصنع خوسيه مارتي، بهذا الاسم منذ 1960 — الذي غيّر عنوانه مرارًا ويشغل منذ 2011 مبنى Romeo y Julieta السابق في بيلاسكوين، سنترو هابانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤرّخها الصفحة الرسمية في الستينيات وتقول إنّها مرقّمة مثل Montecristo التي وُلدت منها؛ ولا تسمّي مصنعها، الذي تضعه الصحافة المتخصّصة عند H. Upmann مثل Montecristo.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Diplomáticos'
