UNION ALL SELECT 'Cuaba', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Fabrique mère La Corona (Miguel Fernández Roig), Cerro, selon la presse du métier ; habanos.com dit le style relancé en 1996 à la fabrique Romeo y Julieta ; Wikipédia cite Briones Montoto' AS BINARY)) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Cuaba est une marque de résurrection. Lancée en 1996, elle reprend le double figurado, effilé aux deux extrémités, un style à la mode à la fin du XIXe siècle que habanos.com dit relancé un siècle plus tard, en 1996, à la fabrique Romeo y Julieta. Wikipédia écrit que Habanos la lança le 19 novembre 1996 à Londres, au Claridge''s, et que les figurados, populaires au début du XXe siècle, déclinèrent à partir des années 1950.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cuaba est une marque de résurrection. Lancée en 1996, elle a été créée pour faire revivre une forme abandonnée depuis les années 1940 : le double figurado, effilé aux deux extrémités, que les rouleurs du XIXe siècle produisaient couramment et que la mécanisation du XXe a fait disparaître des catalogues.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Cuaba is a brand of resurrection. Launched in 1996, it takes up the double figurado, tapered at both ends, a style in fashion in the late nineteenth century that habanos.com says was revived a century later, in 1996, at the Romeo y Julieta factory. Wikipedia writes that Habanos launched it on 19 November 1996 in London, at Claridge''s, and that figurados, popular in the early twentieth century, declined from the 1950s.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cuaba is a brand of resurrection. Launched in 1996, it was created to bring back a shape abandoned since the 1940s: the double figurado, tapered at both ends, which nineteenth-century rollers produced routinely and which the mechanisation of the twentieth made disappear from the catalogues.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Cuaba es una marca de resurrección. Lanzada en 1996, retoma el doble figurado, afilado en ambos extremos, un estilo de moda a finales del siglo XIX que habanos.com dice relanzado un siglo después, en 1996, en la fábrica Romeo y Julieta. Wikipedia escribe que Habanos la lanzó el 19 de noviembre de 1996 en Londres, en el Claridge''s, y que los figurados, populares a principios del siglo XX, declinaron a partir de los años cincuenta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cuaba es una marca de resurrección. Lanzada en 1996, fue creada para hacer revivir una forma abandonada desde los años cuarenta: el doble figurado, afilado en ambos extremos, que los torcedores del siglo XIX producían corrientemente y que la mecanización del siglo XX hizo desaparecer de los catálogos.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Cuaba ist eine Marke der Wiederauferstehung. 1996 eingeführt, greift sie das doppelte Figurado auf, an beiden Enden zulaufend, einen Stil, der Ende des 19. Jahrhunderts in Mode war und von dem habanos.com sagt, er sei ein Jahrhundert später, 1996, in der Fabrik Romeo y Julieta wieder aufgelegt worden. Wikipedia schreibt, Habanos habe sie am 19. November 1996 in London im Claridge''s vorgestellt, und die Figurados, Anfang des 20. Jahrhunderts beliebt, seien ab den 1950er Jahren zurückgegangen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cuaba ist eine Marke der Wiederauferstehung. 1996 auf den Markt gebracht, wurde sie geschaffen, um eine seit den 1940er Jahren aufgegebene Form wiederzubeleben: das doppelte Figurado, an beiden Enden zulaufend, das die Roller des 19. Jahrhunderts routinemäßig herstellten und das die Mechanisierung des 20. aus den Katalogen verschwinden ließ.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('库阿巴是一个「复活」的品牌。它于1996年推出，重拾两端渐尖的双头异形茄——这是十九世纪末流行的样式，habanos.com 称其一个世纪后即1996年在 Romeo y Julieta 工厂重新推出。维基百科写道，Habanos 于1996年11月19日在伦敦的 Claridge''s 酒店推出该品牌，而异形茄在二十世纪初流行，自1950年代起衰落。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('库阿巴是一个「复活」的品牌。它于1996年推出，目的是让一种自1940年代起被弃用的形制重生：两端渐尖的双头异形茄——十九世纪的卷制师常做这种形状，而二十世纪的机械化让它从产品目录中消失。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('«كوابا» علامة بَعْث. أُطلقت سنة 1996، وهي تستعيد الفيغورادو المزدوج، المدبّب من طرفيه، وهو طراز كان رائجاً في أواخر القرن التاسع عشر وتقول habanos.com إنه أُعيد إطلاقه بعد قرن، سنة 1996، في مصنع Romeo y Julieta. وتكتب ويكيبيديا أنّ Habanos أطلقتها في 19 نوفمبر 1996 في لندن، في فندق Claridge''s، وأنّ الفيغورادو، الذائعة في مطلع القرن العشرين، تراجعت ابتداءً من خمسينيات القرن الماضي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('«كوابا» علامة بَعْث. أُطلقت سنة 1996 لإحياء شكلٍ مهجور منذ الأربعينيات: «الفيغورادو المزدوج»، المدبّب من طرفيه، الذي كان لافّو القرن التاسع عشر ينتجونه بانتظام وأزالته مكننةُ القرن العشرين من الكتالوغات.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos présente les doubles figurados comme le sommet de l''art du rouleur de cigares. Wikipédia écrit que chaque Cuaba est roulé à la main par des rouleurs de grade 7, le plus haut niveau de certification, et que les premiers, faits sans moule, variaient légèrement de taille, les moules n''arrivant qu''environ un an plus tard. Les tailles d''origine étaient Divinos, Tradicionales, Generosos et Exclusivos ; Distinguido, Diadema et Salomón les ont rejointes au portefeuille régulier en 2003, dit habanos.com.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La forme n''est pas un caprice esthétique. Un cigare effilé aux deux bouts commence étroit, s''élargit, puis se resserre : le volume de fumée et la concentration des arômes changent en continu, ce qu''un format droit ne fait jamais. Elle est aussi beaucoup plus difficile à rouler, ce qui explique qu''elle ait été abandonnée et pourquoi Cuaba est confiée à des torcedores expérimentés.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos presents double figurados as the pinnacle of the cigar roller''s art. Wikipedia writes that every Cuaba is hand-rolled by grade 7 rollers, the highest level of certification, and that the first ones, made without a mould, varied slightly in size, the moulds arriving only about a year later. The original sizes were Divinos, Tradicionales, Generosos and Exclusivos; Distinguido, Diadema and Salomón joined them in the regular portfolio in 2003, says habanos.com.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The shape is not an aesthetic whim. A cigar tapered at both ends begins narrow, widens, then narrows again: the volume of smoke and the concentration of aromas change continuously, which a straight format never does. It is also far harder to roll, which explains why it was abandoned and why Cuaba is entrusted to experienced torcedores.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos presenta los dobles figurados como la cumbre del arte del torcedor de puros. Wikipedia escribe que cada Cuaba se lía a mano por torcedores de grado 7, el nivel más alto de certificación, y que los primeros, hechos sin molde, variaban ligeramente de tamaño, pues los moldes llegaron solo un año después, aproximadamente. Los tamaños de origen eran Divinos, Tradicionales, Generosos y Exclusivos; Distinguido, Diadema y Salomón se les unieron en el portafolio regular en 2003, dice habanos.com.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La forma no es un capricho estético. Un cigarro afilado en los dos extremos empieza estrecho, se ensancha y luego se estrecha: el volumen de humo y la concentración de aromas cambian continuamente, cosa que un formato recto nunca hace. Es además mucho más difícil de liar, lo que explica que se abandonara y por qué Cuaba se confía a torcedores experimentados.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos stellt die doppelten Figurados als Gipfel der Kunst des Zigarrenrollers dar. Wikipedia schreibt, jede Cuaba werde von Rollern der Stufe 7 von Hand gerollt, der höchsten Zertifizierungsstufe, und die ersten, ohne Form hergestellt, hätten in der Größe leicht variiert, da die Formen erst etwa ein Jahr später kamen. Die ursprünglichen Größen waren Divinos, Tradicionales, Generosos und Exclusivos; Distinguido, Diadema und Salomón stießen 2003 zum regulären Portfolio, sagt habanos.com.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Form ist keine ästhetische Laune. Eine an beiden Enden zulaufende Zigarre beginnt schmal, weitet sich und verengt sich wieder: Rauchvolumen und Aromenkonzentration verändern sich fortwährend, was ein gerades Format nie tut. Sie ist zudem weit schwerer zu rollen, was erklärt, warum sie aufgegeben wurde und warum Cuaba erfahrenen Torcedores anvertraut wird.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos 将双头异形茄视为卷制师技艺的巅峰。维基百科写道，每支 Cuaba 都由7级卷制师手工卷制，这是认证的顶级水平；头几批不用模具，尺寸略有差异，模具大约一年后才出现。原始尺寸为 Divinos、Tradicionales、Generosos 和 Exclusivos；Distinguido、Diadema 和 Salomón 于2003年加入常规产品线，habanos.com 如是说。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
