UNION ALL SELECT 'Cuaba', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تقدّم Habanos الفيغورادو المزدوج بوصفه قمّة فنّ لافّ السيجار. وتكتب ويكيبيديا أنّ كلّ Cuaba يلفّه يدوياً لافّون من الدرجة 7، وهي أرفع مستويات الاعتماد، وأنّ الأوائل منها، المصنوعة بلا قالب، كانت تتفاوت قليلاً في الحجم، إذ لم تصل القوالب إلا بعد نحو سنة. وكانت المقاسات الأصلية Divinos وTradicionales وGenerosos وExclusivos؛ وانضمّت إليها Distinguido وDiadema وSalomón إلى المحفظة النظامية سنة 2003، بحسب habanos.com.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('والشكل ليس نزوة جمالية. فالسيجار المدبّب من طرفيه يبدأ ضيّقاً، ثم يتّسع، ثم يضيق مجدّداً: يتغيّر حجم الدخان وتركيز النكهات باستمرار، وهو ما لا يفعله المقاس المستقيم أبداً. كما أنه أصعب لفّاً بكثير، ما يفسّر هجره ويفسّر لماذا تُوكَل «كوابا» إلى لافّين مخضرمين.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
