UNION ALL SELECT 'Cuaba', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('这个名字来自一种古巴灌木，泰诺人用它的树皮生火，而最初到来的西班牙人看到它被用来点燃烟草。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
