UNION ALL SELECT 'Cuaba', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, avenue 20 de Mayo, au Cerro, ancienne fabrique de cigarettes transformée en fabrique de cigares en 2000, dit la presse du métier (2011 et 2015), qui la nomme mère de Cuaba, de Hoyo de Monterrey et de Punch. En octobre 2026, la page The Habanos Brands Academia de habanos.com range Cuaba parmi les treize autres marques d''un portefeuille de 27, hors des six marques globales, des cinq marques de valeur et des trois marques de volume. Habanos écrit que le style de Cuaba a été relancé en 1996 à la fabrique Romeo y Julieta, sans nommer de fabrique mère ; Wikipédia écrit que la plupart des Cuaba sont faits à la fabrique Briones Montoto, celle des Romeo y Julieta, et la presse du métier place la fabrique mère à La Corona : les deux versions s''écrivent. Tout est roulé à la main en tripe longue.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la fait naître en 1996 à la fabrique Romeo y Julieta, qui remit au goût du jour les doubles figurados ; la presse du métier place ensuite sa fabrique mère à La Corona. Tout est roulé à la main en tripe longue.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, on 20 de Mayo Avenue, in Cerro, a former cigarette factory converted into a cigar factory in 2000, says the trade press (2011 and 2015), which names it as mother of Cuaba, Hoyo de Monterrey and Punch. In October 2026, the page The Habanos Brands Academia on habanos.com places Cuaba among the thirteen other brands of a portfolio of 27, outside the six global brands, the five value brands and the three volume brands. Habanos writes that the Cuaba style was revived in 1996 at the Romeo y Julieta factory, without naming a mother factory; Wikipedia writes that most Cuaba are made at the Briones Montoto factory, that of Romeo y Julieta, and the trade press places the mother factory at La Corona: both versions are given. Everything is hand-rolled with long filler.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page has it born in 1996 at the Romeo y Julieta factory, which revived double figurados; the trade press then places its mother factory at La Corona. Everything is hand-rolled with long filler.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, avenida 20 de Mayo, en el Cerro, antigua fábrica de cigarrillos transformada en fábrica de puros en 2000, dice la prensa del oficio (2011 y 2015), que la nombra madre de Cuaba, de Hoyo de Monterrey y de Punch. En octubre de 2026, la página Habanos Brands Academia de habanos.com clasifica Cuaba entre las otras trece marcas de un portafolio de 27, fuera de las seis marcas globales, de las cinco marcas de valor y de las tres marcas de volumen. Habanos escribe que el estilo de Cuaba fue relanzado en 1996 en la fábrica Romeo y Julieta, sin nombrar fábrica madre; Wikipedia escribe que la mayoría de los Cuaba se hacen en la fábrica Briones Montoto, la de Romeo y Julieta, y la prensa del oficio sitúa la fábrica madre en La Corona: se escriben las dos versiones. Todo se lía a mano con tripa larga.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la hace nacer en 1996 en la fábrica Romeo y Julieta, que puso de nuevo de moda los dobles figurados; la prensa del oficio sitúa luego su fábrica madre en La Corona. Todo se lía a mano con tripa larga.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, Avenida 20 de Mayo, im Cerro, eine frühere Zigarettenfabrik, die 2000 zur Zigarrenfabrik umgebaut wurde, sagt die Fachpresse (2011 und 2015), die sie als Mutter von Cuaba, Hoyo de Monterrey und Punch nennt. Im Oktober 2026 reiht die Seite Habanos Brands Academia von habanos.com Cuaba unter die dreizehn übrigen Marken eines Portfolios von 27 ein, außerhalb der sechs globalen Marken, der fünf Wertmarken und der drei Volumenmarken. Habanos schreibt, der Stil von Cuaba sei 1996 in der Fabrik Romeo y Julieta wieder aufgelegt worden, ohne eine Mutterfabrik zu nennen; Wikipedia schreibt, die meisten Cuaba würden in der Fabrik Briones Montoto gefertigt, der von Romeo y Julieta, und die Fachpresse verortet die Mutterfabrik bei La Corona: Beide Versionen werden festgehalten. Alles wird von Hand mit Longfiller gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite lässt sie 1996 in der Fabrik Romeo y Julieta entstehen, die die Doppelfigurados wiederbelebte; die Fachpresse verortet ihre Mutterfabrik dann bei La Corona. Alles wird von Hand mit Longfiller gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。它的母厂是 La Corona——即 Miguel Fernández Roig 厂——位于塞罗区 20 de Mayo 大道，原为卷烟厂，2000年改建为雪茄厂，行业媒体（2011年和2015年）如是说，并称其为 Cuaba、Hoyo de Monterrey 和 Punch 的母厂。2026年10月，habanos.com 的 Habanos Brands Academia 页面把 Cuaba 列入一个27个品牌的组合中的另外十三个品牌，不在六个全球品牌、五个价值品牌和三个销量品牌之内。Habanos 写道，Cuaba 的风格于1996年在 Romeo y Julieta 工厂重新推出，但未点名母厂；维基百科写道，大部分 Cuaba 在 Briones Montoto 工厂制作，即 Romeo y Julieta 的工厂，而行业媒体把母厂定在 La Corona：两种说法并存。全部手工长茄芯。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它1996年诞生于罗密欧与朱丽叶厂，该厂重新推出双头异形雪茄；行业媒体随后把它的母厂定在 La Corona。全部手工长茄芯。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع Miguel Fernández Roig —، في شارع 20 de Mayo بحيّ سيرو، وهو مصنع سجائر سابق تحوّل إلى مصنع سيجار سنة 2000، بحسب الصحافة المتخصّصة (2011 و2015) التي تسمّيه أمّاً لـCuaba وHoyo de Monterrey وPunch. وفي أكتوبر 2026 تصنّف صفحة Habanos Brands Academia في habanos.com علامة Cuaba ضمن العلامات الثلاث عشرة الأخرى في محفظة من 27 علامة، خارج العلامات العالمية الستّ وعلامات القيمة الخمس وعلامات الحجم الثلاث. وتكتب Habanos أنّ أسلوب Cuaba أُعيد إطلاقه سنة 1996 في مصنع Romeo y Julieta دون أن تسمّي مصنعاً أمّاً؛ وتكتب ويكيبيديا أنّ معظم سيجار Cuaba يُصنع في مصنع Briones Montoto، مصنع Romeo y Julieta، وتضع الصحافة المتخصّصة المصنع الأمّ في La Corona: الروايتان مكتوبتان. كلّه ملفوف يدويًّا بحشوة طويلة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تجعلها الصفحة الرسمية تولد سنة 1996 في مصنع Romeo y Julieta الذي أعاد الفيغورادو المزدوج إلى الرواج؛ ثمّ تضع الصحافة المتخصّصة مصنعها الأمّ في La Corona. كلّه ملفوف يدويًّا بحشوة طويلة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
