UNION ALL SELECT 'Cuaba', 'ar', 'pairings 1', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`pairings_ar`, '$[1].notes')) AS BINARY) = CAST('اقتراح مرافقة بلا صفحة خلفه، لفيغورادو مزدوج من العلامة.' AS BINARY)) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'ar', 'pairings (nombre)', (JSON_LENGTH(`pairings_ar`) = 2) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'source (citation retirée)', (LOCATE(CAST('cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de Cuaba) ; ' AS BINARY), CAST(`source` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'Cuaba', 'fr', 'source', (LOCATE(CAST('habanos.com « Cuaba Brand » (https://www.habanos.com/en/the-' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cuaba'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Non nommée par habanos.com. Presse : Romeo y Julieta (Belascoaín 852), puis Carlos Baliño (Marianao, Origin of Cigar) ; versions divergentes' AS BINARY)) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Le nom signifie le roi du monde. Wikipédia et Origin of Cigar écrivent que la marque aurait été créée en 1848 par l''Allemand Emilio Ohmstedt, en même temps que Sancho Panza ; Origin of Cigar rapporte aussi la version de ceux qui font d''Antonio Allones lui-même le fondateur en 1848. Habanos date de 1882 le lancement, sous Antonio Allones, qui faisait déjà des cigares à La Havane depuis plus de trente ans, d''une marque de qualité et de prix élevés dont le nom fut vite connu pour son prestige.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Le nom claque comme une enseigne du XIXe siècle, et c''en est une : « le roi du monde », déposé en 1848 par Emilio Ohmstedt, à une époque où l''on ne reculait devant aucune emphase pour vendre du tabac. La marque fut longtemps l''une des plus chères de La Havane, réputée pour la sélection de ses feuilles plus que pour la puissance de ses assemblages.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The name means the king of the world. Wikipedia and Origin of Cigar write that the brand is said to have been created in 1848 by the German Emilio Ohmstedt, at the same time as Sancho Panza; Origin of Cigar also reports the version of those who make Antonio Allones himself the founder in 1848. Habanos dates to 1882 the launch, under Antonio Allones, who had already been making cigars in Havana for more than thirty years, of a brand of high quality and high prices whose name was soon known for its prestige.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The name cracks like a nineteenth-century shop sign, and that is exactly what it is: "the king of the world", registered in 1848 by Emilio Ohmstedt, at a time when no emphasis was too great for selling tobacco. The brand was long one of the most expensive in Havana, esteemed for the selection of its leaves rather than for the power of its blends.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('El nombre significa el rey del mundo. Wikipedia y Origin of Cigar escriben que la marca habría sido creada en 1848 por el alemán Emilio Ohmstedt, al mismo tiempo que Sancho Panza; Origin of Cigar recoge también la versión de quienes hacen del propio Antonio Allones el fundador en 1848. Habanos fecha en 1882 el lanzamiento, bajo Antonio Allones, que ya hacía puros en La Habana desde hacía más de treinta años, de una marca de calidad y precios elevados cuyo nombre fue pronto conocido por su prestigio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('El nombre restalla como un rótulo del siglo XIX, y eso es exactamente lo que es: «el rey del mundo», registrado en 1848 por Emilio Ohmstedt, en una época en la que no se retrocedía ante ninguna énfasis para vender tabaco. La marca fue durante mucho tiempo una de las más caras de La Habana, reputada por la selección de sus hojas más que por la potencia de sus ligas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Der Name bedeutet der König der Welt. Wikipedia und Origin of Cigar schreiben, die Marke sei 1848 vom Deutschen Emilio Ohmstedt geschaffen worden, zeitgleich mit Sancho Panza; Origin of Cigar gibt auch die Version derer wieder, die Antonio Allones selbst zum Gründer im Jahr 1848 machen. Habanos datiert auf 1882 die Einführung, unter Antonio Allones, der schon seit mehr als dreißig Jahren in Havanna Zigarren herstellte, einer Marke von hoher Qualität und hohem Preis, deren Name rasch für sein Prestige bekannt wurde.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Der Name knallt wie ein Ladenschild des 19. Jahrhunderts, und genau das ist er: „der König der Welt“, 1848 von Emilio Ohmstedt eingetragen, zu einer Zeit, in der man vor keinem Pathos zurückschreckte, um Tabak zu verkaufen. Die Marke war lange eine der teuersten Havannas, geschätzt für die Auswahl ihrer Blätter mehr als für die Kraft ihrer Blends.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('这个名字的意思是世界之王。维基百科和 Origin of Cigar 写道，该品牌据称由德国人 Emilio Ohmstedt 于1848年创制，与 Sancho Panza 同时；Origin of Cigar 还转述了另一种说法，即把 Antonio Allones 本人视为1848年的创始人。Habanos 把1882年定为推出时间，当时由 Antonio Allones 主持，他在哈瓦那制作雪茄已超过三十年，推出的是一个品质与价格都高的品牌，其名号很快因声望而闻名。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('这名字像十九世纪的店招一样脆响，而它确实就是：「世界之王」，1848年由埃米利奥·奥姆施泰特注册，那个年代为卖烟草不惜任何夸张之辞。这个品牌长期是哈瓦那最昂贵者之一，其名声来自选叶，而非配方的力度。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('يعني الاسم ملك العالم. تكتب ويكيبيديا وOrigin of Cigar أنّ العلامة يُقال إنها أُنشئت سنة 1848 على يد الألماني Emilio Ohmstedt، في الوقت نفسه مع Sancho Panza؛ وتنقل Origin of Cigar أيضاً رواية من يجعلون Antonio Allones نفسه المؤسّس سنة 1848. وتؤرّخ Habanos لإطلاق العلامة بسنة 1882، في عهد Antonio Allones الذي كان يصنع السيجار في هافانا منذ ما يزيد على ثلاثين سنة، وهي علامة رفيعة الجودة والسعر ذاع اسمها سريعاً بما لها من مكانة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('الاسم يطقطق كلافتة متجر من القرن التاسع عشر، وهو كذلك فعلاً: «ملك العالم»، سُجّل سنة 1848 على يد إميليو أومشتيت، في زمن لم يكن يُتورَّع فيه عن أي مبالغة لبيع التبغ. وكانت العلامة طويلاً من أغلى علامات هافانا، تُعرف بانتقاء أوراقها أكثر مما تُعرف بقوّة خلطاتها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos la dit de saveur légère à moyenne, en feuilles de la Vuelta Abajo, roulée à la main en tripe longue. Habanos écrit aussi que la marque a souvent servi pour des éditions régionales. Wikipédia écrit qu''elle resta populaire pendant les années 1960 et 1970.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('C''est précisément ce qui la rend intéressante aujourd''hui. El Rey del Mundo appartient au registre doux à médium du portefeuille cubain — celui que la mode des années 2000, tournée vers les assemblages de plus en plus forts, a laissé de côté. La marque n''a pas suivi ; elle a gardé un profil de bois blond, de foin sec et d''amande, avec une longueur en bouche qui doit tout à la qualité de la matière et rien à l''intensité.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos describes it as light to medium in flavour, in leaves from the Vuelta Abajo, hand-rolled with long filler. Habanos also writes that the brand has often been used for regional editions. Wikipedia writes that it remained popular during the 1960s and 1970s.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('That is precisely what makes it interesting today. El Rey del Mundo belongs to the mild-to-medium register of the Cuban portfolio — the one the fashion of the 2000s, turned towards ever stronger blends, left aside. The brand did not follow; it kept a profile of pale wood, dry hay and almond, with a length on the palate that owes everything to the quality of the material and nothing to intensity.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos la dice de sabor ligero a medio, en hojas de la Vuelta Abajo, liada a mano con tripa larga. Habanos escribe también que la marca ha servido a menudo para ediciones regionales. Wikipedia escribe que siguió siendo popular durante los años sesenta y setenta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Es precisamente eso lo que la hace interesante hoy. El Rey del Mundo pertenece al registro suave a medio del portafolio cubano — aquel que la moda de los años dos mil, volcada en ligas cada vez más fuertes, dejó de lado. La marca no siguió; conservó un perfil de madera clara, heno seco y almendra, con una longitud en boca que se lo debe todo a la calidad de la materia y nada a la intensidad.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos bezeichnet sie als von leichtem bis mittlerem Geschmack, aus Blättern der Vuelta Abajo, von Hand mit Longfiller gerollt. Habanos schreibt außerdem, die Marke habe oft für regionale Editionen gedient. Wikipedia schreibt, sie sei in den 1960er und 1970er Jahren beliebt geblieben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Genau das macht sie heute interessant. El Rey del Mundo gehört zum milden bis mittleren Register des kubanischen Sortiments — jenem, das die Mode der 2000er Jahre mit ihren immer kräftigeren Blends links liegen ließ. Die Marke folgte nicht; sie behielt ein Profil aus hellem Holz, trockenem Heu und Mandel, mit einer Länge am Gaumen, die alles der Qualität des Materials und nichts der Intensität verdankt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos 称其风味轻至中等，采用 Vuelta Abajo 的叶片，手工长茄芯卷制。Habanos 还写道，该品牌常用于地区限量版。维基百科写道，它在1960年代和1970年代依然广受欢迎。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('而这恰恰是它今天有意思的地方。世界之王属于古巴产品序列中偏柔至中度的路数——正是2000年代那股愈发追求浓烈的风潮所忽略的一路。这个品牌没有跟随；它保住了浅色木质、干草与杏仁的风格，口中的绵长全然来自原料的品质，与强度无关。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تصفها Habanos بأنها خفيفة إلى متوسطة النكهة، من أوراق Vuelta Abajo، ملفوفة يدوياً بحشوة طويلة. وتكتب Habanos أيضاً أنّ العلامة استُخدمت كثيراً في إصدارات إقليمية. وتكتب ويكيبيديا أنها ظلّت رائجة في ستينيات القرن العشرين وسبعينياته.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وهذا تحديداً ما يجعلها مثيرة للاهتمام اليوم. تنتمي «إل ري ديل موندو» إلى المستوى اللطيف-المتوسط في المحفظة الكوبية — ذاك الذي تركته جانباً موضةُ الألفية المتّجهة إلى خلطات أقوى فأقوى. لم تسايرها العلامة؛ بل احتفظت بطابع من خشب فاتح وقشّ جافّ ولوز، بطول في الفم يدين بكل شيء لجودة المادة ولا شيء للشدّة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Origin of Cigar écrit, en décembre 2025, que la gamme standard ne compte que le Choix Suprême et le Demi Tasse. Le Choix Suprême est un Hermoso No.4, 127 mm pour un cepo 48, et le Demi Tasse une Entreacto, 98 mm pour un cepo 30, selon la reprise de Wikipédia par Alchetron.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La gamme s''est réduite au fil des décennies, comme celle de plusieurs marques historiques que Habanos a resserrées. Le Choix Suprême, un Hermoso No.4, en reste l''expression la plus connue : un format court, régulier, qui se fume en une heure et ne demande pas d''estomac plein.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Origin of Cigar writes, in December 2025, that the standard range includes only the Choix Suprême and the Demi Tasse. The Choix Suprême is an Hermoso No.4, 127 mm with a cepo of 48, and the Demi Tasse an Entreacto, 98 mm with a cepo of 30, according to Alchetron''s reuse of Wikipedia.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The range has shrunk over the decades, like that of several historic brands Habanos has tightened. The Choix Suprême, an Hermoso No.4, remains its best-known expression: a short, even format, smoked in an hour, that does not require a full stomach.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Origin of Cigar escribe, en diciembre de 2025, que la gama estándar solo cuenta con el Choix Suprême y el Demi Tasse. El Choix Suprême es un Hermoso No.4, 127 mm para un cepo 48, y el Demi Tasse un Entreacto, 98 mm para un cepo 30, según la reutilización de Wikipedia por Alchetron.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La gama se ha reducido con las décadas, como la de varias marcas históricas que Habanos ha estrechado. El Choix Suprême, un Hermoso No.4, sigue siendo su expresión más conocida: un formato corto y regular, que se fuma en una hora y no exige el estómago lleno.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Origin of Cigar schreibt im Dezember 2025, das Standardsortiment umfasse nur die Choix Suprême und den Demi Tasse. Die Choix Suprême ist ein Hermoso No.4, 127 mm bei Cepo 48, und der Demi Tasse ein Entreacto, 98 mm bei Cepo 30, nach der Übernahme von Wikipedia durch Alchetron.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Das Sortiment ist über die Jahrzehnte geschrumpft, wie das mehrerer historischer Marken, die Habanos gestrafft hat. Die Choix Suprême, eine Hermoso No.4, bleibt ihr bekanntester Ausdruck: ein kurzes, gleichmäßiges Format, in einer Stunde geraucht, das keinen vollen Magen verlangt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Origin of Cigar 于2025年12月写道，标准产品线只有 Choix Suprême 和 Demi Tasse。据 Alchetron 转载的维基百科，Choix Suprême 是 Hermoso No.4，127 mm、cepo 48；Demi Tasse 是 Entreacto，98 mm、cepo 30。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('几十年来其产品线不断收缩，正如哈瓦那雪茄公司精简过的几个历史品牌。Choix Suprême（一款 Hermoso No.4）仍是它最知名的表达：短小而均匀，一小时抽完，不需要先吃饱。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تكتب Origin of Cigar، في ديسمبر 2025، أنّ التشكيلة القياسية لا تضمّ سوى Choix Suprême وDemi Tasse. وChoix Suprême هو Hermoso No.4 طوله 127 mm بقياس cepo 48، وDemi Tasse هو Entreacto طوله 98 mm بقياس cepo 30، بحسب نقل Alchetron عن ويكيبيديا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('تقلّصت التشكيلة عبر العقود، كما تقلّصت تشكيلات علامات تاريخية عدّة ضغطتها «هابانوس». ويبقى «شوا سوبريم»، وهو «إيرموسو رقم 4»، تعبيرها الأشهر: مقاس قصير منتظم، يُدخَّن في ساعة ولا يستدعي معدة ممتلئة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Il existe un autre El Rey del Mundo, hondurien, fait par la famille Villazon, dit Wikipédia : c''est un autre cigare, et la présente fiche ne concerne que la marque cubaine de Habanos S.A.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Une marque de connaisseurs, donc — au sens le moins snob du terme : celle qu''on redécouvre quand on se lasse de chercher la force.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('There is another El Rey del Mundo, Honduran, made by the Villazon family, says Wikipedia: it is a different cigar, and this entry concerns only the Cuban brand of Habanos S.A.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('A connoisseur''s brand, then — in the least snobbish sense of the word: the one you rediscover when you tire of looking for strength.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
UNION ALL SELECT 'El Rey del Mundo', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Existe otro El Rey del Mundo, hondureño, hecho por la familia Villazon, dice Wikipedia: es otro puro, y esta ficha solo concierne a la marca cubana de Habanos S.A.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'El Rey del Mundo'
