UNION ALL SELECT 'libre : 1882 selon Habanos, 1848 selon Wikipédia', 'es', 'dictionnaire', ((SELECT COUNT(*) FROM `content_translations` WHERE `source_hash` = SHA1('1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos') AND `lang` = 'es' AND CAST(`target_text` AS BINARY) = CAST('1882 según Habanos, 1848 según Wikipedia; fábrica madre no nombrada por Habanos' AS BINARY)) = 1) FROM (SELECT 1 AS un) AS _x
UNION ALL SELECT 'libre : 1882 selon Habanos, 1848 selon Wikipédia', 'de', 'dictionnaire', ((SELECT COUNT(*) FROM `content_translations` WHERE `source_hash` = SHA1('1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos') AND `lang` = 'de' AND CAST(`target_text` AS BINARY) = CAST('1882 laut Habanos, 1848 laut Wikipedia; Mutterfabrik von Habanos nicht genannt' AS BINARY)) = 1) FROM (SELECT 1 AS un) AS _x
UNION ALL SELECT 'libre : 1882 selon Habanos, 1848 selon Wikipédia', 'zh', 'dictionnaire', ((SELECT COUNT(*) FROM `content_translations` WHERE `source_hash` = SHA1('1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos') AND `lang` = 'zh' AND CAST(`target_text` AS BINARY) = CAST('据 Habanos 为1882年，据维基百科为1848年；Habanos 未点名母厂' AS BINARY)) = 1) FROM (SELECT 1 AS un) AS _x
UNION ALL SELECT 'libre : 1882 selon Habanos, 1848 selon Wikipédia', 'ar', 'dictionnaire', ((SELECT COUNT(*) FROM `content_translations` WHERE `source_hash` = SHA1('1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos') AND `lang` = 'ar' AND CAST(`target_text` AS BINARY) = CAST('1882 بحسب Habanos، 1848 بحسب ويكيبيديا؛ مصنع أمّ لم تسمّه Habanos' AS BINARY)) = 1) FROM (SELECT 1 AS un) AS _x;
SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme', 'celebrities', 'pairings') AND b.`name` IN ('Ramón Allones','Vegas Robaina','Vegueros','José L. Piedra','Quintero','Diplomáticos','Cuaba','El Rey del Mundo')) = 0 AS sceaux_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` p ON p.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(p.`notes`) AND p.`id` IN ('cuba')) = 0 AS sceaux_pays_a_jour,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 264') AS journal_non_tronque;
